"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { useRouter } from "next/navigation";
import { deleteStudentAction, updateStudentAction, saveSessionContent, assignStudentTrack, removeStudentTrack, bulkAssignTrack, assignInstructorTrack, removeInstructorTrack, setInstructorRole } from "./actions";
import type { SessionResource, StudentTrackRow, InstructorTrackRow } from "./actions";
import { canManageStudents, canSwitchPrograms, canViewInsights } from "@/lib/roles";
import { UserCheck, ClipboardText as ClipboardList, Coffee } from "@phosphor-icons/react";
import { buttonClass, type SaveState } from "@/components/ui";
import { PageHeader } from "@/components/page-header";
import type { CourseSidebar } from "@/lib/course-needs";
import { type CourseEngagementProps } from "@/components/stats/course-engagement";
import type { EngagementAnalytics } from "./actions-analytics";
import type { CoursesAnalytics } from "./actions-courses";
import { TrackOverviewForm } from "./track-overview-form";
import type { PendingPerson } from "@/lib/people-hub";
import type { InsightsData } from "./page";
import type { Student } from "@/lib/types";
import { isStorageUrl, isUploadedVideo } from "@/lib/storage-utils";
import { type CohortRow, type StudentRow, type AdminTrackConfig, type AdminSession, type AdminWeek, type SessionContentMap, buildInitialWeeks, applyContentMap, tagSessionResources, getTrackIcon } from "./admin-shared";
import { AdminTopTabs } from "./admin-top-tabs";
import { StudentWorkTab } from "./student-work-tab";
import { PeopleTab } from "./people-tab";
import { HomeTab } from "./home-tab";
import { TrackView } from "./track-view";
import { AttendanceOverviewTab } from "./attendance-overview-tab";
import { LunchLearnTab } from "./lunch-learn-tab";
import { AnalyticsTab } from "./analytics-tab";
import { CourseProgressTab } from "./course-progress-tab";
import { InsightsTab } from "./insights-tab";

// ─── Main Component ───────────────────────────────────────────────────────────

export function AdminTabs({
  cohorts,
  students: initialStudents,
  tracks,
  studentTracks: initialStudentTracks,
  instructorTracks: initialInstructorTracks = [],
  programSlug: initialProgramSlug,
  surveyConfigs,
  trackPublicSurveys = [],
  userRole = "admin",
  isMaster = false,
  assignableRoles = [],
  engagementScores = {},
  courseStats = {},
  initialTab,
  initialTrackView,
  initialStudentSubView,
  signupsPanel,
  lunchLearnRecordings = [],
  insightsData = null,
  switchablePrograms = [],
  hiddenCourseCount = 0,
  analyticsData = null,
  analyticsCourse,
  coursesData = null,
  courseEngagement = null,
  attendanceRates = null,
  trackAnsweredSurveyIds = null,
  trackEnrolledCount = 0,
  trackPulseLatest = null,
  trackSurveyRespondents = {},
  pendingPeople = [],
  alumniEnrollments = [],
  unviewedAssessments = 0,
  launchReadiness = {},
  courseNeeds = {},
  trackExams = [],
}: {
  cohorts: CohortRow[];
  students: StudentRow[];
  tracks: AdminTrackConfig[];
  studentTracks: StudentTrackRow[];
  instructorTracks?: InstructorTrackRow[];
  programSlug: string;
  surveyConfigs: {
    id: string;
    title: string;
    skipForTracks?: string[];
    appliesToTracks?: string[];
    appliesToPrograms?: string[];
  }[];
  trackPublicSurveys?: { id: string; title: string; count: number }[];
  userRole?: string;
  isMaster?: boolean;
  assignableRoles?: string[];
  engagementScores?: Record<string, { total: number; attendance: number; submissions: number; reflections: number; videos: number }>;
  /** Server-computed enrolled/active/completed per track. See getCourseRosterStats. */
  courseStats?: Record<
    string,
    { total: number; active: number; fullAttendance: number | null; sessionsHeld: number; certificates?: number }
  >;
  initialTab?: string;
  initialTrackView?: string;
  /** Which Students sub-view to open (roster / attendance / progress / work /
   *  certificates), so a linked-to number lands on the list behind it. */
  initialStudentSubView?: string;
  /** Server-rendered Signups sub-view; set only while ?sub=signups is open. */
  signupsPanel?: React.ReactNode;
  lunchLearnRecordings?:{ id: string; title: string; presenter: string; recording_url: string; description: string | null; recorded_at: string }[];
  insightsData?: InsightsData | null;
  analyticsData?: EngagementAnalytics | null;
  /** Shared Analytics course scope (?course=), applied to the funnel + table. */
  analyticsCourse?: string;
  coursesData?: CoursesAnalytics | null;
  courseEngagement?: CourseEngagementProps | null;
  /** Per-learner attendance for the open course — roster badge. */
  attendanceRates?: { held: number; attended: Record<string, number> } | null;
  /** Programs a super-admin can switch into, for the no-program empty state. */
  switchablePrograms?: { slug: string; name: string }[];
  /** Courses the CURRENT program owns that are hidden. Non-zero means the
   *  empty state is a hide/show state, not a program with no courses. */
  hiddenCourseCount?: number;
  /** Survey Insights narrowed to the open course's roster; null off the course Surveys view. */
  /** Auth surveys with ≥1 response from the open course's students; null off track tabs. */
  trackAnsweredSurveyIds?: string[] | null;
  /** Enrolled learners in the open course — response-rate denominator. */
  trackEnrolledCount?: number;
  trackPulseLatest?: { week: number; session: number; answered: number; enrolled: number } | null;
  /** survey id → distinct learners from this course who answered it. */
  trackSurveyRespondents?: Record<string, number>;
  pendingPeople?: PendingPerson[];
  alumniEnrollments?: { track_slug: string; email: string; source: string }[];
  unviewedAssessments?: number;
  /** Pre-launch checks per track, present only for courses near their start
   *  date. See lib/launch-readiness. */
  launchReadiness?: Record<string, { label: string; ok: boolean; detail: string; action?: "send-invites" }[]>;
  courseNeeds?: Record<string, CourseSidebar>;
  /** The open course's practice exams, rendered as rows in the Surveys list. */
  trackExams?: { id: string; title: string; attempted: number }[];
}) {
  const router = useRouter();
  const programSlug = initialProgramSlug;
  // Capability-driven, so it follows ROLE_CAPABILITIES: admin and super_admin
  // both manage people (the ladder is cumulative), plus the master owner.
  const isManager = canManageStudents(userRole) || isMaster;
  // Courses for the shared Analytics scope selector (slug + display name).
    // Programs like Catalyst (apex) don't have a learner dashboard — no
  // tracks, no cohorts. They render a single empty-state pointer to
  // Survey Insights via the `insights` tab.
  const isDashboardless = tracks.length === 0 && cohorts.length === 0;
  // Nothing visible, but the program does own courses — they're just hidden.
  const allCoursesHidden = isDashboardless && hiddenCourseCount > 0;
  // Build tab list dynamically. The old "Program" Overview tab is gone —
  // it duplicated /dashboard/insights for super-admins and was a wasted
  // landing for managers. Admins now land directly on People (or first
  // track for instructors).
  const tabs = isDashboardless
    ? []
    : [
        ...tracks.map((t, i) => ({ id: t.slug, label: t.shortName, icon: getTrackIcon(i) })),
        // Cross-course rollups are a manager tool; an instructor's course tab
        // already holds its own Students / Attendance / Progress / Work views.
        ...(isManager
          ? [
              { id: "student-work", label: "Student Work", icon: ClipboardList },
              { id: "attendance", label: "Analytics", icon: UserCheck },
              { id: "lunch-learn", label: "Lunch & Learn", icon: Coffee },
            ]
          : []),
      ];

  // Default landing is the Admin Home picker — a grid of cards that lets
  // the admin choose what to manage. People + Student Work + Attendance +
  // Lunch & Learn are still reachable from the picker's secondary links
  // (or via direct URL), they're just not the default surface anymore.
  // Instructors with assigned tracks still land on the picker so the URL
  // pattern stays consistent — they'll see only the tracks they teach.
  const defaultTab = "home";

  // A ?tab= that matches neither a fixed tab nor one of THIS program's tracks
  // (stale bookmark, back-button into another program's course, hidden course)
  // must not render a dead blank view — fall back to the home picker.
  const FIXED_TABS = new Set([
    "home", "students", "student-work", "attendance", "insights",
    "analytics", "course-progress", "lunch-learn",
  ]);
  const normalizeTab = (t: string) =>
    FIXED_TABS.has(t) || tracks.some((tr) => tr.slug === t) ? t : defaultTab;

  const [tab, setTab] = useState<string>(normalizeTab(initialTab || defaultTab));
  const [liveTrackNames, setLiveTrackNames] = useState<Record<string, { name: string; instructor: string }>>({});

  // When the browser restores this page from its back-forward cache (bfcache),
  // the JS heap is frozen in time and router.refresh() on another page doesn't
  // help. Detect restoration via pageshow and force a fresh fetch.
  useEffect(() => {
    const handlePageShow = (e: PageTransitionEvent) => {
      if (e.persisted) router.refresh();
    };
    // Next's client router restores back/forward from its own cache without
    // re-fetching — stale when the program cookie changed in between (switch
    // program, hit back). The URL is identical across programs, so only a
    // refresh can reconcile the view with the current cookie.
    const handlePopState = () => router.refresh();
    window.addEventListener("pageshow", handlePageShow);
    window.addEventListener("popstate", handlePopState);
    return () => {
      window.removeEventListener("pageshow", handlePageShow);
      window.removeEventListener("popstate", handlePopState);
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Sync tab state when the URL ?tab= param changes (sidebar nav clicks).
  // Critical: when the URL switches BACK to /dashboard/admin with no ?tab=
  // (e.g. clicking the Admin sidebar item after viewing Insights), the
  // component used to keep its previous tab state — which rendered the
  // old view with empty server data and looked like a load failure. Now
  // we reset to the default tab whenever initialTab is absent.
  useEffect(() => {
    const next = normalizeTab(initialTab || defaultTab);
    if (next !== tab) setTab(next);
  }, [initialTab]); // eslint-disable-line react-hooks/exhaustive-deps

  const [students, setStudents] = useState(initialStudents);
  // Client-side nav between tabs (e.g. Engagement -> Attendance) re-runs the
  // server load with a different roster, but useState keeps its FIRST value —
  // so landing on a tab that doesn't fetch students (Engagement/Survey insights)
  // and then opening Attendance showed "0 students". Adopt the server roster
  // whenever its membership changes; identical rosters are left alone so
  // optimistic in-tab edits (add/remove/rename) aren't clobbered by ref churn.
  useEffect(() => {
    setStudents((prev) => {
      if (
        prev.length === initialStudents.length &&
        prev.every((s, i) => s.id === initialStudents[i]?.id)
      ) {
        return prev;
      }
      return initialStudents;
    });
  }, [initialStudents]);
  const [studentSaving, setStudentSaving] = useState<string | null>(null);

  // Track data: keyed by track slug
  const [trackData, setTrackData] = useState<Record<string, AdminWeek[]>>(() => {
    const initial: Record<string, AdminWeek[]> = {};
    for (const t of tracks) {
      initial[t.slug] = buildInitialWeeks(t);
    }
    return initial;
  });

  // Per-track, per-week save state
  const [saveStates, setSaveStates] = useState<Record<string, Record<number, SaveState>>>({});
  const saveTimers = useRef<Record<string, Record<number, ReturnType<typeof setTimeout>>>>({});

  useEffect(() => {
    const timers = saveTimers;
    return () => {
      for (const trackTimers of Object.values(timers.current)) {
        Object.values(trackTimers).forEach(clearTimeout);
      }
    };
  }, []);


  // Track which slugs have already been loaded so router.refresh() calls
  // (triggered by TrackOverviewForm autosave) don't re-fetch and overwrite
  // text the admin is actively editing.
  const loadedSlugs = useRef<Set<string>>(new Set());

  // Load initial session content from the API for all tracks
  useEffect(() => {
    async function loadContent(track: AdminTrackConfig) {
      // Only load once per slug. router.refresh() creates a new `tracks`
      // array reference on every re-render, which would otherwise re-trigger
      // this effect and reset in-progress edits before the 800ms save fires.
      if (loadedSlugs.current.has(track.slug)) return;
      // Home/insights tabs serialize tracks with weeks: [] to slim the
      // payload. Fetching now would apply DB content onto an empty base, and
      // the loadedSlugs guard above would then block the retry when the full
      // config arrives — leaving the curriculum permanently blank. Defer
      // until the track tab's server render provides the real weeks.
      if (!track.weeks.length) return;
      loadedSlugs.current.add(track.slug);
      try {
        const res = await fetch(`/api/session-content?track=${track.slug}`);
        if (!res.ok) return;
        const json = await res.json() as { rows: Array<{
          week_number: number;
          meeting_link: string | null;
          recording_url: string | null;
          meeting_link_2: string | null;
          recording_url_2: string | null;
          meeting_link_3: string | null;
          recording_url_3: string | null;
          status: string | null;
          status_2: string | null;
          status_3: string | null;
          resources: SessionResource[];
          title: string | null;
          subtitle: string | null;
          description: string | null;
          objectives: string[] | null;
          homework_instructions: string | null;
          homework_instructions_2: string | null;
          homework_instructions_3: string | null;
        }> };
        const map: SessionContentMap = {};
        for (const row of json.rows) {
          map[row.week_number] = {
            meeting_link: row.meeting_link ?? "",
            recording_url: row.recording_url ?? "",
            meeting_link_2: row.meeting_link_2 ?? "",
            recording_url_2: row.recording_url_2 ?? "",
            meeting_link_3: row.meeting_link_3 ?? "",
            recording_url_3: row.recording_url_3 ?? "",
            status: row.status ?? "upcoming",
            status_2: row.status_2 ?? "upcoming",
            status_3: row.status_3 ?? "upcoming",
            resources: row.resources ?? [],
            title: row.title ?? null,
            subtitle: row.subtitle ?? null,
            description: row.description ?? null,
            objectives: row.objectives ?? null,
            homework_instructions: row.homework_instructions ?? null,
            homework_instructions_2: row.homework_instructions_2 ?? null,
            homework_instructions_3: row.homework_instructions_3 ?? null,
          };
        }
        setTrackData((prev) => {
          // The home tab serializes tracks with weeks:[] to reduce payload.
          // When the user navigates to a track tab the server re-renders with
          // full week config — the tracks prop updates, this effect re-runs,
          // and prev[slug] may still be [] from the initial mount. Use the
          // current track config as the base in that case so the curriculum
          // renders correctly without requiring a manual refresh.
          const base = prev[track.slug]?.length ? prev[track.slug] : buildInitialWeeks(track);
          return { ...prev, [track.slug]: applyContentMap(base, map) };
        });
      } catch {
        // API unavailable — still rebuild weeks from config if empty so the
        // curriculum accordion shows up even without DB content.
        setTrackData((prev) => {
          if (!prev[track.slug]?.length && track.weeks.length) {
            return { ...prev, [track.slug]: buildInitialWeeks(track) };
          }
          return prev;
        });
      }
    }
    for (const t of tracks) {
      loadContent(t);
    }
  }, [tracks]);

  // ── Debounced save for any track ──────────────────────────────────────────

  const scheduleSave = useCallback((trackSlug: string, weekNum: number, weekData: AdminWeek) => {
    if (!saveTimers.current[trackSlug]) saveTimers.current[trackSlug] = {};
    clearTimeout(saveTimers.current[trackSlug][weekNum]);
    setSaveStates((s) => ({ ...s, [trackSlug]: { ...s[trackSlug], [weekNum]: "saving" } }));

    saveTimers.current[trackSlug][weekNum] = setTimeout(async () => {
      try {
        const allResources = tagSessionResources(weekData.sessions);
        const objectivesArr = weekData.overrideObjectives.trim()
          ? weekData.overrideObjectives.split("\n").map((s) => s.trim()).filter(Boolean)
          : null;
        await saveSessionContent(trackSlug, weekNum, {
          meeting_link: weekData.sessions[0]?.meetingLink ?? "",
          recording_url: weekData.sessions[0]?.recordingUrl ?? "",
          meeting_link_2: weekData.sessions[1]?.meetingLink ?? "",
          recording_url_2: weekData.sessions[1]?.recordingUrl ?? "",
          meeting_link_3: weekData.sessions[2]?.meetingLink ?? "",
          recording_url_3: weekData.sessions[2]?.recordingUrl ?? "",
          status: weekData.sessions[0]?.status ?? "upcoming",
          status_2: weekData.sessions[1]?.status ?? "upcoming",
          status_3: weekData.sessions[2]?.status ?? "upcoming",
          title: weekData.overrideTitle || null,
          subtitle: weekData.overrideSubtitle || null,
          description: weekData.overrideDescription || null,
          objectives: objectivesArr,
          homework_instructions: weekData.sessions[0]?.homework || null,
          homework_instructions_2: weekData.sessions[1]?.homework || null,
          homework_instructions_3: weekData.sessions[2]?.homework || null,
          resources: allResources,
        }, programSlug);
        setSaveStates((s) => ({ ...s, [trackSlug]: { ...s[trackSlug], [weekNum]: "saved" } }));
        setTimeout(() => setSaveStates((s) => ({ ...s, [trackSlug]: { ...s[trackSlug], [weekNum]: "idle" } })), 2000);
      } catch (err) {
        console.error(`[admin] ${trackSlug} week ${weekNum} save failed:`, err);
        setSaveStates((s) => ({ ...s, [trackSlug]: { ...s[trackSlug], [weekNum]: "error" } }));
      }
    }, 800);
  }, []);

  function updateSession(trackSlug: string, weekNum: number, sessionNum: number, patch: Partial<AdminSession>) {
    setTrackData((prev) => {
      const weeks = prev[trackSlug] ?? [];
      const updated = weeks.map((w) =>
        w.week === weekNum
          ? {
              ...w,
              sessions: w.sessions.map((s) =>
                s.num === sessionNum ? { ...s, ...patch } : s
              ),
            }
          : w
      );
      const week = updated.find((w) => w.week === weekNum)!;
      scheduleSave(trackSlug, weekNum, week);
      return { ...prev, [trackSlug]: updated };
    });
  }

  function updateWeekOverride(trackSlug: string, weekNum: number, patch: Partial<Pick<AdminWeek, "overrideTitle" | "overrideSubtitle" | "overrideDescription" | "overrideObjectives">>) {
    setTrackData((prev) => {
      const weeks = prev[trackSlug] ?? [];
      const updated = weeks.map((w) =>
        w.week === weekNum ? { ...w, ...patch } : w
      );
      const week = updated.find((w) => w.week === weekNum)!;
      scheduleSave(trackSlug, weekNum, week);
      return { ...prev, [trackSlug]: updated };
    });
  }

  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [addingStudent, setAddingStudent] = useState(false);
  const [addError, setAddError] = useState("");

  // Track enrollment state
  const [enrollments, setEnrollments] = useState<StudentTrackRow[]>(initialStudentTracks);
  // Same staleness trap as the roster above: client-nav between tabs re-runs
  // the server load, but useState keeps its FIRST value — arriving at
  // Attendance from a tab that doesn't fetch enrollments (Engagement/Surveys)
  // rendered every course as 0 students. Adopt the server rows whenever
  // membership changes; identical sets are left alone so optimistic in-tab
  // enrollment edits aren't clobbered.
  useEffect(() => {
    setEnrollments((prev) => {
      if (
        prev.length === initialStudentTracks.length &&
        prev.every(
          (e, i) =>
            e.student_id === initialStudentTracks[i]?.student_id &&
            e.track_slug === initialStudentTracks[i]?.track_slug,
        )
      ) {
        return prev;
      }
      return initialStudentTracks;
    });
  }, [initialStudentTracks]);
  const [instrTracks, setInstrTracks] = useState<InstructorTrackRow[]>(initialInstructorTracks);
  const [instrTrackSaving, setInstrTrackSaving] = useState<string | null>(null);
  const [enrollmentSaving, setEnrollmentSaving] = useState<string | null>(null);
  const [enrollmentFilter, setEnrollmentFilter] = useState<string>("all");
  const [bulkTrack, setBulkTrack] = useState<string>(tracks[0]?.slug ?? "");
  const [bulkSelected, setBulkSelected] = useState<Set<string>>(new Set());
  const [bulkSaving, setBulkSaving] = useState(false);

  const [showBulkAssign, setShowBulkAssign] = useState(false);

  async function updateStudent(id: string, field: "role" | "cohort_id" | "first_name" | "last_name", value: string) {
    setStudentSaving(id);
    try {
      await updateStudentAction(id, field, value);
      setStudents((prev) => prev.map((s) => (s.id === id ? { ...s, [field]: value } : s)));
    } catch (e) {
      console.error("Failed to update student:", e);
    }
    setStudentSaving(null);
  }

  async function deleteStudent(id: string) {
    setStudentSaving(id);
    try {
      await deleteStudentAction(id);
      setStudents((prev) => prev.filter((s) => s.id !== id));
    } catch (e) {
      console.error("Failed to delete student:", e);
    }
    setStudentSaving(null);
    setConfirmDelete(null);
  }

  // Track enrollment helpers
  function getStudentEnrollments(studentId: string): string[] {
    return enrollments
      .filter((e) => e.student_id === studentId)
      .map((e) => e.track_slug);
  }

  async function toggleTrackEnrollment(studentId: string, trackSlug: string) {
    setEnrollmentSaving(`${studentId}-${trackSlug}`);
    try {
      const isEnrolled = enrollments.some(
        (e) => e.student_id === studentId && e.track_slug === trackSlug
      );
      if (isEnrolled) {
        await removeStudentTrack(studentId, trackSlug, programSlug);
        setEnrollments((prev) =>
          prev.filter((e) => !(e.student_id === studentId && e.track_slug === trackSlug))
        );
      } else {
        await assignStudentTrack(studentId, trackSlug, programSlug);
        setEnrollments((prev) => [
          ...prev,
          { id: crypto.randomUUID(), student_id: studentId, track_slug: trackSlug, program_id: "", created_at: new Date().toISOString() },
        ]);
      }
    } catch (e) {
      console.error("Failed to toggle enrollment:", e);
    }
    setEnrollmentSaving(null);
  }

  async function handleBulkAssign() {
    if (bulkSelected.size === 0 || !bulkTrack) return;
    setBulkSaving(true);
    try {
      await bulkAssignTrack(Array.from(bulkSelected), bulkTrack, programSlug);
      // Add to local state
      const newRows: StudentTrackRow[] = Array.from(bulkSelected)
        .filter((sid) => !enrollments.some((e) => e.student_id === sid && e.track_slug === bulkTrack))
        .map((sid) => ({
          id: crypto.randomUUID(),
          student_id: sid,
          track_slug: bulkTrack,
          program_id: "",
          created_at: new Date().toISOString(),
        }));
      setEnrollments((prev) => [...prev, ...newRows]);
      setBulkSelected(new Set());
    } catch (e) {
      console.error("Failed to bulk assign:", e);
    }
    setBulkSaving(false);
  }

  // Instructor track helpers
  function getInstructorAssignments(instructorId: string): string[] {
    return instrTracks
      .filter((e) => e.student_id === instructorId)
      .map((e) => e.track_slug);
  }

  async function setInstructorTrackRole(instructorId: string, trackSlug: string, role: "lead" | "assistant") {
    setInstrTrackSaving(`${instructorId}-${trackSlug}-role`);
    try {
      await setInstructorRole(instructorId, trackSlug, role);
      setInstrTracks((prev) =>
        prev.map((e) => (e.student_id === instructorId && e.track_slug === trackSlug ? { ...e, role } : e)),
      );
    } catch (e) {
      console.error("Failed to set instructor role:", e);
    }
    setInstrTrackSaving(null);
  }

  async function toggleInstructorTrack(instructorId: string, trackSlug: string) {
    setInstrTrackSaving(`${instructorId}-${trackSlug}`);
    try {
      const isAssigned = instrTracks.some(
        (e) => e.student_id === instructorId && e.track_slug === trackSlug
      );
      if (isAssigned) {
        await removeInstructorTrack(instructorId, trackSlug, programSlug);
        setInstrTracks((prev) =>
          prev.filter((e) => !(e.student_id === instructorId && e.track_slug === trackSlug))
        );
      } else {
        await assignInstructorTrack(instructorId, trackSlug, programSlug);
        setInstrTracks((prev) => [
          ...prev,
          { id: crypto.randomUUID(), student_id: instructorId, track_slug: trackSlug, program_id: "", created_at: new Date().toISOString() },
        ]);
      }
    } catch (e) {
      console.error("Failed to toggle instructor track:", e);
    }
    setInstrTrackSaving(null);
  }

  // ── Find the currently selected track config ────────────────────────────
  const activeTrack = tracks.find((t) => t.slug === tab);
  const activeWeeks = trackData[tab] ?? [];

  return (
    <div>
      <div className="flex flex-col">
      <div className="min-w-0 flex-1">

      {/* Dashboardless programs (marketing apex with no tracks) have nothing
         per-track to show. Surface the next useful destinations instead. */}
      {isDashboardless && (
        <div className="space-y-4">
          {/* Two different empty states wear the same shape. A program with no
             courses at all (the marketing apex) needs the program picker. A
             program whose courses are ALL hidden needs Manage Courses — it
             used to get the picker, which switched back into the same program,
             which was still empty, so there was no way out of the loop and no
             Manage button on the screen that replaced the real admin home. */}
          <PageHeader
            eyebrow="Admin"
            title={allCoursesHidden ? "Every course here is hidden" : "No program selected"}
            subtitle={
              allCoursesHidden
                ? `This program has ${hiddenCourseCount} ${hiddenCourseCount === 1 ? "course" : "courses"}, all currently hidden, so there's nothing to manage on this screen. Show one in Manage Courses to bring the admin home back.`
                : canSwitchPrograms(userRole)
                  ? "This domain has no courses of its own. Open Manage Courses, or switch programs from your avatar menu."
                  : "This domain doesn't have a learner dashboard. Contact a super-admin to switch programs."
            }
          />
          {/* Two buttons for super-admins, whose avatar menu already switches
             programs (pills removed 2026-08-20 at Fonz's request). A
             cross-program grant holder (Jihan) has NO other switcher, so for
             them the granted programs render here — it's the only way out of
             an all-hidden home program (2026-08-24). */}
          {canManageStudents(userRole) && (
            <div className="flex flex-wrap gap-2">
              <a href="/dashboard/admin/programs" className={buttonClass("dark", "md")}>
                Manage Courses
                <span aria-hidden>&rarr;</span>
              </a>
              <a href="/dashboard/admin/programs/new" className={buttonClass("secondary", "md")}>
                New course
              </a>
            </div>
          )}
          {!canSwitchPrograms(userRole) && switchablePrograms.length > 0 && (
            <div className="space-y-2">
              <p className="text-sm text-ink-soft">Your other programs</p>
              <div className="flex flex-wrap gap-2">
                {switchablePrograms.map((p) => (
                  <a
                    key={p.slug}
                    href={`/api/switch-program?slug=${encodeURIComponent(p.slug)}&next=${encodeURIComponent("/dashboard/admin")}`}
                    className={buttonClass("secondary", "md")}
                  >
                    {p.name}
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Admin Home — the picker grid. Default landing when no ?tab= is set.
         Replaces the old crowded People-tab-as-default. Click a card to go
         into that track's per-track admin; quiet secondary links below
         cover cross-track operations (People, Student Work, Attendance,
         Lunch & Learn). */}
      {tab === "home" && !isDashboardless && (
        <HomeTab
          courseStats={courseStats}
          enrollments={enrollments}
          isManager={isManager}
          isMaster={isMaster}
          liveTrackNames={liveTrackNames}
          programSlug={programSlug}
          students={students}
          tracks={tracks}
          userRole={userRole}
        />
      )}

      {/* Track view — shows when a track is selected from the sidebar */}
      {activeTrack && (
        <TrackView
          activeTrack={activeTrack}
          initialStudentSubView={initialStudentSubView}
          signupsPanel={signupsPanel}
          initialTab={initialTab}
          initialTrackView={initialTrackView}
          activeWeeks={activeWeeks}
          assignableRoles={assignableRoles}
          attendanceRates={attendanceRates}
          cohorts={cohorts}
          courseEngagement={courseEngagement}
          courseNeeds={courseNeeds}
          deleteStudent={deleteStudent}
          engagementScores={engagementScores}
          enrollmentSaving={enrollmentSaving}
          enrollments={enrollments}
          instrTrackSaving={instrTrackSaving}
          instrTracks={instrTracks}
          isManager={isManager}
          launchReadiness={launchReadiness}
          liveTrackNames={liveTrackNames}
          programSlug={programSlug}
          router={router}
          saveStates={saveStates}
          setLiveTrackNames={setLiveTrackNames}
          setStudents={setStudents}
          studentSaving={studentSaving}
          students={students}
          surveyConfigs={surveyConfigs}
          toggleInstructorTrack={toggleInstructorTrack}
          setInstructorTrackRole={setInstructorTrackRole}
          toggleTrackEnrollment={toggleTrackEnrollment}
          trackAnsweredSurveyIds={trackAnsweredSurveyIds}
          trackEnrolledCount={trackEnrolledCount}
          trackPulseLatest={trackPulseLatest}
          trackExams={trackExams}
          trackPublicSurveys={trackPublicSurveys}
          trackSurveyRespondents={trackSurveyRespondents}
          tracks={tracks}
          updateSession={updateSession}
          updateStudent={updateStudent}
          updateWeekOverride={updateWeekOverride}
          userRole={userRole}
        />
      )}

      {/* People — compact cross-track roster */}
      {tab === "students" && (
        <div className="space-y-6">
        <AdminTopTabs current="students" showInsights={canViewInsights(userRole)} isManager={isManager} />
        <PeopleTab
          students={students}
          cohorts={cohorts}
          tracks={tracks}
          enrollments={enrollments}
          instrTracks={instrTracks}
          engagementScores={engagementScores}
          isManager={isManager}
          assignableRoles={assignableRoles}
          programSlug={programSlug}
          enrollmentSaving={enrollmentSaving}
          instrTrackSaving={instrTrackSaving}
          studentSaving={studentSaving}
          onUpdateStudent={updateStudent}
          onDeleteStudent={deleteStudent}
          onToggleStudentTrack={toggleTrackEnrollment}
          onToggleInstructorTrack={toggleInstructorTrack}
          onSetInstructorRole={setInstructorTrackRole}
          onStudentAdded={(s) => setStudents((prev) => [...prev, s])}
          pendingPeople={pendingPeople}
        />
        </div>
      )}

      {/* Standalone Student Work (from sidebar, all tracks) */}
      {tab === "student-work" && (
        <div className="space-y-6">
          <AdminTopTabs current="student-work" showInsights={canViewInsights(userRole)} isManager={isManager} />
          <StudentWorkTab tracks={tracks} programSlug={programSlug} />
        </div>
      )}

      {/* Standalone Analytics (from sidebar, all tracks) */}
      {tab === "attendance" && (
        <AttendanceOverviewTab
          enrollments={enrollments}
          isManager={isManager}
          students={students}
          tracks={tracks}
          userRole={userRole}
        />
      )}

      {/* Lunch & Learn management */}
      {tab === "lunch-learn" && <LunchLearnTab lunchLearnRecordings={lunchLearnRecordings} />}

      {/* Engagement Analytics — program-level activation funnel + per-learner
         activity. Scoped to the current program (the action enforces it), so it
         follows the program switcher rather than showing every program. */}
      {tab === "analytics" && (
        <AnalyticsTab
          analyticsCourse={analyticsCourse}
          analyticsData={analyticsData}
          isManager={isManager}
          userRole={userRole}
        />
      )}

      {/* Courses & Progress — completion funnel, distribution, and per-course /
         per-student progress. Scoped to the current program like Engagement. */}
      {tab === "course-progress" && (
        <CourseProgressTab
          coursesData={coursesData}
          isManager={isManager}
          userRole={userRole}
        />
      )}

      {/* Survey Insights — per-program survey management + cross-program
         response viewer. The Overview tab used to host the Pre/Post survey
         cards too; they were noisy there and properly belong here next to
         the response data. The bare /dashboard/insights route hosts the
         broader operational dashboard (engagement, attendance, alumni). */}
      {tab === "insights" && (
        <InsightsTab
          insightsData={insightsData}
          isManager={isManager}
          userRole={userRole}
        />
      )}
      </div>
      </div>
    </div>
  );
}
// Re-export the helper so student-facing pages can use it without importing
// from this file (avoids "use client" leaking into server components).
export { isStorageUrl, isUploadedVideo };

"use client";

import { useState, useTransition } from "react";
import { Megaphone, Trash as Trash2, Plus, CircleNotch as Loader2, PaperPlaneTilt as Send } from "@phosphor-icons/react";
import { createAnnouncement, deleteAnnouncement } from "./actions-misc";
import { humanizeSlug } from "@/lib/utils";

type Announcement = {
  id: string;
  message: string;
  track_slug: string | null;
  created_at: string;
  expires_at: string;
};

type Props = {
  announcements: Announcement[];
  tracks: { slug: string; name: string }[];
  programSlug: string;
};

export function AnnouncementsManager({ announcements: initial, tracks, programSlug }: Props) {
  const [announcements, setAnnouncements] = useState(initial);
  const [showForm, setShowForm] = useState(false);
  const [message, setMessage] = useState("");
  const [trackSlug, setTrackSlug] = useState("");
  const [expiresHours, setExpiresHours] = useState(72);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const [deleting, setDeleting] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const handleCreate = async () => {
    if (!message.trim()) return;
    setSending(true);
    setError("");
    try {
      const expiresAt = new Date(Date.now() + expiresHours * 60 * 60 * 1000).toISOString();
      await createAnnouncement({
        programSlug,
        trackSlug: trackSlug || undefined,
        message: message.trim(),
        expiresAt,
      });
      // Add to local state optimistically
      setAnnouncements((prev) => [
        {
          id: crypto.randomUUID(),
          message: message.trim(),
          track_slug: trackSlug || null,
          created_at: new Date().toISOString(),
          expires_at: expiresAt,
        },
        ...prev,
      ]);
      setMessage("");
      setTrackSlug("");
      setShowForm(false);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to create announcement");
    } finally {
      setSending(false);
    }
  };

  const handleDelete = async (id: string) => {
    setDeleting(id);
    try {
      await deleteAnnouncement(id);
      setAnnouncements((prev) => prev.filter((a) => a.id !== id));
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to delete");
    } finally {
      setDeleting(null);
    }
  };

  const trackName = (slug: string | null) => {
    if (!slug) return "All tracks";
    return tracks.find((t) => t.slug === slug)?.name ?? humanizeSlug(slug);
  };

  const expiresIn = (expiresAt: string) => {
    const hours = Math.round((new Date(expiresAt).getTime() - Date.now()) / (1000 * 60 * 60));
    if (hours <= 0) return "Expired";
    if (hours < 24) return `${hours}h left`;
    return `${Math.round(hours / 24)}d left`;
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="text-lg font-bold text-ink flex items-center gap-2">
            <Megaphone size={20} />
            Announcements
          </h2>
          <p className="text-sm text-ink-faint mt-0.5">
            Post updates to students. Track-specific announcements trigger email notifications.
          </p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="flex items-center gap-2 rounded-lg bg-ink px-4 py-2 text-sm font-semibold text-paper transition-colors hover:bg-ink-soft"
        >
          <Plus size={16} />
          New announcement
        </button>
      </div>

      {/* Error */}
      {error && (
        <div className="rounded-lg bg-red-50 border border-red-200 px-4 py-3 text-sm text-red-700">
          {error}
          <button onClick={() => setError("")} className="ml-2 underline">Dismiss</button>
        </div>
      )}

      {/* Create form */}
      {showForm && (
        <div className="panel p-4 space-y-3">
          <textarea
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            placeholder="What do you want to tell students?"
            rows={3}
            className="w-full rounded-lg border border-rule bg-paper px-3 py-2 text-sm text-ink placeholder:text-ink-faint focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--primary)] resize-none"
          />
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs font-medium text-ink-soft">Track (optional)</label>
              <select
                value={trackSlug}
                onChange={(e) => setTrackSlug(e.target.value)}
                className="mt-1 block rounded-lg border border-rule bg-paper px-3 py-2 text-sm text-ink"
              >
                <option value="">All tracks (no email)</option>
                {tracks.map((t) => (
                  <option key={t.slug} value={t.slug}>{t.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="text-xs font-medium text-ink-soft">Expires in</label>
              <select
                value={expiresHours}
                onChange={(e) => setExpiresHours(Number(e.target.value))}
                className="mt-1 block rounded-lg border border-rule bg-paper px-3 py-2 text-sm text-ink"
              >
                <option value={24}>24 hours</option>
                <option value={72}>3 days</option>
                <option value={168}>1 week</option>
                <option value={720}>30 days</option>
              </select>
            </div>
            <div className="flex-1" />
            <div className="flex gap-2">
              <button
                onClick={() => setShowForm(false)}
                className="rounded-lg border border-rule px-4 py-2 text-sm font-medium text-ink hover:bg-paper-tint transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleCreate}
                disabled={!message.trim() || sending}
                className="flex items-center gap-2 rounded-lg bg-ink px-4 py-2 text-sm font-semibold text-paper transition-colors hover:bg-ink-soft disabled:opacity-50"
              >
                {sending ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />}
                {trackSlug ? "Post & email" : "Post"}
              </button>
            </div>
          </div>
          {trackSlug && (
            <p className="text-xs text-ink-faint">
              📧 All students enrolled in <strong>{trackName(trackSlug)}</strong> will receive an email notification
              (unless they&apos;ve opted out).
            </p>
          )}
        </div>
      )}

      {/* Announcements list */}
      {announcements.length === 0 ? (
        <div className="panel p-8 text-center">
          <Megaphone size={32} className="mx-auto text-ink-faint mb-3" />
          <p className="text-sm text-ink-faint">No active announcements.</p>
        </div>
      ) : (
        <div className="space-y-2">
          {announcements.map((a) => (
            <div key={a.id} className="panel flex items-start gap-3 p-4">
              <Megaphone size={16} className="mt-0.5 shrink-0 text-ink-faint" />
              <div className="flex-1 min-w-0">
                <p className="text-sm text-ink">{a.message}</p>
                <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-ink-faint">
                  <span className="rounded bg-paper-tint px-1.5 py-0.5">{trackName(a.track_slug)}</span>
                  <span>{expiresIn(a.expires_at)}</span>
                  <span>·</span>
                  <span>{new Date(a.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</span>
                </div>
              </div>
              <button
                onClick={() => handleDelete(a.id)}
                disabled={deleting === a.id}
                className="shrink-0 rounded-lg p-2 text-ink-faint hover:bg-red-50 hover:text-red-600 transition-colors"
                title="Delete announcement"
              >
                {deleting === a.id ? <Loader2 size={14} className="animate-spin" /> : <Trash2 size={14} />}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { redirect } from "next/navigation";
import { getSessionContext } from "@/lib/auth/session";
import { canAccessAdminPanel } from "@/lib/roles";
import { getProgram } from "@/lib/programs/server";
import { createServiceClient } from "@/lib/supabase/server";
import { AnnouncementsManager } from "../announcements-manager";

export default async function AnnouncementsPage() {
  const ctx = await getSessionContext();
  if (!ctx || !canAccessAdminPanel(ctx.student?.role ?? "")) redirect("/dashboard");

  const program = await getProgram();
  const svc = createServiceClient();

  // Get program ID
  const { data: programRow } = await svc
    .from("programs")
    .select("id")
    .eq("slug", program.slug)
    .single();

  const programId = programRow?.id;

  // Get active announcements
  const { data: announcements } = programId
    ? await svc
        .from("announcements")
        .select("id, message, track_slug, created_at, expires_at")
        .eq("program_id", programId)
        .gt("expires_at", new Date().toISOString())
        .order("created_at", { ascending: false })
    : { data: [] };

  return (
    <div className="mx-auto max-w-3xl px-4 sm:px-6 py-8">
      <AnnouncementsManager
        announcements={(announcements ?? []) as any}
        tracks={program.tracks.map((t) => ({ slug: t.slug, name: t.name }))}
        programSlug={program.slug}
      />
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback, useMemo } from "react";
import { UserCheck, ArrowsClockwise as RefreshCw, CaretLeft as ChevronLeft, CaretRight as ChevronRight, Download, Check, Circle } from "@phosphor-icons/react";
import {
  type AttendanceRecord,
  type StudentRow,
  type TrackLike,
  summarizeAllStudents,
  unitHasArrived,
  weeklyAttendanceRates,
} from "@/lib/attendance/compute";
import { computeCurrentWeek, trackHasStarted, formatCohortDate } from "@/lib/utils";
import { unitDisplayMap } from "@/lib/programs/unit-display";
import { StatCard } from "@/components/stats/stat-card";
import { SectionHeadline } from "@/components/stats/section-headline";
import { ThresholdLegend, TONE_CHIP, TONE_DOT, type StatusTone } from "@/components/stats/status";
import { buttonClass, microLabel } from "@/components/ui";
import { downloadCsv } from "@/lib/csv";

type AttendanceTabProps = {
  students: StudentRow[];
  tracks: TrackLike[];
  /** Enrollment rows (student_id → track_slug). When passed, attendance is
   * scored per enrollment so a program-roster account with no enrollment (staff
   * ghost login, un-enrolled signup) doesn't surface as "missed" a track it was
   * never in. Omit for the embedded per-track view, whose students are already
   * enrollment-scoped upstream. */
  enrollments?: { student_id: string; track_slug: string }[];
  /** Used in the CSV filename + page heading. Defaults to "attendance". */
  scopeLabel?: string;
  /** When true: hides the header/title, defaults straight to mark view. */
  embedded?: boolean;
  /** Optional Roster/Attendance/Submissions switcher, shown when embedded. */
  viewSwitcher?: React.ReactNode;
  /** When true: keep the view toggle + controls but drop the title block —
   * the parent already renders a PageHeader, so showing both is a double header. */
  hideTitle?: boolean;
  /** Shared Analytics scope — pre-select this course in the overview. */
  course?: string;
};

type View = "overview" | "mark";

/** The unit's calendar date (YYYY-MM-DD) when the syllabus provides one. */
function unitDate(track: TrackLike, week: number): string | null {
  return (track.weekSummaries ?? []).find((s) => s.week === week)?.date ?? null;
}

// Threshold → semantic tone (shared TONE_CHIP/TONE_DOT classes render it).
function rateTone(rate: number): StatusTone {
  if (rate >= 80) return "success";
  if (rate >= 50) return "warning";
  return "danger";
}

const STATUS_LABEL: Record<string, { label: string; tone: StatusTone }> = {
  // Factual, non-judgmental labels — these describe attendance, not the person.
  // "Disengaged" read as an accusation on a visitor-facing screen.
  "on-track": { label: "On track", tone: "success" },
  "at-risk": { label: "Check in", tone: "warning" },
  disengaged: { label: "Low attendance", tone: "danger" },
};

export function AttendanceTab({ students, tracks, enrollments, scopeLabel, embedded, viewSwitcher, hideTitle, course }: AttendanceTabProps) {
  const startedTracks = useMemo(
    () => tracks.filter((t) => trackHasStarted(t)),
    [tracks]
  );
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [view, setView] = useState<View>(embedded ? "mark" : "overview");
  // Stores the user's explicit pick. `null` (the initial value) means
  // "fall back to the first started track." Switching tracks goes through
  // selectTrack() so we can snap the week navigator at the same time.
  const [explicitTrackSlug, setExplicitTrackSlug] = useState<string | null>(null);
  // markWeek defaults to the current week of the initial active track
  // (computed once via lazy initializer; subsequent track switches snap
  // via selectTrack()).
  const [markWeek, setMarkWeek] = useState<number>(() => {
    const initial = startedTracks[0] ?? tracks[0];
    if (!initial) return 1;
    const cw =
      initial.currentUnit ??
      computeCurrentWeek(
        initial.startDate,
        initial.totalWeeks,
        initial.lastSessionDayOffset
      );
    return Math.max(1, Math.min(cw, initial.totalWeeks));
  });
  const [savingKeys, setSavingKeys] = useState<Set<string>>(new Set());
  const filenameSlug = (scopeLabel ?? "attendance")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

  // Derive the effective active slug at render time. Falls through cleanly
  // when the user's pick goes stale (e.g. config reload removed it) without
  // needing a sync effect to "fix up" state.
  const activeTrackSlug =
    (explicitTrackSlug && tracks.some((t) => t.slug === explicitTrackSlug)
      ? explicitTrackSlug
      : course && tracks.some((t) => t.slug === course)
        ? course
        : startedTracks[0]?.slug ?? tracks[0]?.slug) ?? "";

  const activeTrack = useMemo(
    () => tracks.find((t) => t.slug === activeTrackSlug) ?? null,
    [tracks, activeTrackSlug]
  );

  // Picking a track also snaps the week navigator to that track's current
  // week — both state writes happen in the same event handler so React
  // batches them and we never need an effect to keep them in sync.
  const selectTrack = useCallback(
    (slug: string) => {
      setExplicitTrackSlug(slug);
      const t = tracks.find((x) => x.slug === slug);
      if (t) {
        const cw =
          t.currentUnit ??
          computeCurrentWeek(t.startDate, t.totalWeeks, t.lastSessionDayOffset);
        setMarkWeek(Math.max(1, Math.min(cw, t.totalWeeks)));
      }
    },
    [tracks]
  );

  const fetchRecords = useCallback(
    async (silent = false) => {
      if (silent) setRefreshing(true);
      else setLoading(true);
      try {
        if (tracks.length === 0) {
          setRecords([]);
          return;
        }
        const results = await Promise.all(
          tracks.map((t) =>
            fetch(`/api/attendance?track=${encodeURIComponent(t.slug)}`)
              .then((r) => (r.ok ? r.json() : { records: [] }))
              .catch(() => ({ records: [] }))
          )
        );
        const merged: AttendanceRecord[] = results.flatMap(
          (r: { records?: AttendanceRecord[] }) => r.records ?? []
        );
        setRecords(merged);
      } finally {
        setLoading(false);
        setRefreshing(false);
      }
    },
    [tracks]
  );

  // Initial / on-tracks-change data load. The lint rule guards against
  // cascading state updates inside effects, but loading async data IS the
  // textbook use of useEffect — fetchRecords flips loading flags and
  // populates records, which are downstream of the network response.
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void fetchRecords();
  }, [fetchRecords]);


  // studentId → set of enrolled track slugs. Undefined when no enrollments were
  // passed (embedded per-track view), which keeps the original all-tracks
  // behavior for callers that pre-scope their student list.
  const enrolledByStudent = useMemo(() => {
    if (!enrollments) return undefined;
    const m = new Map<string, Set<string>>();
    for (const e of enrollments) {
      const set = m.get(e.student_id) ?? new Set<string>();
      set.add(e.track_slug);
      m.set(e.student_id, set);
    }
    return m;
  }, [enrollments]);

  const summaries = useMemo(
    () => summarizeAllStudents(students, tracks, records, undefined, enrolledByStudent),
    [students, tracks, records, enrolledByStudent]
  );

  // Boolean lookup: did student X attend session (slug, week, n)?
  // Built once per records change, O(1) lookups during render.
  const attended = useMemo(() => {
    const set = new Set<string>();
    for (const r of records) {
      set.add(`${r.student_id}|${r.track}|${r.week_number}|${r.session_number}`);
    }
    return set;
  }, [records]);

  function isAttended(studentId: string, trackSlug: string, week: number, sess: number) {
    return attended.has(`${studentId}|${trackSlug}|${week}|${sess}`);
  }

  async function toggleAttendance(
    studentId: string,
    trackSlug: string,
    week: number,
    sess: number,
    nextValue: boolean
  ) {
    const key = `${studentId}|${trackSlug}|${week}|${sess}`;
    setSavingKeys((prev) => new Set(prev).add(key));
    // Optimistic: mutate `records` immediately so the click is instant.
    setRecords((prev) => {
      if (nextValue) {
        const optimistic: AttendanceRecord = {
          id: `optimistic-${key}-${Date.now()}`,
          student_id: studentId,
          track: trackSlug,
          week_number: week,
          session_number: sess,
          checked_in_at: new Date().toISOString(),
          marked_by: null,
        };
        return [...prev, optimistic];
      }
      return prev.filter(
        (r) =>
          !(
            r.student_id === studentId &&
            r.track === trackSlug &&
            r.week_number === week &&
            r.session_number === sess
          )
      );
    });

    try {
      const res = await fetch("/api/attendance", {
        method: nextValue ? "POST" : "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          track: trackSlug,
          week_number: week,
          session_number: sess,
          student_id: studentId,
        }),
      });
      if (!res.ok) throw new Error(`Status ${res.status}`);
    } catch {
      // Rollback by refetching that track. Cheaper than maintaining a
      // separate per-call diff and corrects any drift from concurrent edits.
      await fetchRecords(true);
    } finally {
      setSavingKeys((prev) => {
        const next = new Set(prev);
        next.delete(key);
        return next;
      });
    }
  }

  async function markAllPresent(trackSlug: string, week: number, sess: number) {
    // Find students who aren't already marked for this slot.
    const toMark = students.filter((s) => !isAttended(s.id, trackSlug, week, sess));
    if (toMark.length === 0) return;
    // Fire in parallel — the API upserts so duplicates are no-ops.
    await Promise.all(
      toMark.map((s) => toggleAttendance(s.id, trackSlug, week, sess, true))
    );
  }

  function exportCSV() {
    const trackCols = tracks.map((t) => t.shortName);
    const header = [
      "Name",
      "Email",
      "ZIP",
      "State",
      "Birthday",
      ...trackCols.map((n) => `${n} %`),
      "Overall %",
      "Sessions Attended",
      "Sessions Expected",
      "Consecutive Misses",
      "Status",
    ];
    const rows = summaries.map((s) => {
      const name =
        s.student.first_name && s.student.last_name
          ? `${s.student.first_name} ${s.student.last_name}`
          : s.student.email;
      const trackRates = tracks.map((t) => s.byTrack[t.slug]?.rate ?? "—");
      return [
        name,
        s.student.email,
        s.student.zip,
        s.student.state,
        s.student.date_of_birth,
        ...trackRates,
        s.rate,
        s.attended,
        s.expected,
        s.consecutiveMisses,
        STATUS_LABEL[s.status]?.label ?? s.status,
      ];
    });
    downloadCsv(`${filenameSlug || "attendance"}-${new Date().toISOString().slice(0, 10)}.csv`, header, rows);
  }

  if (tracks.length === 0) {
    return (
      <div className="panel p-8 text-center">
        <p className="text-sm text-ink-soft">
          No tracks configured for this view. Attendance lights up once a track
          is added.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {embedded && viewSwitcher && (
        <div className="flex flex-wrap items-center gap-2">{viewSwitcher}</div>
      )}
      {!embedded && (
        <Header
          scopeLabel={scopeLabel}
          view={view}
          setView={setView}
          refreshing={refreshing}
          onRefresh={() => void fetchRecords(true)}
          onExport={exportCSV}
          hasData={summaries.length > 0}
          hideTitle={hideTitle}
        />
      )}

      {view === "overview" ? (
        <OverviewPanel
          key={course ?? "all"}
          allTracks={tracks}
          startedTracks={startedTracks}
          students={students}
          enrolledByStudent={enrolledByStudent}
          summaries={summaries}
          records={records}
          loading={loading}
          initialCourse={course}
          onJumpToMark={(slug, week) => {
            selectTrack(slug);
            if (week) setMarkWeek(week);
            setView("mark");
          }}
        />
      ) : (
        <MarkPanel
          tracks={tracks}
          hideCoursePicker={!!course}
          startedTracks={startedTracks}
          activeTrack={activeTrack}
          activeTrackSlug={activeTrackSlug}
          selectTrack={selectTrack}
          markWeek={markWeek}
          setMarkWeek={setMarkWeek}
          students={students}
          isAttended={isAttended}
          savingKeys={savingKeys}
          onToggle={toggleAttendance}
          onMarkAllPresent={markAllPresent}
          loading={loading}
        />
      )}
    </div>
  );
}

// ─── Header ───────────────────────────────────────────────────────────────

function Header({
  scopeLabel,
  view,
  setView,
  refreshing,
  onRefresh,
  onExport,
  hasData,
  hideTitle,
}: {
  scopeLabel?: string;
  view: View;
  setView: (v: View) => void;
  refreshing: boolean;
  onRefresh: () => void;
  onExport: () => void;
  hasData: boolean;
  hideTitle?: boolean;
}) {
  // Attendance is auto-recorded from Zoom, so there's no "Take attendance"
  // action — you adjust a session by clicking its box. The only view switch
  // left is getting back from that editor to the report.
  const actions = (
    <>
      {view === "mark" && (
        <button
          type="button"
          onClick={() => setView("overview")}
          className={buttonClass("ghost", "sm")}
        >
          ← Back to report
        </button>
      )}
      <button
        type="button"
        onClick={onRefresh}
        disabled={refreshing}
        aria-label="Refresh attendance"
        className={buttonClass("ghost", "sm")}
      >
        <RefreshCw
          size={14}
          className={refreshing ? "animate-spin" : undefined}
        />
      </button>
      <button
        type="button"
        onClick={onExport}
        disabled={!hasData}
        className={buttonClass("secondary", "sm")}
      >
        <Download size={12} />
        Export CSV
      </button>
    </>
  );
  if (hideTitle) {
    return <div className="flex items-center justify-end gap-1.5">{actions}</div>;
  }
  return (
    <SectionHeadline
      eyebrow={scopeLabel || "Attendance"}
      headline={view === "overview" ? "Who's showing up" : "Mark check-ins"}
      actions={actions}
    />
  );
}

// ─── Overview ─────────────────────────────────────────────────────────────

function OverviewPanel({
  startedTracks,
  students,
  enrolledByStudent,
  summaries,
  records,
  loading,
  onJumpToMark,
  initialCourse,
  allTracks,
}: {
  startedTracks: TrackLike[];
  students: StudentRow[];
  enrolledByStudent?: Map<string, Set<string>>;
  summaries: ReturnType<typeof summarizeAllStudents>;
  records: AttendanceRecord[];
  loading: boolean;
  onJumpToMark: (slug: string, week?: number) => void;
  /** Shared Analytics scope — the ONE course picker; this panel follows it. */
  initialCourse?: string;
  /** Full track list, to name a scoped course that hasn't started yet. */
  allTracks: TrackLike[];
}) {
  // Names of who's behind stay hidden until the "Need a check-in" tile is
  // clicked — the page leads with numbers, not a wall of at-risk students.
  const [showCheckIn, setShowCheckIn] = useState(false);
  // The shared scope (top-right) is the only course selector — no second
  // dropdown here. A scoped course that hasn't started renders its own empty
  // state below instead of silently swapping to another course.
  const track = initialCourse
    ? startedTracks.find((t) => t.slug === initialCourse) ?? null
    : startedTracks[0] ?? null;

  // Scope the roster (and thus the rate + risk list) to THIS course's enrolled
  // learners, so program accounts not in the track don't drag numbers down.
  const trackStudents = useMemo(
    () =>
      track && enrolledByStudent
        ? students.filter((s) => enrolledByStudent.get(s.id)?.has(track.slug))
        : students,
    [students, enrolledByStudent, track],
  );

  const rates = useMemo(
    () => (track ? weeklyAttendanceRates(track, trackStudents, records) : []),
    [track, trackStudents, records],
  );
  const avg =
    rates.length > 0 ? Math.round(rates.reduce((a, b) => a + b, 0) / rates.length) : null;

  // Risk list scoped to this course's roster (no silent cap).
  const atRisk = useMemo(
    () =>
      summaries
        .filter((s) => s.status !== "on-track")
        .filter(
          (s) =>
            !enrolledByStudent ||
            (track ? !!enrolledByStudent.get(s.student.id)?.has(track.slug) : true),
        )
        .sort((a, b) => b.consecutiveMisses - a.consecutiveMisses || a.rate - b.rate),
    [summaries, enrolledByStudent, track],
  );

  // Loading renders nothing — a placeholder at a different height caused a
  // visible jump on the per-track view.
  if (loading) return null;

  if (startedTracks.length === 0 || (initialCourse && !track)) {
    const scopedName = initialCourse
      ? allTracks.find((t) => t.slug === initialCourse)?.name
      : null;
    return (
      <div className="panel p-6 text-center">
        <p className="mx-auto max-w-[40ch] text-sm text-ink-soft">
          {scopedName
            ? `${scopedName} hasn’t started yet — attendance opens on its first session.`
            : "No attendance to show yet. This will fill in once a session starts."}
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Headline numbers, big. "Need a check-in" is a button — click to reveal
         the names, which stay hidden by default. */}
      <div className="grid grid-cols-3 gap-3">
        <StatCard value={avg !== null ? `${avg}%` : "—"} label="Avg attendance" />
        <StatCard value={trackStudents.length} label="Students" />
        <StatCard
          value={atRisk.length}
          label="Need a check-in"
          hint={atRisk.length > 0 ? (showCheckIn ? "Hide names" : "Show names") : undefined}
          onClick={() => setShowCheckIn((v) => !v)}
          ariaExpanded={showCheckIn}
          disabled={atRisk.length === 0}
        />
      </div>

      {/* Names — revealed only when the tile is clicked. */}
      {showCheckIn && atRisk.length > 0 && (
        <div className="rounded-xl border border-rule bg-paper-tint-soft p-4">
          <p className={`mb-2.5 ${microLabel}`}>
            Check in with
          </p>
          <div className="flex flex-wrap gap-2">
            {atRisk.map((s) => {
              const name =
                s.student.first_name && s.student.last_name
                  ? `${s.student.first_name} ${s.student.last_name}`
                  : s.student.email;
              const dot = TONE_DOT[STATUS_LABEL[s.status]?.tone ?? "warning"];
              return (
                <span
                  key={s.student.id}
                  title={`${s.attended}/${s.expected} sessions · ${
                    s.consecutiveMisses > 0
                      ? `${s.consecutiveMisses} in a row missed`
                      : "no recent streak"
                  }`}
                  className="inline-flex items-center gap-1.5 rounded-full border border-rule bg-white px-3 py-1.5 text-xs font-semibold text-ink"
                >
                  <span className={`h-1.5 w-1.5 rounded-full ${dot}`} />
                  {name}
                </span>
              );
            })}
          </div>
        </div>
      )}

      {/* Weekly boxes — color + % agree; click a box to correct that session.
         Attendance is auto-recorded from Zoom, so this is a view + occasional fix. */}
      <section className="panel p-4 sm:p-5">
        <div className="mb-4">
          <ThresholdLegend
            items={[
              { tone: "success", label: "Good · 80%+" },
              { tone: "warning", label: "Watch · 50–79%" },
              { tone: "danger", label: "Low · under 50%" },
            ]}
          />
        </div>
        {rates.length === 0 ? (
          <p className="text-sm text-ink-faint">No sessions yet.</p>
        ) : (
          <div className="flex flex-wrap gap-2">
            {rates.map((rate, i) => (
              <button
                key={i}
                type="button"
                onClick={() => track && onJumpToMark(track.slug, i + 1)}
                title={`Adjust ${track?.unitLabel ?? "Week"} ${i + 1} attendance`}
                className={`group min-w-[78px] flex-1 rounded-lg px-2.5 py-3 text-center transition-shadow hover:shadow-[inset_0_0_0_1.5px_currentColor] ${TONE_CHIP[rateTone(rate)]}`}
              >
                <div className="text-lg font-extrabold leading-none tabular-nums">{rate}%</div>
                <div className="mt-1.5 inline-flex items-center gap-1 text-micro font-semibold opacity-80">
                  {track?.unitLabel ?? "Week"} {i + 1}
                  <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="opacity-60 group-hover:opacity-100">
                    <path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" />
                  </svg>
                </div>
              </button>
            ))}
          </div>
        )}
      </section>

    </div>
  );
}

// ─── Mark panel ───────────────────────────────────────────────────────────

function MarkPanel({
  tracks,
  hideCoursePicker,
  startedTracks,
  activeTrack,
  activeTrackSlug,
  selectTrack,
  markWeek,
  setMarkWeek,
  students,
  isAttended,
  savingKeys,
  onToggle,
  onMarkAllPresent,
  loading,
}: {
  tracks: TrackLike[];
  /** True when the shared Analytics scope already picks the course. */
  hideCoursePicker?: boolean;
  startedTracks: TrackLike[];
  activeTrack: TrackLike | null;
  activeTrackSlug: string;
  selectTrack: (s: string) => void;
  markWeek: number;
  setMarkWeek: (n: number) => void;
  students: StudentRow[];
  isAttended: (studentId: string, slug: string, week: number, sess: number) => boolean;
  savingKeys: Set<string>;
  onToggle: (
    studentId: string,
    slug: string,
    week: number,
    sess: number,
    nextValue: boolean
  ) => Promise<void>;
  onMarkAllPresent: (slug: string, week: number, sess: number) => Promise<void>;
  loading: boolean;
}) {
  // Return null while loading — a placeholder card sits at a different height
  // than the populated mark grid and causes a visible jump on mount.
  // The fetch is fast enough that appearing immediately is better UX.
  if (loading) return null;

  if (startedTracks.length === 0) {
    return (
      <div className="panel p-8 text-center">
        <p className="text-sm text-ink-soft">
          No tracks have started yet. Marking lights up on each track&apos;s start
          date.
        </p>
      </div>
    );
  }

  if (!activeTrack) return null;

  const totalWeeks = activeTrack.totalWeeks;
  // A session-modeled track has one session per unit; `sessionsPerWeek` there
  // is the weekly cadence, so using it would render two slots per session.
  const sessionsPerWeek =
    activeTrack.unitLabel === "Session" ? 1 : activeTrack.sessionsPerWeek;
  const unitDisplay = unitDisplayMap(activeTrack.weekSummaries ?? [], activeTrack.unitLabel ?? "Week");
  const arrived = unitHasArrived(activeTrack, markWeek);
  const markDate = unitDate(activeTrack, markWeek);

  return (
    <div className="space-y-5">
      {/* Track picker — a select, like every other scope filter (pills are
         reserved for navigation, so this can't read as yet another tab row). */}
      {!hideCoursePicker && tracks.length > 1 && (
        <label className="flex flex-col gap-1.5">
          <span className="text-micro font-semibold uppercase tracking-[0.16em] text-ink-faint">
            Course
          </span>
          <select
            value={activeTrackSlug}
            onChange={(e) => selectTrack(e.target.value)}
            className="min-w-[16rem] max-w-full rounded-lg border border-rule bg-white px-3 py-2 text-sm font-semibold text-ink focus:border-ink-faint"
          >
            {tracks.map((t) => {
              const hasStarted = trackHasStarted(t);
              return (
                <option key={t.slug} value={t.slug} disabled={!hasStarted}>
                  {t.name}
                  {hasStarted ? "" : ` · starts ${formatCohortDate(t.startDate, { month: "short", day: "numeric" })}`}
                </option>
              );
            })}
          </select>
        </label>
      )}

      {/* Week navigator */}
      <div className="flex items-center justify-between gap-3 border-y border-rule py-3">
        <button
          type="button"
          onClick={() => setMarkWeek(Math.max(1, markWeek - 1))}
          disabled={markWeek <= 1}
          aria-label="Previous week"
          className="inline-flex h-9 w-9 items-center justify-center rounded-full text-ink-soft hover:bg-paper-tint-soft hover:text-ink disabled:opacity-30 transition-colors"
        >
          <ChevronLeft size={16} />
        </button>
        <div className="text-center">
          <p className="text-micro font-semibold uppercase tracking-[0.16em] text-ink-faint">
            {activeTrack.shortName}
          </p>
          {/* Unit picker — a select, not chevrons alone: a 17-unit course
             (Security+) is unusable one week-step at a time. */}
          <select
            value={markWeek}
            onChange={(e) => setMarkWeek(Number(e.target.value))}
            aria-label="Select unit"
            className="mt-0.5 max-w-full cursor-pointer rounded-lg border border-rule bg-surface-elevated px-2 py-1 text-sm font-semibold text-ink"
          >
            {Array.from({ length: totalWeeks }, (_, i) => i + 1).map((w) => {
              const u = unitDisplay.get(w);
              const text = u?.text ?? `Week ${w}`;
              const d = unitDate(activeTrack, w);
              const future = !unitHasArrived(activeTrack, w);
              return (
                <option key={w} value={w}>
                  {text}
                  {d ? ` · ${formatCohortDate(d, { month: "short", day: "numeric" })}` : ""}
                  {future ? " · upcoming" : ""}
                </option>
              );
            })}
          </select>
        </div>
        <button
          type="button"
          onClick={() => setMarkWeek(Math.min(totalWeeks, markWeek + 1))}
          disabled={markWeek >= totalWeeks}
          aria-label="Next week"
          className="inline-flex h-9 w-9 items-center justify-center rounded-full text-ink-soft hover:bg-paper-tint-soft hover:text-ink disabled:opacity-30 transition-colors"
        >
          <ChevronRight size={16} />
        </button>
      </div>

      {/* Future units are view-only. Marking ahead of the calendar is how the
         Security+ launch data got phantom check-ins for sessions 2–6. */}
      {!arrived && (
        <p className="rounded-lg bg-paper-tint-soft px-4 py-3 text-sm text-ink-soft">
          This {(activeTrack.unitLabel ?? "week").toLowerCase()} hasn&apos;t
          happened yet
          {markDate ? ` — it meets ${formatCohortDate(markDate)}` : ""}. Marking
          opens on the day.
        </p>
      )}

      {students.length === 0 ? (
        <p className="text-sm text-ink-soft text-center py-8">
          No students in this scope yet.
        </p>
      ) : (
        <SessionTable
          track={activeTrack}
          week={markWeek}
          sessionsPerWeek={sessionsPerWeek}
          students={students}
          isAttended={isAttended}
          savingKeys={savingKeys}
          onToggle={onToggle}
          onMarkAllPresent={onMarkAllPresent}
          locked={!arrived}
        />
      )}
    </div>
  );
}

function SessionTable({
  track,
  week,
  sessionsPerWeek,
  students,
  isAttended,
  savingKeys,
  onToggle,
  onMarkAllPresent,
  locked,
}: {
  track: TrackLike;
  week: number;
  sessionsPerWeek: number;
  students: StudentRow[];
  isAttended: (studentId: string, slug: string, week: number, sess: number) => boolean;
  savingKeys: Set<string>;
  onToggle: (
    studentId: string,
    slug: string,
    week: number,
    sess: number,
    nextValue: boolean
  ) => Promise<void>;
  onMarkAllPresent: (slug: string, week: number, sess: number) => Promise<void>;
  /** True when this unit's date hasn't arrived — grid is view-only. */
  locked?: boolean;
}) {
  const sessionNumbers = Array.from({ length: sessionsPerWeek }, (_, i) => i + 1);

  return (
    <div className="overflow-hidden panel">
      {/* Header: per-session present count + "mark all" */}
      <div className="grid grid-cols-[1fr_auto] sm:grid-cols-[1fr_repeat(var(--sessions),auto)_auto] gap-x-3 items-center px-4 py-2.5 bg-paper-tint-soft border-b border-rule text-micro font-semibold uppercase tracking-[0.16em] text-ink-faint"
        style={{ ["--sessions" as string]: sessionsPerWeek }}>
        <div>Student</div>
        {sessionNumbers.map((s) => {
          const presentCount = students.filter((st) =>
            isAttended(st.id, track.slug, week, s)
          ).length;
          const allPresent = presentCount === students.length && students.length > 0;
          return (
            <div key={s} className="hidden sm:flex items-center gap-2 justify-end">
              <span className="tabular-nums normal-case font-normal text-ink-soft">
                {presentCount}/{students.length}
              </span>
              <button
                type="button"
                onClick={() => void onMarkAllPresent(track.slug, week, s)}
                disabled={allPresent || locked}
                className="rounded-full border border-rule px-2 py-0.5 text-micro font-medium text-ink-soft hover:bg-surface-elevated hover:text-ink disabled:opacity-40 transition-colors"
              >
                S{s} all
              </button>
            </div>
          );
        })}
        <div className="hidden sm:block text-right tabular-nums normal-case font-normal text-ink-soft">
          Rate
        </div>
      </div>

      <ul className="divide-y divide-rule-soft">
        {students.map((s) => {
          const name =
            s.first_name && s.last_name
              ? `${s.first_name} ${s.last_name}`
              : s.email;
          const attendedSessions = sessionNumbers.filter((n) =>
            isAttended(s.id, track.slug, week, n)
          ).length;
          return (
            <li
              key={s.id}
              className="grid grid-cols-[1fr_auto] sm:grid-cols-[1fr_repeat(var(--sessions),auto)_auto] gap-x-3 items-center px-4 py-3"
              style={{ ["--sessions" as string]: sessionsPerWeek }}
            >
              <div className="min-w-0">
                <p className="text-sm font-medium text-ink truncate">{name}</p>
                <p className="text-micro text-ink-faint truncate">{s.email}</p>
              </div>
              <div className="flex items-center gap-2 sm:contents">
                {sessionNumbers.map((sNum) => {
                  const checked = isAttended(s.id, track.slug, week, sNum);
                  const key = `${s.id}|${track.slug}|${week}|${sNum}`;
                  const saving = savingKeys.has(key);
                  return (
                    <button
                      key={sNum}
                      type="button"
                      role="checkbox"
                      aria-checked={checked}
                      aria-label={`${name} — Session ${sNum}: ${checked ? "present" : "absent"}`}
                      disabled={saving || locked}
                      onClick={() =>
                        void onToggle(s.id, track.slug, week, sNum, !checked)
                      }
                      className={`relative inline-flex h-8 w-8 sm:justify-self-end items-center justify-center rounded-full border transition-colors ${
                        checked
                          ? "border-success bg-success text-white"
                          : "border-rule bg-surface-elevated text-ink-faint hover:border-ink-soft hover:text-ink-soft"
                      } ${saving ? "opacity-60" : ""} ${locked ? "cursor-not-allowed opacity-50" : ""}`}
                    >
                      {checked ? <Check size={14} strokeWidth={2.5} /> : <Circle size={12} />}
                      {sessionsPerWeek > 1 && (
                        <span className="absolute -bottom-3.5 text-micro text-ink-faint hidden sm:block">
                          S{sNum}
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
              <div className="hidden sm:block text-right tabular-nums text-micro text-ink-soft">
                {attendedSessions}/{sessionsPerWeek}
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

// Re-export for backwards compatibility — anything currently importing the
// old static helper still resolves.
export { type StudentRow, type AttendanceRecord, type TrackLike };
// Silence unused import warning — kept for future quick-mark icon swaps.
void UserCheck;

"use client";

import { useEffect } from "react";

// Admin-scoped boundary: keeps the admin shell and sends people back to the
// admin home, not the learner dashboard the parent boundary points at.
export default function AdminError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    console.error("[admin-error]", error);
  }, [error]);

  return (
    <div className="flex flex-1 items-center justify-center px-4 py-16">
      <div className="mx-auto max-w-md text-center">
        <p className="text-[11px] font-mono uppercase tracking-[0.18em] text-ink-faint mb-4">
          Something went wrong
        </p>
        <h1 className="text-2xl font-bold text-ink mb-3">This admin page hit a snag</h1>
        <p className="text-sm text-ink-soft mb-6 leading-relaxed">
          Nothing you saved was lost. Try again, and if it keeps happening, send the
          reference below to the platform team.
        </p>
        {error.digest && (
          <p className="mb-6 font-mono text-xs text-ink-faint">Ref {error.digest}</p>
        )}
        <div className="flex items-center justify-center gap-3">
          <button
            onClick={reset}
            className="inline-flex items-center gap-2 rounded-lg bg-ink px-5 py-2.5 text-sm font-semibold text-paper transition-colors hover:bg-ink-soft"
          >
            Try again
          </button>
          <a
            href="/dashboard/admin"
            className="inline-flex items-center gap-2 rounded-lg border border-rule px-5 py-2.5 text-sm font-semibold text-ink transition-colors hover:bg-paper-tint"
          >
            Back to admin
          </a>
        </div>
      </div>
    </div>
  );
}

