import type { SurveyQuestion } from "@/components/survey-fields";
import { fetchPendingPeople, type PendingPerson } from "@/lib/people-hub";
import { getCourseEngagement, getCourseRosterStats } from "@/lib/course-engagement";
import { loadExitSurveyCompletion } from "@/lib/exit-survey-results";
import { examsForTrack } from "@/lib/exams";
import { getLaunchReadinessMany, isInLaunchWindow, type ReadinessCheck } from "@/lib/launch-readiness";
import { getCourseSidebar, type CourseSidebar } from "@/lib/course-needs";
import { resolveCurrentUnit, resolveTrackPhase, formatCohortDate } from "@/lib/utils";
import { getEngagementAnalytics, type EngagementAnalytics } from "./actions-analytics";
import { getCoursesAnalytics, type CoursesAnalytics } from "./actions-courses";
import type { CourseEngagementProps } from "@/components/stats/course-engagement";

export type InsightsData = {
  sections: {
    survey: SurveyConfig;
    schema: SurveyQuestion[] | null;
    responses: BCCSurveyResponse[];
  }[];
  programs: { slug: string; name: string }[];
  totalResponses: number;
};

type LunchLearnRow = {
  id: string;
  title: string;
  presenter: string;
  recording_url: string;
  description: string | null;
  recorded_at: string;
};


/** Start a request now, await it later. The pre-attached catch keeps an early
 *  redirect() from surfacing an in-flight promise as an unhandled rejection —
 *  the awaited copy still rejects at its original call site. */
function eager<T>(p: Promise<T>): Promise<T> {
  p.catch(() => {});
  return p;
}

export default async function AdminPage({
  searchParams,
}: {
  searchParams: Promise<{ tab?: string; view?: string; sub?: string; course?: string; session?: string }>;
}) {
  // `sub` makes the Students sub-view (roster / attendance / progress / work /
  // certificates) addressable, so an analytics number can link straight to the
  // list behind it instead of dead-ending on a figure.
  const {
    tab: initialTab,
    view: initialTrackView,
    sub: initialStudentSubView,
    session: signupsSession,
    // Shared Analytics course scope. The ?course= plumbing has been in place
    // since #824; the dimensions never read it, which is why the selector was
    // gated off in #825. The funnel reads it now.
    course: analyticsCourse,
  } = await searchParams;
  const [program, ctx] = await Promise.all([
    getProgram(),
    isSupabaseConfigured() ? getSessionContext() : Promise.resolve(null),
  ]);

  // Fetches below are started here and awaited where they are used. Nothing
  // about them depends on the queries in between, and each `await` on this
  // page costs a full round trip to Supabase — on a weak connection that is
  // ~1s of dead screen apiece. Ordering and error behavior are unchanged:
  // `eager` only pre-attaches a no-op catch so an early redirect() can't turn
  // an in-flight promise into an unhandled rejection. The awaited copy still
  // throws at the original call site.
  const hiddenSlugsPromise = eager(getHiddenTrackSlugs());
  // Assigned inside the session block below, awaited after it.
  let dynamicProgramsPromise: Promise<{ slug: string; name: string }[]> | null = null;

  // Land a super-admin in a real program instead of the "No program selected"
  // dead end.
  //
  // The apex (bccacademy.io) resolves to the `marketing` pseudo-program, which
  // owns no courses. A LEARNER gets rescued by resolveLearnerBrand, which reads
  // their enrollments — but a super-admin has none, so nothing rescues them and
  // every visit lands on an empty screen.
  //
  // Only fires when no program-override cookie is set, so it's a first-landing
  // default and never fights a deliberate switch. The empty state stays
  // reachable by switching to a program that genuinely has no courses.
  if (
    program.tracks.length === 0 &&
    ctx?.userId &&
    canSwitchPrograms(ctx.student?.role ?? "") &&
    !(await cookies()).get("program-override")
  ) {
    // The admin's own home program. One tiny lookup, only on the dead-end path
    // (the session context doesn't carry program_id).
    const { data: me } = await createServiceClient()
      .from("students")
      .select("programs(slug)")
      .eq("id", ctx.userId)
      .maybeSingle();
    const meProgram = (Array.isArray(me?.programs) ? me?.programs[0] : me?.programs) as
      | { slug: string }
      | undefined;
    const homeSlug = meProgram?.slug ?? null;
    const fallback = homeSlug && getJoinablePrograms().find((p) => p.slug === homeSlug);
    if (fallback) {
      redirect(`/api/switch-program?slug=${fallback.slug}&next=/dashboard/admin`);
    }
  }

  // Tab-gated data fetching. The admin page re-renders on every ?tab=
  // change, so we only pay the cost for queries the active tab actually
  // needs. Default-tab heuristic mirrors AdminTabs's own initial state:
  // no ?tab= → Admin Home picker, which only needs the basic tracks +
  // students + studentTracks already in the core batch.
  const effectiveTab = initialTab ?? "home";
  const isTrackTab = program.tracks.some((t) => t.slug === effectiveTab);
  // Engagement scores feed the person rows in BOTH the per-track People
  // sub-view and the cross-track People tab — fetching for only one made the
  // same learner show an engagement block in one place and nothing in the
  // other. (The per-course attendance % badge stays course-only: a percentage
  // across courses with different session counts has no honest denominator.)
  const needsEngagement = isTrackTab || effectiveTab === "students";
  // Home tab only needs id+role for enrollment-count filtering; tabs that
  // display student details need the full row. Similarly, student_tracks are
  // fetched as full rows only for tabs that manage individual enrollments.
  const needsStudents = isTrackTab || effectiveTab === "students" || effectiveTab === "student-work" || effectiveTab === "attendance" || effectiveTab === "home";
  const needsStudentTracks = isTrackTab || effectiveTab === "students" || effectiveTab === "student-work" || effectiveTab === "attendance" || effectiveTab === "home";
  const isHomeTab = effectiveTab === "home";
  const needsInstructorTracks = isTrackTab || effectiveTab === "students";
  const needsCohorts = isHomeTab || isTrackTab || effectiveTab === "students";
  const needsLunchLearns = effectiveTab === "lunch-learn";
  const needsInsightsData = effectiveTab === "insights";
  const needsAnalyticsData = effectiveTab === "analytics";
  const needsCoursesData = effectiveTab === "course-progress";
  let allStudents: Pick<Student, "id" | "first_name" | "last_name" | "email" | "role" | "is_staff" | "cohort_id" | "last_seen_at" | "last_activity_at" | "zip" | "state" | "date_of_birth">[] = [];
  let allCohorts: { id: string; name: string; display_name: string | null; track_slug: string | null; start_date: string | null; total_weeks: number | null }[] = [];
  let studentTracks: StudentTrackRow[] = [];
  let instructorTracks: InstructorTrackRow[] = [];
  let userRole = "student";
  let actorId: string | null = null;
  let actorEmail: string | null = null;
  let myInstructorTracks: string[] = [];
  // Track narrowing from a course-scoped cross-program grant (e.g. "Catalyst,
  // but only Homes for the Summer"). null = whole program. See
  // lib/auth/program-access.
  let grantTrackScope: string[] | null = null;
  let publicSurveyStats: PublicSurveyStatsRow[] = [];
  let lunchLearnRecordings: LunchLearnRow[] = [];
  let insightsData: InsightsData | null = null;
  let analyticsData: EngagementAnalytics | null = null;
  let coursesData: CoursesAnalytics | null = null;
  let courseEngagement: CourseEngagementProps | null = null;
  // Per-learner attendance for the open course's roster: sessions held once,
  // plus each learner's attended count. Null when nobody has checked in.
  let attendanceRates: { held: number; attended: Record<string, number> } | null = null;
  let courseStats: Record<
    string,
    { total: number; active: number; fullAttendance: number | null; sessionsHeld: number }
  > = {};
  let alumniEnrollments: { track_slug: string; email: string; source: string }[] = [];
  let pendingPeople: PendingPerson[] = [];
  let unviewedAssessments: number | null = null;
  const surveyList = [
    ...Object.values(PLATFORM_AUTH_SURVEYS),
    ...(program.surveys ?? []),
  ];
  const engagementScores: Record<string, { total: number; attendance: number; submissions: number; reflections: number; videos: number }> = {};

  if (isSupabaseConfigured() && !ctx) redirect("/");
  if (isSupabaseConfigured() && ctx) {
    // Session context resolved in parallel with getProgram() above.
    const userId = ctx.userId;
    actorId = userId;
    userRole = ctx.student?.role ?? "student";
    actorEmail = ctx.student?.email ?? ctx.userEmail ?? null;

    const svc = createServiceClient();

    // Program ID lookup. Every program is standalone — Catalyst, Beyond the
    // Game (atg), Beyond Code Centers, and Forte each scope to their own
    // program id; students/data live under that id. Cached across requests
    // with a short TTL: program UUIDs never change, so there is zero staleness
    // risk.
    const aggregatedSlugs = [program.slug === "marketing" ? "catalyst" : program.slug];
    const programRows = await getCachedProgramIds(aggregatedSlugs);
    const programIds = (programRows ?? []).map((p) => p.id as string);
    const programTrackSlugs = program.tracks.map((t) => t.slug);
    const programId = programRows?.find((p) => p.slug === program.slug)?.id;

    if (!canAccessAdminPanel(userRole)) redirect("/dashboard");

    // Second set of started-now-awaited-later fetches (see `eager` above).
    // These depend only on the program's own config, never on the roster
    // batch they used to queue behind.
    const activeTrackForFetch = isTrackTab
      ? program.tracks.find((tk) => tk.slug === effectiveTab)
      : undefined;
    // When this load fetches the roster anyway, the course stats are seeded
    // from those rows below instead of refetching students + student_tracks.
    const courseStatsPromise =
      needsStudents && needsStudentTracks
        ? null
        : eager(getCourseRosterStats(programTrackSlugs).catch(() => ({})));
    const trackLengthsPromise = needsEngagement ? eager(resolveTrackLengths()) : null;
    dynamicProgramsPromise = eager(listDynamicPrograms());
    const activeTrackStatsPromise = activeTrackForFetch
      ? eager(
          Promise.all([
            svc
              .from("attendance")
              .select("student_id, week_number, session_number")
              .eq("track", activeTrackForFetch.slug)
              .not("checked_in_at", "is", null),
            getCourseEngagement(activeTrackForFetch.name, activeTrackForFetch.slug, {
              hasVideoContent: activeTrackForFetch.weeks.some((w) => !!w.videoUrl),
              submissionsEnabled: activeTrackForFetch.submissionsEnabled !== false,
              unitLabel: activeTrackForFetch.unitLabel ?? "Week",
            }).catch(() => null),
          ]),
        )
      : null;

    // Program boundary for non-super-admins. Holding an admin/instructor role
    // proves you run SOME program — it never proved you run THIS one, so
    // reaching another program's admin surface (its domain, a switcher cookie)
    // showed you its roster. Access = your home program plus your grants.
    if (!canSwitchPrograms(userRole) && !isMasterEmail(actorEmail) && programId) {
      const [grants, homeRow] = await Promise.all([
        getProgramGrants(userId),
        svc
          .from("students")
          .select("program_id")
          .eq("id", userId)
          .maybeSingle<{ program_id: string | null }>(),
      ]);
      const homeProgramId = homeRow.data?.program_id ?? null;
      const allowed = allowedProgramIds(homeProgramId, grants);
      // Only enforce once we actually know where this person belongs — an
      // account with neither a program stamp nor a grant keeps the old
      // behavior rather than being locked out of the panel.
      if (allowed.length > 0 && !allowed.includes(programId)) {
        // Send them to their own program's panel. Bouncing to /dashboard
        // looped forever for an admin browsing a course they take elsewhere
        // (Rob, 2026-11-06: 6,000 reloads, then out of memory).
        const { data: home } = homeProgramId
          ? await svc.from("programs").select("slug").eq("id", homeProgramId).maybeSingle<{ slug: string }>()
          : { data: null };
        redirect(
          home?.slug && home.slug !== program.slug
            ? `/api/switch-program?slug=${encodeURIComponent(home.slug)}&next=/dashboard/admin`
            : "/dashboard",
        );
      }
      grantTrackScope = allowedTrackSlugs(homeProgramId, grants, programId);
    }

    // Survey Insights is open to any admin, but program admins see only their
    // own program's data (scoped server-side in the actions below); super-admins
    // get the BCC-wide view. Instructors have no insights access, so bounce them
    // off ?tab=insights entirely rather than showing an empty state.
    if (effectiveTab === "insights" && !canViewInsights(userRole)) {
      redirect("/dashboard/admin");
    }

    // No auto-redirect away from /dashboard/admin. The previous version
    // bounced super-admins to /dashboard/insights, which meant clicking
    // "Admin" in the sidebar appeared to do nothing whenever you were
    // already on Insights. AdminTabs' defaultTab handles landing inside
    // a useful tab (People for managers/super-admins, first track for
    // instructors); dashboardless programs render their own empty state.

    // Public-survey stats are only shown on dashboardless programs
    // (marketing apex BCC-wide view, Catalyst, etc.). On Forge/ATG the
    // widget is hidden entirely, so fetching across the whole
    // public_survey_responses table is pure waste — that query is the
    // single biggest contributor to admin-page latency for super-admins.
    // tracks.length is known synchronously from the resolved program
    // config; no DB round-trip needed to decide.
    const needsPublicSurveyStats =
      canSwitchPrograms(userRole) && program.tracks.length === 0;

    // Dashboardless programs (marketing apex BCC-wide view, Catalyst) have no
    // tracks, cohorts, students, etc. — every program-scoped query would
    // return empty. Skip the heavy batch entirely and only resolve public
    // survey stats. This makes /dashboard/admin on bccacademy.io render in
    // one round-trip instead of ~12 empty queries.
    const isDashboardlessProgram = program.tracks.length === 0;

    if (isDashboardlessProgram) {
      publicSurveyStats = needsPublicSurveyStats
        ? await getPublicSurveyStats().catch((e) => {
            console.error("getPublicSurveyStats failed:", e);
            return [] as PublicSurveyStatsRow[];
          })
        : [];
    } else {
      // Tab-gated batch. The previous version fired every query on every
      // admin page load; now we only pay for what the current tab renders.
      // Core entities (students/cohorts/tracks/instructor enrollments) are
      // always fetched — they're cheap and used as nav metadata everywhere.
      // Survey stats, engagement scores, lunch_learns are skipped on tabs
      // that don't render them.
      const [
        coreRes,
        publicStatsRes,
        engagementRes,
        alumniRes,
      ] = await Promise.all([
      Promise.all([
        needsStudents
          ? svc
                  .from("students")
                  .select("id, first_name, last_name, email, role, is_staff, cohort_id, last_seen_at, last_activity_at, zip, state, date_of_birth")
                  // Program members PLUS every super_admin: cross-program staff
                  // (e.g. someone running both Catalyst and Beyond Code Centers)
                  // should appear in each program's People tab, not only under
                  // the program their account happened to be created in.
                  .or(
                    programIds.length > 0
                      ? `program_id.in.(${programIds.join(",")}),role.eq.super_admin`
                      : "role.eq.super_admin",
                  )
                  // Internal QA logins never belong on a visitor-facing roster,
                  // attendance list, or risk view.
                  .eq("is_test", false)
                  .order("created_at", { ascending: true })
          : Promise.resolve({ data: [] as Pick<Student, "id" | "first_name" | "last_name" | "email" | "role" | "is_staff" | "cohort_id" | "last_seen_at" | "last_activity_at" | "zip" | "state" | "date_of_birth">[] }),
        needsCohorts
          ? svc
              .from("cohorts")
              .select("id, name, display_name, track_slug, start_date, total_weeks")
              .in("program_id", programIds)
              .order("created_at", { ascending: true })
          : Promise.resolve({ data: [] as { id: string; name: string; display_name: string | null; track_slug: string | null; start_date: string | null; total_weeks: number | null }[] }),
        // Enrollment scope = THIS program's track slugs (globally unique), not
        // program_id — signups on the apex domain stamp Catalyst, and filtering
        // by program_id blanked standalone program rosters (HS cohort, BCC
        // Centers) whose enrollments were filed under it.
        needsStudentTracks
          ? isHomeTab
              ? svc
                  .from("student_tracks")
                  .select("track_slug, student_id")
                  .in("track_slug", programTrackSlugs)
              : svc
                  .from("student_tracks")
                  .select("id, student_id, track_slug, program_id, created_at")
                  .in("track_slug", programTrackSlugs)
                  .order("created_at")
          : Promise.resolve({ data: [] as StudentTrackRow[] }),
        needsInstructorTracks
          ? svc
              .from("instructor_tracks")
              .select("id, student_id, track_slug, program_id, created_at, role")
              // Deliberately NOT filtered by program. The staff roster above
              // already spans programs (it ORs in every super_admin), so
              // scoping assignments to the active program made cross-program
              // instructors render as teaching nothing — their rows exist,
              // they're just filed under another program. Re-assigning from
              // the "empty" list then no-ops against the existing row, so the
              // list looks permanently broken and un-fixable. The roster is
              // the scope; this table is small and keyed to it.
              .order("created_at")
          : Promise.resolve({ data: [] as InstructorTrackRow[] }),
        userRole === "instructor"
          ? svc
              .from("instructor_tracks")
              .select("track_slug")
              .eq("student_id", userId)
          : Promise.resolve({ data: null as { track_slug: string }[] | null }),
      ]),
      needsPublicSurveyStats
        ? getPublicSurveyStats().catch((e) => {
            console.error("getPublicSurveyStats failed:", e);
            return [] as PublicSurveyStatsRow[];
          })
        : Promise.resolve([] as PublicSurveyStatsRow[]),
      needsEngagement
        ? Promise.all([
            // Scoped by track slug (globally unique), not program_id stamp —
            // activity recorded under another program's id (apex-domain flows
            // stamp Catalyst) still belongs to this program's courses.
            svc.from("attendance").select("student_id, track, week_number").in("track", programTrackSlugs),
            svc.from("submissions").select("student_id, track_slug, week_number").in("track_slug", programTrackSlugs).not("submitted_at", "is", null),
            svc.from("reflections").select("student_id, track_slug, week_number").in("track_slug", programTrackSlugs).not("submitted_at", "is", null),
            // Video is a did-the-work engagement signal (self-paced tracks have
            // no attendance); tutor chat was ACTIVITY, not engagement, so it no
            // longer feeds the score.
            svc.from("week_progress").select("user_id, track_slug, week_number").in("track_slug", programTrackSlugs).not("video_watched_at", "is", null),
          ])
        : Promise.resolve(null),
      // Historical alumni (imported from Circle and similar). Only fetched
      // on the program overview tab where the metric and chart use it.
      effectiveTab === "program"
        ? svc
            .from("alumni_enrollments")
            .select("track_slug, email, source")
            .in("program_id", programIds)
        : Promise.resolve({ data: null as { track_slug: string; email: string; source: string }[] | null }),
    ]);

    const [
      studentsResult,
      cohortsResult,
      studentTracksRes,
      instructorTracksRes,
      myInstrTracksRes,
    ] = coreRes;

    allStudents = (studentsResult.data ?? []) as Pick<Student, "id" | "first_name" | "last_name" | "email" | "role" | "is_staff" | "cohort_id" | "last_seen_at" | "last_activity_at" | "zip" | "state" | "date_of_birth">[];
    allCohorts = cohortsResult.data || [];
    studentTracks = (studentTracksRes.data ?? []) as StudentTrackRow[];
    instructorTracks = (instructorTracksRes.data ?? []) as InstructorTrackRow[];

    // Membership is defined by ENROLLMENT, not just the account's program_id
    // stamp. A learner whose account was stamped under another program (signed
    // up on a different surface) but who is enrolled in THIS program's courses
    // belongs on this roster — without this, the HS cohort read "2 enrolled"
    // while its Students list showed zero. Supplement the stamped set with
    // anyone holding an enrollment or instructor assignment here.
    // instructorTracks is fetched unfiltered (see the fetch above), so narrow
    // it to THIS program's courses before supplementing — otherwise every
    // instructor platform-wide gets appended to every program's roster.
    if (needsStudents) {
      const trackSlugSet = new Set(programTrackSlugs);
      const have = new Set(allStudents.map((s) => s.id));
      const missingIds = Array.from(
        new Set(
          [
            ...studentTracks,
            ...instructorTracks.filter((e) => trackSlugSet.has(e.track_slug)),
          ]
            .map((e) => e.student_id)
            .filter((id) => !have.has(id)),
        ),
      );
      if (missingIds.length > 0) {
        const { data: extra } = await svc
          .from("students")
          .select("id, first_name, last_name, email, role, is_staff, cohort_id, last_seen_at, last_activity_at, zip, state, date_of_birth")
          .in("id", missingIds)
          .eq("is_test", false);
        allStudents = [
          ...allStudents,
          ...((extra ?? []) as typeof allStudents),
        ];
      }
    }
    myInstructorTracks = ((myInstrTracksRes.data ?? []) as { track_slug: string }[]).map(
      (r) => r.track_slug
    );

    // People hub: allowlisted/invited emails with no account yet, for the
    // current program's tracks. Only on the People tab.
    // Managers only: instructors are view-only on their course's roster and
    // can't act on invites/allowlists, so don't ship them the pending emails.
    if (
      effectiveTab === "students" &&
      (canManageStudents(userRole) || isMasterEmail(actorEmail))
    ) {
      const studentEmails = new Set(
        allStudents.map((s) => (s.email ?? "").toLowerCase()).filter(Boolean),
      );
      pendingPeople = await fetchPendingPeople(
        program.tracks.map((t) => t.slug),
        studentEmails,
      );
    }
    publicSurveyStats = publicStatsRes;

    alumniEnrollments = (alumniRes.data ?? []) as { track_slug: string; email: string; source: string }[];

    // Compute engagement scores only when the active tab needs them.
    if (engagementRes) {
      const [attendanceRes, submissionsRes, reflectionsRes, videoRes] = engagementRes;
      const attendanceRows = (attendanceRes.data ?? []) as { student_id: string; track: string; week_number: number }[];
      const submissionRows = (submissionsRes.data ?? []) as { student_id: string; track_slug: string; week_number: number }[];
      const reflectionRows = (reflectionsRes.data ?? []) as { student_id: string; track_slug: string; week_number: number }[];
      const videoRows = (videoRes.data ?? []) as { user_id: string; track_slug: string; week_number: number }[];

      // Denominator per LEARNER: units held so far across the courses they're
      // enrolled in. Scoring everyone against the longest course in the
      // program made a 6-day Home for the Summer learner with perfect
      // attendance read 8/25 (6 of Security+'s 19). Audit 2026-08-18, F17.
      const lengths = await (trackLengthsPromise ?? resolveTrackLengths());
      const heldForStudent = (id: string): number => {
        let held = 0;
        for (const st of studentTracks) {
          if (st.student_id !== id) continue;
          held += lengths.get(st.track_slug)?.heldUnits ?? 0;
        }
        return Math.max(held, 1);
      };

      // Canonical engagement (docs/analytics-plan.md): the four did-the-work
      // signals, each worth up to 25 pts → /100. Video replaces the old tutor
      // term so self-paced tracks aren't structurally under-scored.
      const staffCohortSlugs = new Set(program.tracks.filter((t) => t.staffCohort).map((t) => t.slug));
      const learnerIds = new Set(
        studentTracks.filter((st) => staffCohortSlugs.has(st.track_slug)).map((st) => st.student_id),
      );
      for (const s of allStudents) {
        // Staff cohort enrollees are learners on that course (test rows are already excluded).
        if ((s.role !== "student" || s.is_staff) && !learnerIds.has(s.id)) continue;
        const att = new Set(attendanceRows.filter((r) => r.student_id === s.id).map((r) => `${r.track}-${r.week_number}`)).size;
        const sub = new Set(submissionRows.filter((r) => r.student_id === s.id).map((r) => `${r.track_slug}-${r.week_number}`)).size;
        const ref = new Set(reflectionRows.filter((r) => r.student_id === s.id).map((r) => `${r.track_slug}-${r.week_number}`)).size;
        const vid = new Set(videoRows.filter((r) => r.user_id === s.id).map((r) => `${r.track_slug}-${r.week_number}`)).size;

        const denom = heldForStudent(s.id);
        const attScore = Math.min((att / denom) * 25, 25);
        const subScore = Math.min((sub / denom) * 25, 25);
        const refScore = Math.min((ref / denom) * 25, 25);
        const vidScore = Math.min((vid / denom) * 25, 25);

        engagementScores[s.id] = {
          total: Math.round(attScore + subScore + refScore + vidScore),
          attendance: att,
          submissions: sub,
          reflections: ref,
          videos: vid,
        };
      }
    }
    } // end !isDashboardlessProgram

    // These five are independent of each other and were awaited one after the
    // other, so a tab that needs two of them paid two round trips of latency
    // before rendering. Each still runs only under the same condition it
    // always did; they just no longer queue behind each other.
    const [unviewedRes, llRes, insightsRes, analyticsRes, coursesRes] = await Promise.all([
      isHomeTab && canAccessAdminPanel(userRole)
        ? svc
            .from("assessment_results")
            .select("*", { count: "exact", head: true })
            .is("facilitator_viewed_at", null)
        : Promise.resolve(null),
      canAccessAdminPanel(userRole) && needsLunchLearns
        ? svc
            .from("lunch_learns")
            .select("id, title, presenter, recording_url, description, recorded_at")
            .order("recorded_at", { ascending: false })
        : Promise.resolve(null),
      canViewInsights(userRole) && needsInsightsData
        ? buildInsightsData(programIds, aggregatedSlugs)
        : Promise.resolve(null),
      canViewInsights(userRole) && needsAnalyticsData
        ? getEngagementAnalytics(analyticsCourse).catch(() => null)
        : Promise.resolve(null),
      canViewInsights(userRole) && needsCoursesData
        ? getCoursesAnalytics().catch(() => null)
        : Promise.resolve(null),
    ]);

    if (unviewedRes) unviewedAssessments = unviewedRes.count ?? 0;
    if (llRes) lunchLearnRecordings = (llRes.data ?? []) as LunchLearnRow[];
    if (insightsRes) insightsData = insightsRes;
    if (analyticsRes) analyticsData = analyticsRes;
    if (coursesRes) coursesData = coursesRes;

    // Scoping note for the three above: Survey Insights, Engagement and
    // Courses are all scoped to the CURRENT program (via programIds /
    // analyticsCourse), for super-admins too — no cross-program firehose, and
    // the cohort dropdown only lists this program's cohorts. The BCC-wide
    // operational dashboard at /dashboard/insights is scoped separately, and
    // Insights uses the same assembly as the PDF export so screen and PDF
    // never drift.

    // Enrolled + active per course for the course-picker list. Computed here
    // rather than on the client, which only has program-scoped students and a
    // browsing timestamp: that undercounts the roster (learners whose
    // students.program_id points at another program) and reports a live Zoom
    // camp as "0 active". Same signals as getCourseEngagement, so the list and
    // the course Overview agree.
    courseStats = courseStatsPromise
      ? await courseStatsPromise
      : await getCourseRosterStats(programTrackSlugs, new Date(), {
          enrollments: studentTracks,
          students: allStudents,
        }).catch(() => ({}));

    // Per-course engagement snapshot for the open course tab — the admin
    // feedback loop on the learner streak cards. Only the active course's
    // aggregates are fetched.
    if (isTrackTab) {
      const t = program.tracks.find((tk) => tk.slug === effectiveTab);
      if (t) {
        // Per-learner attendance for the roster badge. Keyed on week+session,
        // not week alone — a course meeting twice a week would otherwise read
        // 100% for someone who only ever comes on Tuesdays. "Held" is derived
        // from check-ins, since the schedule can't say a session actually ran.
        // The roster badge and the engagement snapshot describe the same
        // course but need nothing from each other, so they go together.
        const [attRes, engagementSnapshot] = await activeTrackStatsPromise!;
        const attRows = attRes.data;
        const held = new Set(
          (attRows ?? []).map((r) => `${r.week_number}-${r.session_number}`),
        ).size;
        if (held > 0) {
          const perLearner = new Map<string, Set<string>>();
          for (const r of attRows ?? []) {
            if (!perLearner.has(r.student_id)) perLearner.set(r.student_id, new Set());
            perLearner.get(r.student_id)!.add(`${r.week_number}-${r.session_number}`);
          }
          attendanceRates = { held, attended: {} };
          for (const [id, set] of perLearner) attendanceRates.attended[id] = set.size;
        }
        courseEngagement = engagementSnapshot;
        // Pre-start, "3/16 active · 12 idle" reads as failure when it's a full
        // roster waiting on day one — lead with enrollment instead.
        if (courseEngagement && resolveTrackPhase(t) === "upcoming") {
          courseEngagement = {
            ...courseEngagement,
            upcoming: true,
            startLabel: t.startDateTbd ? null : formatCohortDate(t.startDate),
          };
        }
      }
    }
  }

  // Programs the "No program selected" screen can offer.
  //
  // A super-admin gets all of them. A cross-program admin (Jihan, Linda) gets
  // the ones they were actually granted plus their home program — the picker was
  // gated on canSwitchPrograms, i.e. super_admin only, so a grant-holder landing
  // on that screen saw the empty version with no way out, even though the user
  // menu would have offered them a switcher elsewhere.
  let switchablePrograms: { slug: string; name: string }[] = [];
  if (canSwitchPrograms(userRole)) {
    switchablePrograms = [
      ...getJoinablePrograms().map((p) => ({ slug: p.slug, name: p.name })),
      ...(await (dynamicProgramsPromise ?? listDynamicPrograms())),
    ];
  } else if (canAccessAdminPanel(userRole) && actorId) {
    const granted = new Set(await getGrantedProgramSlugs(actorId));
    const { data: me } = await createServiceClient()
      .from("students")
      .select("programs(slug)")
      .eq("id", actorId)
      .maybeSingle();
    const home = (Array.isArray(me?.programs) ? me?.programs[0] : me?.programs) as
      | { slug: string }
      | undefined;
    if (home?.slug) granted.add(home.slug);
    switchablePrograms = [
      ...getJoinablePrograms().map((p) => ({ slug: p.slug, name: p.name })),
      ...(await (dynamicProgramsPromise ?? listDynamicPrograms())),
    ].filter((p) => granted.has(p.slug));
  }

  // Platform auth surveys (e.g. the Security+ midpoint check-in) live outside
  // program.surveys, so building this list from the program config alone left
  // the course Surveys tab empty even after a cohort had answered.
  const surveyConfigs = Array.from(
    new Map(surveyList.map((s) => [s.id, s])).values(),
  ).map((s) => ({
    id: s.id,
    title: s.title,
    // Which tracks opt out — the per-track Surveys tab hides these, so a
    // Security+ instructor isn't offered AI Fundamentals surveys.
    skipForTracks: s.skipForTracks,
    // Which tracks the survey is FOR — those always list it, even at zero
    // responses, so an admin can watch a fresh survey fill in.
    appliesToTracks: s.appliesToTracks,
  }));

  // Public surveys tied to a track (e.g. network-plus-post → Network+).
  // Fetched only when an admin is viewing a track-scoped tab — keeps the
  // home/people/etc tabs unaffected by the extra query.
  let activeTrack: typeof program.tracks[0] | undefined;
  let activeTrackPublicSurveyIds: string[] = [];
  let trackPublicSurveys: { id: string; title: string; count: number }[] = [];
  // Auth surveys this course's enrolled students have actually answered.
  // null = not a track tab (no filtering). The course Surveys tab is an
  // insights list, and the old opt-out (skipForTracks) rule surfaced every
  // program survey under every course — an unrelated survey has no business
  // there, and with zero responses there'd be nothing to view anyway.
  let trackAnsweredSurveyIds: string[] | null = null;
  /** Enrolled LEARNERS in the open course — the denominator for response rate. */
  let trackEnrolledCount = 0;
  // Latest session's pulse (exit survey) completion, for the Surveys tab row.
  let trackPulseLatest: { week: number; session: number; answered: number; enrolled: number } | null = null;
  /** survey id → distinct learners from this course who answered it. */
  let trackSurveyRespondents: Record<string, number> = {};
  /** This course's practice exams + how many enrolled learners attempted. */
  let trackExams: { id: string; title: string; attempted: number }[] = [];

  if (isSupabaseConfigured()) {
    activeTrack = isTrackTab
      ? program.tracks.find((t) => t.slug === effectiveTab)
      : undefined;
    activeTrackPublicSurveyIds = activeTrack?.publicSurveys ?? [];
    if (activeTrack) {
      // Learners only — staff hold enrollments so they can see a course, and
      // counting them would make a response rate read low for a class that
      // fully responded. Same filter the completion rate uses.
      const learnerIds = new Set(
        allStudents
          .filter((s) => activeTrack!.staffCohort || (s.role === "student" && !s.is_staff))
          .map((s) => s.id),
      );
      const trackStudentIds = Array.from(
        new Set(
          studentTracks
            .filter((e) => e.track_slug === activeTrack!.slug)
            .map((e) => e.student_id)
            .filter((id) => learnerIds.has(id)),
        ),
      );
      trackEnrolledCount = trackStudentIds.length;
      if (activeTrack.exitSurveyEnabled) {
        const pulse = await loadExitSurveyCompletion(createServiceClient(), activeTrack.slug);
        trackPulseLatest = pulse.at(-1) ?? null;
      }
      const surveyIds = Array.from(new Set(surveyList.map((sv) => sv.id)));
      if (trackStudentIds.length > 0 && surveyIds.length > 0) {
        const { data: answered } = await createServiceClient()
          .from("survey_responses")
          .select("survey_type, student_id")
          .in("survey_type", surveyIds)
          .in("student_id", trackStudentIds);
        trackAnsweredSurveyIds = Array.from(
          new Set((answered ?? []).map((r) => r.survey_type as string)),
        );
        // Distinct respondents per survey. THE number this page was missing:
        // "15 of 16 answered the pre-survey, 1 of 16 answered the post" is how
        // you notice a cohort never came back — AI Fundamentals sat at 15-vs-1
        // for weeks with nothing anywhere saying so.
        const byS = new Map<string, Set<string>>();
        for (const r of answered ?? []) {
          const id = r.survey_type as string;
          if (!byS.has(id)) byS.set(id, new Set());
          byS.get(id)!.add(r.student_id as string);
        }
        trackSurveyRespondents = Object.fromEntries(
          Array.from(byS, ([id, set]) => [id, set.size]),
        );
      } else {
        trackAnsweredSurveyIds = [];
      }
      // Practice exams sit in the same Surveys list as peer rows, so they
      // carry the same participation shape: distinct enrolled learners with a
      // submitted attempt.
      // One query for every exam on the course, not one per exam in sequence —
      // a course with four practice exams paid four round trips here.
      const exams = examsForTrack(activeTrack.slug);
      const attemptsByExam = new Map<string, Set<string>>();
      if (exams.length > 0 && trackStudentIds.length > 0) {
        const { data: att } = await createServiceClient()
          .from("exam_attempts")
          .select("exam_id, student_id")
          .in("exam_id", exams.map((e) => e.id))
          .not("submitted_at", "is", null)
          .in("student_id", trackStudentIds);
        for (const r of att ?? []) {
          const id = r.exam_id as string;
          if (!attemptsByExam.has(id)) attemptsByExam.set(id, new Set());
          attemptsByExam.get(id)!.add(r.student_id as string);
        }
      }
      for (const exam of exams) {
        trackExams.push({ id: exam.id, title: exam.title, attempted: attemptsByExam.get(exam.id)?.size ?? 0 });
      }
    }
    const publicSurveyCounts = activeTrackPublicSurveyIds.length > 0
      ? await getPublicSurveyCountsByType(activeTrackPublicSurveyIds).catch((e) => {
          console.error("getPublicSurveyCountsByType failed:", e);
          return [] as { survey_type: string; count: number }[];
        })
      : [];
    trackPublicSurveys = activeTrackPublicSurveyIds.map((id) => {
      const cfg = PLATFORM_PUBLIC_SURVEYS[id];
      const stat = publicSurveyCounts.find((r) => r.survey_type === id);
      return {
        id,
        title: cfg?.title ?? id,
        count: stat?.count ?? 0,
      };
    });
  }

  // Serialize track configs for the client component. Home/insights/lunch-learn
  // tabs only show track cards (basic metadata + enrollment counts), not the
  // week/session details. Skipping weeks for those tabs reduces serialized
  // payload dramatically — ~200 weeks + ~400 sessions objects for a typical
  // 5-track, 10-week, 2-session program.
  const needsFullTrackConfig = isTrackTab || effectiveTab === "students" || effectiveTab === "student-work" || effectiveTab === "attendance";
  const allTracks = program.tracks.map((t) => {
    const base = {
      slug: t.slug,
      name: t.name,
      shortName: t.shortName,
      description: t.description,
      type: t.type,
      totalWeeks: t.totalWeeks,
      // Correct current unit for day-gated camps (advances by comingSoonUntil,
      // not the 7-day cycle). Computed here where the full config with weeks[]
      // is available; the admin tabs/attendance default to it instead of
      // computeCurrentWeek, which pins at Day 1 all camp.
      currentUnit: resolveCurrentUnit(t),
      // Which headline number is honest for this course: enrolled before it
      // starts, active while it runs, completion once it's over.
      phase: resolveTrackPhase(t),
      unitLabel: t.unitLabel,
      selfPaced: t.selfPaced,
      sessionsPerWeek: t.sessionsPerWeek,
      instructor: t.instructor,
      companionOf: t.companionOf,
      sessionTimes: t.sessionTimes,
      startDate: t.startDate,
      startDateTbd: t.startDateTbd,
      lastSessionDayOffset: t.lastSessionDayOffset,
      weekSummaries: t.weekSummaries,
      defaultReflectionPrompts: t.defaultReflectionPrompts,
      submissionsEnabled: t.submissionsEnabled,
      reflectionsEnabled: t.reflectionsEnabled,
      exitSurveyEnabled: t.exitSurveyEnabled,
      staffCohort: t.staffCohort,
      sequentialGating: t.sequentialGating,
      officeHours: t.officeHours ?? [],
    };
    if (needsFullTrackConfig) {
      return {
        ...base,
        weeks: t.weeks.map((w) => ({
          week: w.week,
          title: w.title,
          icon: w.icon,
          sessions: w.sessions.map((s) => ({ title: s.title })),
          submissionPrompts: w.submissionPrompts,
        })),
      };
    }
    return { ...base, weeks: [] };
  });

  // Catalyst is an umbrella that aggregates other programs' tracks (Forte's
  // ai-literacy, etc.). In the program-first admin, show only Catalyst's OWN
  // courses here — the aggregated ones are managed under their home program.
  const ownTracks =
    program.slug === "catalyst"
      ? allTracks.filter((t) => {
          const home = getHomeProgramForTrack(t.slug);
          return !home || home.slug === "catalyst";
        })
      : allTracks;

  // Drop courses the super-admin has hidden via Manage Courses — they vanish
  // from the admin home (and catalog) but keep all data and are one click to
  // restore. Works for hardcoded and DB courses alike.
  const hiddenSlugs = await hiddenSlugsPromise;
  const visibleTracks = ownTracks.filter((t) => !hiddenSlugs.has(t.slug));

  // How many of THIS program's courses are hidden — drives the "every course is
  // hidden" empty state instead of the "no program selected" picker.
  //
  // It canNOT be derived from ownTracks/visibleTracks: getProgram() has ALREADY
  // dropped hidden courses, so both lists arrive hidden-free and the difference
  // is always 0 (which is also why the visibleTracks filter above is a no-op).
  // Re-resolve the program unfiltered instead, and only when there's nothing
  // left to show, so a normal admin home pays nothing for it.
  //
  // Guarded to statically-configured programs: getProgramBySlug falls back to
  // Catalyst for an unknown slug, so an admin-created org would otherwise be
  // told every course is hidden and handed Catalyst's count.
  let hiddenCourseCount = 0;
  if (
    visibleTracks.length === 0 &&
    getEveryProgramConfig().some((p) => p.slug === program.slug)
  ) {
    const unfiltered = await getProgramWithOverrides(program.slug);
    const unfilteredOwn =
      program.slug === "catalyst"
        ? unfiltered.tracks.filter((t) => {
            const home = getHomeProgramForTrack(t.slug);
            return !home || home.slug === "catalyst";
          })
        : unfiltered.tracks;
    hiddenCourseCount = unfilteredOwn.filter((t) => hiddenSlugs.has(t.slug)).length;
  }

  // A course-scoped grant confines someone to the named courses inside a
  // program they don't otherwise belong to — the same narrowing instructors
  // get from their assignments, just sourced from the grant.
  const grantScopedTracks = grantTrackScope
    ? visibleTracks.filter((t) => grantTrackScope.includes(t.slug))
    : visibleTracks;

  // Instructors only see their assigned tracks
  const tracks = userRole === "instructor" && myInstructorTracks.length > 0
    ? grantScopedTracks.filter((t) => myInstructorTracks.includes(t.slug))
    : grantScopedTracks;

  // Instructors see only the PEOPLE in their own courses, not the whole
  // program roster. Without this, the People and Attendance tabs listed every
  // student in the program (tracks were scoped above, students weren't).
  // Enrollments are trimmed to the same tracks so nothing else re-derives the
  // full picture from them.
  // Same for a course-scoped grant: courses were narrowed above, so narrow the
  // people and enrollments too or the roster still lists the whole program.
  if (grantTrackScope) {
    const scope = new Set(grantTrackScope);
    const visibleIds = new Set(
      studentTracks.filter((e) => scope.has(e.track_slug)).map((e) => e.student_id),
    );
    if (actorId) visibleIds.add(actorId);
    allStudents = allStudents.filter((s) => visibleIds.has(s.id));
    studentTracks = studentTracks.filter((e) => scope.has(e.track_slug));
    instructorTracks = instructorTracks.filter((e) => scope.has(e.track_slug));
  }

  if (userRole === "instructor" && myInstructorTracks.length > 0) {
    const myTrackSet = new Set(myInstructorTracks);
    const visibleIds = new Set(
      studentTracks
        .filter((e) => myTrackSet.has(e.track_slug))
        .map((e) => e.student_id),
    );
    if (actorId) visibleIds.add(actorId);
    allStudents = allStudents.filter((s) => visibleIds.has(s.id));
    studentTracks = studentTracks.filter((e) => myTrackSet.has(e.track_slug));
  }

  // Pre-launch checks for courses whose start date is near (2 weeks before
  // through 2 days after). Live on every load, so launch-morning triage is one
  // refresh instead of hand-run queries across three tools.
  const launchReadiness: Record<string, ReadinessCheck[]> = await getLaunchReadinessMany(
    tracks.filter((t) => isInLaunchWindow(t.startDate, t.startDateTbd)).map((t) => t.slug),
  );

  // Needs-you list for the course being viewed only: three small queries per
  // course, so computing it for every tab would tax every admin page load.
  const courseNeeds: Record<string, CourseSidebar> = {};
  const isCourseView = tracks.some((t) => t.slug === effectiveTab);
  if (isCourseView) courseNeeds[effectiveTab] = await getCourseSidebar(effectiveTab);

  // Signups sub-view of the course Students dropdown: rendered here (server)
  // because it reads four registration sources, then handed to the client view.
  // Managers only, same gate as the standalone Signups page.
  let signupsPanel: React.ReactNode = null;
  if (isCourseView && initialStudentSubView === "signups" && canManageStudents(userRole)) {
    const actor = await requireManager();
    const allowedTracks = await allowedTrackSlugsForActor(actor, actor.svc);
    const data = await loadSignups(allowedTracks, effectiveTab);
    const model = await computeCourseSignups(data, effectiveTab, signupsSession);
    signupsPanel = (
      <SignupsPanel
        model={model}
        summary
        sessionHref={(id) =>
          `/dashboard/admin?tab=${encodeURIComponent(effectiveTab)}&view=students&sub=signups${id ? `&session=${encodeURIComponent(id)}` : ""}`
        }
      />
    );
  }

  return (
    <div className={`mx-auto w-full max-w-2xl ${isCourseView ? "md:max-w-5xl lg:max-w-6xl" : "md:max-w-5xl"} space-y-6 px-4 sm:px-8 md:px-5 py-8`}>
      <AdminTabs
        cohorts={allCohorts}
        students={allStudents}
        tracks={tracks}
        launchReadiness={launchReadiness}
        courseNeeds={courseNeeds}
        trackExams={trackExams}
        studentTracks={studentTracks}
        instructorTracks={instructorTracks}
        programSlug={program.slug}
        surveyConfigs={surveyConfigs}
        trackPublicSurveys={trackPublicSurveys}
        trackAnsweredSurveyIds={trackAnsweredSurveyIds}
        trackEnrolledCount={trackEnrolledCount}
        trackPulseLatest={trackPulseLatest}
        trackSurveyRespondents={trackSurveyRespondents}
        userRole={userRole}
        isMaster={isMasterEmail(actorEmail)}
        assignableRoles={assignableRoles(userRole, isMasterEmail(actorEmail))}
        engagementScores={engagementScores}
        courseStats={courseStats}
        initialTab={initialTab}
        initialTrackView={initialTrackView}
        initialStudentSubView={initialStudentSubView}
        signupsPanel={signupsPanel}
        lunchLearnRecordings={lunchLearnRecordings}
        insightsData={insightsData}
        switchablePrograms={switchablePrograms}
        hiddenCourseCount={hiddenCourseCount}
        analyticsData={analyticsData}
        analyticsCourse={analyticsCourse}
        coursesData={coursesData}
        courseEngagement={courseEngagement}
        attendanceRates={attendanceRates}
        pendingPeople={pendingPeople}
        alumniEnrollments={alumniEnrollments}
        unviewedAssessments={unviewedAssessments ?? 0}
      />
    </div>
  );
}

/**
 * Cross-request TTL cache for the program-slugs-to-UUIDs lookup. Program
 * UUIDs never change, so this is safe to cache and saves one Supabase
 * round-trip per admin page navigation.
 *
 * IMPORTANT: only cache non-empty results. An empty result is almost
 * always transient (cold-start auth race, RLS context not yet warm) and
 * caching it for 60 seconds was making the admin home read "0 students
 * across every track" for up to a minute after a deploy. Re-query on the
 * next request instead.
 */
const _progIdCache = new Map<string, { data: { id: string; slug: string }[]; ts: number }>();
async function getCachedProgramIds(
  slugs: string[],
): Promise<{ id: string; slug: string }[]> {
  const key = slugs.sort().join(",");
  const cached = _progIdCache.get(key);
  if (cached && Date.now() - cached.ts < 60_000) return cached.data;
  const svc = createServiceClient();
  const { data, error } = await svc
    .from("programs")
    .select("id, slug")
    .in("slug", slugs);
  const result = (data ?? []) as { id: string; slug: string }[];
  if (error || result.length === 0) {
    if (error) console.error("[admin] getCachedProgramIds query failed:", error);
    return result;
  }
  _progIdCache.set(key, { data: result, ts: Date.now() });
  return result;
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { bulkAssignTrack } from "./actions";
import type { StudentTrackRow, InstructorTrackRow } from "./actions";
import { Users, CaretDown as ChevronDown, Check, UserCheck, Trash as Trash2, UserPlus, Plus, CircleNotch as Loader2 } from "@phosphor-icons/react";
import { Avatar } from "@/components/avatar";
import { BackLink, buttonClass, fieldInput } from "@/components/ui";
import { PendingPeopleSection, StatusPill } from "./pending-people";
import type { PendingPerson } from "@/lib/people-hub";
import { AddPeoplePanel } from "./add-people-panel";
import { type CohortRow, type StudentRow, type AdminTrackConfig } from "./admin-shared";

// ─── People Tab ───────────────────────────────────────────────────────────────

export function PeopleTab({
  students,
  cohorts,
  tracks,
  enrollments,
  instrTracks,
  engagementScores,
  isManager,
  programSlug,
  enrollmentSaving,
  instrTrackSaving,
  studentSaving,
  onUpdateStudent,
  onDeleteStudent,
  onToggleStudentTrack,
  onToggleInstructorTrack,
  onSetInstructorRole,
  onStudentAdded,
  initialTrackFilter,
  staffCohort,
  attendanceRates = null,
  embedded,
  viewSwitcher,
  pendingPeople = [],
  assignableRoles = [],
}: {
  students: StudentRow[];
  cohorts: CohortRow[];
  tracks: AdminTrackConfig[];
  enrollments: StudentTrackRow[];
  instrTracks: InstructorTrackRow[];
  engagementScores: Record<string, { total: number; attendance: number; submissions: number; reflections: number; videos: number }>;
  isManager: boolean;
  assignableRoles?: string[];
  programSlug: string;
  enrollmentSaving: string | null;
  instrTrackSaving: string | null;
  studentSaving: string | null;
  onUpdateStudent: (id: string, field: "role" | "cohort_id" | "first_name" | "last_name", value: string) => Promise<void>;
  onDeleteStudent: (id: string) => Promise<void>;
  onToggleStudentTrack: (studentId: string, trackSlug: string) => Promise<void>;
  onToggleInstructorTrack: (instructorId: string, trackSlug: string) => Promise<void>;
  /** Lead vs teaching assistant per course. Omitted where roles can't be managed. */
  onSetInstructorRole?: (instructorId: string, trackSlug: string, role: "lead" | "assistant") => Promise<void>;
  onStudentAdded: (student: StudentRow) => void;
  initialTrackFilter?: string;
  /** Course whose learners are staff: every enrollee counts as a learner. */
  staffCohort?: boolean;
  /** Sessions held + each learner's attended count, for the open course. */
  attendanceRates?: { held: number; attended: Record<string, number> } | null;
  embedded?: boolean;
  viewSwitcher?: React.ReactNode;
  pendingPeople?: PendingPerson[];
}) {
  const [searchQuery, setSearchQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState(embedded && !staffCohort ? "student" : "all");
  const isRosterLearner = (s: { role?: string | null }) => !!staffCohort || s.role === "student";
  const [trackFilter, setTrackFilter] = useState(initialTrackFilter ?? "all");
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);
  const [showBulkAssign, setShowBulkAssign] = useState(false);
  const [bulkTrack, setBulkTrack] = useState(tracks[0]?.slug ?? "");
  const [bulkSelected, setBulkSelected] = useState<Set<string>>(new Set());
  const [bulkSaving, setBulkSaving] = useState(false);
  // Inline "New group" form — student row edit panel

  const router = useRouter();

  const filtered = students.filter((s) => {
    const matchesSearch =
      !searchQuery ||
      `${s.first_name ?? ""} ${s.last_name ?? ""} ${s.email ?? ""}`
        .toLowerCase()
        .includes(searchQuery.toLowerCase());
    const matchesRole = roleFilter === "all" || s.role === roleFilter;
    const matchesTrack =
      trackFilter === "all" ||
      enrollments.some((e) => e.student_id === s.id && e.track_slug === trackFilter);
    return matchesSearch && matchesRole && matchesTrack;
  });

  // The pending list (pre-account invites/allowlist) must obey the SAME filters
  // as the roster, or picking a cohort still shows everyone's pending rows mixed
  // together. Pending people have no account yet, so role only gates them by
  // "student" vs a specific staff role.
  const filteredPending = pendingPeople.filter((p) => {
    const matchesSearch =
      !searchQuery ||
      `${p.firstName} ${p.lastName} ${p.email}`.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesTrack = trackFilter === "all" || p.trackSlugs.includes(trackFilter);
    const matchesRole = roleFilter === "all" || roleFilter === "student";
    return matchesSearch && matchesTrack && matchesRole;
  });

  function getStudentTrackSlugs(studentId: string) {
    return enrollments.filter((e) => e.student_id === studentId).map((e) => e.track_slug);
  }
  function getInstructorTrackSlugs(instructorId: string) {
    return instrTracks.filter((e) => e.student_id === instructorId).map((e) => e.track_slug);
  }
  function getTrackCount(studentId: string) {
    // The expanded card shows TEACHING (instructor_tracks) for instructors and
    // TRACKS (student_tracks enrollments) for everyone else — count from the
    // same source so the roster badge matches what you see when you expand.
    const isInstructor =
      students.find((s) => s.id === studentId)?.role === "instructor";
    const rows = isInstructor ? instrTracks : enrollments;
    return rows.filter((e) => e.student_id === studentId).length;
  }

  async function handleBulkAssign() {
    if (bulkSelected.size === 0 || !bulkTrack) return;
    setBulkSaving(true);
    try {
      await bulkAssignTrack(Array.from(bulkSelected), bulkTrack, programSlug);
      setBulkSelected(new Set());
      setShowBulkAssign(false);
    } catch (e) {
      console.error("Bulk assign failed:", e);
    }
    setBulkSaving(false);
  }


  return (
    <div className="space-y-6">
      {!embedded && (
        <BackLink href="/dashboard/admin" label="Admin" />
      )}
      {/* Header */}
      {(!embedded || isManager) && (
      <div className="flex flex-wrap items-start justify-between gap-3">
        {/* Program-wide totals used to render here — removed: they ignored the
           filters below and fought the filtered counts (three unrelated
           numbers on one screen). The summary strip by the filters is now the
           only count, always describing the list it sits above. */}
        <div />
        {!embedded && isManager && (
          <div className="flex flex-wrap items-center gap-2">
            {showBulkAssign ? (
              <>
                <div className="relative">
                  <select
                    value={bulkTrack}
                    onChange={(e) => setBulkTrack(e.target.value)}
                    className="appearance-none border border-rule bg-white pl-3 pr-7 py-2 text-xs font-medium text-ink focus:border-ink-faint"
                  >
                    {tracks.map((t) => (
                      <option key={t.slug} value={t.slug}>{t.shortName}</option>
                    ))}
                  </select>
                  <ChevronDown size={12} className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 text-ink-faint" />
                </div>
                <button
                  type="button"
                  onClick={handleBulkAssign}
                  disabled={bulkSelected.size === 0 || bulkSaving}
                  className={buttonClass("primary", "sm")}
                >
                  {bulkSaving ? <Loader2 size={12} className="animate-spin" /> : <UserCheck size={12} />}
                  Assign{bulkSelected.size > 0 ? ` (${bulkSelected.size})` : ""}
                </button>
                <button
                  type="button"
                  onClick={() => { setShowBulkAssign(false); setBulkSelected(new Set()); }}
                  className={buttonClass("secondary", "sm")}
                >
                  Cancel
                </button>
              </>
            ) : (
              <>
                <button
                  type="button"
                  onClick={() => setShowBulkAssign(true)}
                  className={buttonClass("secondary", "sm")}
                >
                  <Users size={13} />
                  Bulk assign
                </button>
                <button
                  type="button"
                  onClick={() => setShowAddForm((v) => !v)}
                  className={buttonClass("primary", "sm")}
                >
                  <UserPlus size={13} />
                  Add people
                </button>
              </>
            )}
          </div>
        )}
      </div>
      )}

      {/* Add people — one panel, two modes (invite by email / add directly). */}
      {!embedded && showAddForm && (
        <AddPeoplePanel
          tracks={tracks}
          programSlug={programSlug}
          assignableRoles={assignableRoles}
          onStudentAdded={onStudentAdded}
          onClose={() => setShowAddForm(false)}
        />
      )}

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2">
        {viewSwitcher}
        {!embedded && (
          <input
            type="search"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by name or email…"
            className={`${fieldInput} flex-1 min-w-[200px]`}
          />
        )}
        {!embedded && isManager && (
          <div className="relative">
            <select
              value={roleFilter}
              onChange={(e) => setRoleFilter(e.target.value)}
              className="appearance-none border border-rule bg-neutral-50 pl-3 pr-7 py-2 text-sm text-ink focus:border-ink-faint"
            >
              <option value="all">All roles</option>
              <option value="student">Students</option>
              <option value="instructor">Instructors</option>
              <option value="admin">Admins</option>
            </select>
            <ChevronDown size={12} className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 text-ink-faint" />
          </div>
        )}
        {!embedded && isManager && tracks.length > 0 && (
          <div className="relative min-w-0">
            <select
              value={trackFilter}
              onChange={(e) => setTrackFilter(e.target.value)}
              className="max-w-[14rem] sm:max-w-none appearance-none border border-rule bg-neutral-50 pl-3 pr-7 py-2 text-sm text-ink focus:border-ink-faint"
            >
              <option value="all">All tracks</option>
              {tracks.map((t) => (
                <option key={t.slug} value={t.slug}>{t.shortName}</option>
              ))}
            </select>
            <ChevronDown size={12} className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 text-ink-faint" />
          </div>
        )}
      </div>

      {/* Summary strip — the ONE set of numbers on this page, always
         describing the list below with the current filters applied. Replaces
         the program-wide header count, "N shown", and the Pending section's
         own count, which each measured a different population. */}
      {(() => {
        const joined = filtered.filter((s) => isRosterLearner(s)).length;
        const staff = filtered.length - joined;
        const invited = filteredPending.filter((p) => p.inviteSent).length;
        const allowlisted = filteredPending.length - invited;
        const parts = [
          `${joined} joined`,
          ...(invited > 0 ? [`${invited} invited`] : []),
          ...(allowlisted > 0 ? [`${allowlisted} allowlisted, not yet invited`] : []),
          ...(staff > 0 ? [`${staff} staff`] : []),
        ];
        return <p className="text-sm text-ink-soft">{parts.join(" · ")}</p>;
      })()}

      {/* Roster — ONE list: account holders first, then pending people
         (invited/allowlisted, no account yet) as rows in the same panel, so
         the whole pipeline reads as a single list instead of stacked
         sections. Pending rows are managers-only (the invite/remove actions
         are manage_students). */}
      <div className="divide-y divide-neutral-100 overflow-hidden panel">
        {filtered.length === 0 && (!isManager || filteredPending.length === 0) && (
          <p className="p-4 text-sm text-ink-soft">No people found.</p>
        )}
        {filtered.map((s) => {
          const fullName =
            [s.first_name, s.last_name].filter(Boolean).join(" ") || "—";
          const isExpanded = expandedId === s.id;
          const trackCount = getTrackCount(s.id);
          // Attendance only means something for a learner in the open course —
          // staff don't check in, and the rate is course-scoped.
          const attendanceRate =
            attendanceRates && isRosterLearner(s)
              ? (() => {
                  const attended = attendanceRates.attended[s.id] ?? 0;
                  const held = attendanceRates.held;
                  return {
                    attended,
                    held,
                    // held is the count of distinct sessions that have any
                    // attendance recorded, so it's 0 for a course that hasn't
                    // met yet (and after a failed fetch). Without this guard
                    // 0/0 renders "NaN%" in the roster.
                    pct: held > 0 ? Math.round((attended / held) * 100) : 0,
                  };
                })()
              : null;
          const studentSlugs = getStudentTrackSlugs(s.id);
          const instructorSlugs = getInstructorTrackSlugs(s.id);

          return (
            <div key={s.id}>
              <div
                className="flex items-center gap-3 px-4 py-3 hover:bg-paper-tint-soft cursor-pointer select-none"
                onClick={() => setExpandedId(isExpanded ? null : s.id)}
              >
                {showBulkAssign && s.role === "student" && (
                  <input
                    type="checkbox"
                    checked={bulkSelected.has(s.id)}
                    onClick={(e) => e.stopPropagation()}
                    onChange={(e) => {
                      setBulkSelected((prev) => {
                        const next = new Set(prev);
                        if (e.target.checked) next.add(s.id);
                        else next.delete(s.id);
                        return next;
                      });
                    }}
                    className="h-4 w-4 shrink-0 rounded border-rule accent-neutral-900"
                  />
                )}
                <Avatar
                  firstName={s.first_name ?? ""}
                  lastName={s.last_name ?? ""}
                  size="sm"
                />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-ink truncate">
                    {fullName}
                  </p>
                  <p className="text-xs text-ink-faint truncate">{s.email}</p>
                  <p className="text-micro text-ink-faint truncate">
                    {s.last_activity_at
                      ? `Last active: ${new Date(s.last_activity_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`
                      : s.last_seen_at
                      ? `Last login: ${new Date(s.last_seen_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`
                      : "Never logged in"}
                  </p>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  {attendanceRate && (
                    <span
                      className="text-micro tabular-nums hidden sm:block text-ink-soft"
                      title={`Attended ${attendanceRate.attended} of ${attendanceRate.held} sessions held`}
                    >
                      {attendanceRate.pct}% attendance
                    </span>
                  )}
                  <span className="text-micro text-ink-faint tabular-nums hidden sm:block">
                    {trackCount} {trackCount === 1 ? "track" : "tracks"}
                  </span>
                  {isRosterLearner(s) && (
                    <StatusPill status={s.last_activity_at ? "active" : "joined"} />
                  )}
                  <span
                    className={`inline-block rounded-full px-2 py-0.5 text-micro font-medium ${
                      s.role === "student"
                        ? "bg-paper-tint text-ink-soft"
                        : s.role === "instructor"
                          ? "bg-blue-50 text-blue-700"
                          : "bg-amber-50 text-amber-700"
                    }`}
                  >
                    {s.role}
                  </span>
                  <ChevronDown
                    size={14}
                    className={`text-ink-faint transition-transform ${isExpanded ? "rotate-180" : ""}`}
                  />
                </div>
              </div>

              {isExpanded && (
                <div
                  className="border-t border-rule-soft bg-neutral-50 px-4 py-4 space-y-4"
                  onClick={(e) => e.stopPropagation()}
                >
                  {/* Name — saves on blur or Enter. Fixes typos/casing for the
                     certificate and Zoom join without asking the student. */}
                  <div className="flex flex-wrap gap-3">
                    {([["first_name", "First name"], ["last_name", "Last name"]] as const).map(
                      ([field, label]) => (
                        <div key={field}>
                          <label className="text-micro font-medium uppercase tracking-wide text-ink-soft">
                            {label}
                          </label>
                          <input
                            type="text"
                            defaultValue={s[field] ?? ""}
                            disabled={studentSaving === s.id}
                            onBlur={(e) => {
                              const v = e.target.value.trim();
                              if (v && v !== (s[field] ?? "")) onUpdateStudent(s.id, field, v);
                              else e.target.value = s[field] ?? "";
                            }}
                            onKeyDown={(e) => {
                              if (e.key === "Enter") e.currentTarget.blur();
                            }}
                            className="mt-1 block w-40 border border-rule bg-white px-3 py-2 text-xs font-medium text-ink focus:border-ink-faint disabled:opacity-60"
                          />
                        </div>
                      ),
                    )}
                  </div>

                  {/* Role + cohort */}
                  <div className="flex flex-wrap gap-3">
                    <div>
                      <label className="text-micro font-medium uppercase tracking-wide text-ink-soft">
                        Role
                      </label>
                      <div className="relative mt-1">
                        {/* Only roles the actor may grant are shown; the select
                           is disabled for anyone they don't outrank (the server
                           enforces the same rule in updateStudentAction). */}
                        <select
                          value={s.role}
                          disabled={studentSaving === s.id || !assignableRoles.includes(s.role)}
                          onChange={(e) => onUpdateStudent(s.id, "role", e.target.value)}
                          className="appearance-none border border-rule bg-white pl-3 pr-7 py-2 text-xs font-medium text-ink focus:border-ink-faint disabled:opacity-60"
                        >
                          {([
                            ["student", "Student"],
                            ["instructor", "Instructor"],
                            ["admin", "Admin"],
                            ["super_admin", "Super Admin"],
                          ] as const)
                            .filter(([value]) => assignableRoles.includes(value) || value === s.role)
                            .map(([value, label]) => (
                              <option key={value} value={value}>{label}</option>
                            ))}
                        </select>
                        <ChevronDown size={12} className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 text-ink-faint" />
                      </div>
                    </div>
                    {/* The Group (cohort) selector used to render here. Removed
                       2026-08-06: enrollment lives in the Tracks chips below;
                       the cohort dropdown only surfaced stale spring-era rows
                       and confused course-based programs. cohort_id data is
                       untouched (auto-assignment at signup still works). */}
                  </div>

                  {/* Track chips — every track is rendered; the filled "✓"
                     chips are the student's current enrollments, the
                     outlined "+" chips are tracks they're not in (click to
                     add). Previously labeled "Enrolled tracks" which made
                     the "+" chips read like current memberships. */}
                  {tracks.length > 0 && (
                    <div>
                      <div className="mb-2 flex items-baseline gap-3">
                        <p className="text-micro font-medium uppercase tracking-wide text-ink-soft">
                          {s.role === "instructor" ? "Teaching" : "Tracks"}
                        </p>
                        <p className="text-micro text-ink-faint">
                          ✓ enrolled · + click to add
                        </p>
                      </div>
                      <div className="flex flex-wrap gap-1.5">
                        {tracks.map((t) => {
                          const savingKey = `${s.id}-${t.slug}`;
                          const isInstructor = s.role === "instructor";
                          const enrolled = isInstructor
                            ? instructorSlugs.includes(t.slug)
                            : studentSlugs.includes(t.slug);
                          const isSaving = isInstructor
                            ? instrTrackSaving === savingKey
                            : enrollmentSaving === savingKey;
                          return (
                            <button
                              key={t.slug}
                              type="button"
                              onClick={() =>
                                isInstructor
                                  ? onToggleInstructorTrack(s.id, t.slug)
                                  : onToggleStudentTrack(s.id, t.slug)
                              }
                              disabled={isSaving}
                              className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-micro font-medium transition-colors disabled:opacity-60 ${
                                enrolled
                                  ? "bg-ink text-white"
                                  : "border border-rule bg-white text-ink-soft hover:border-ink-faint hover:text-ink-soft"
                              }`}
                            >
                              {isSaving ? (
                                <Loader2 size={10} className="animate-spin" />
                              ) : enrolled ? (
                                <Check size={10} />
                              ) : (
                                <Plus size={10} />
                              )}
                              {t.shortName}
                            </button>
                          );
                        })}
                      </div>
                      {s.role === "instructor" && onSetInstructorRole && instructorSlugs.length > 0 && (
                        <div className="mt-3 space-y-1.5">
                          <p className="text-micro text-ink-faint">
                            Assistants can make any edit. The lead gets a daily recap of their changes.
                          </p>
                          {tracks
                            .filter((t) => instructorSlugs.includes(t.slug))
                            .map((t) => {
                              const role =
                                instrTracks.find((e) => e.student_id === s.id && e.track_slug === t.slug)?.role ?? "lead";
                              const saving = instrTrackSaving === `${s.id}-${t.slug}-role`;
                              return (
                                <div key={t.slug} className="flex items-center justify-between gap-3">
                                  <span className="truncate text-xs text-ink">{t.shortName}</span>
                                  <div
                                    role="group"
                                    aria-label={`Role on ${t.shortName}`}
                                    className="inline-flex shrink-0 rounded-full border border-rule p-0.5"
                                  >
                                    {(["lead", "assistant"] as const).map((r) => (
                                      <button
                                        key={r}
                                        type="button"
                                        aria-pressed={role === r}
                                        disabled={saving || role === r}
                                        onClick={() => onSetInstructorRole(s.id, t.slug, r)}
                                        className={`rounded-full px-2.5 py-0.5 text-micro font-medium transition-colors disabled:cursor-default ${
                                          role === r ? "bg-ink text-white" : "text-ink-soft hover:text-ink"
                                        }`}
                                      >
                                        {r === "lead" ? "Lead" : "Assistant"}
                                      </button>
                                    ))}
                                  </div>
                                </div>
                              );
                            })}
                        </div>
                      )}
                    </div>
                  )}

                  {/* Engagement snapshot (only if scores were fetched) */}
                  {isRosterLearner(s) && engagementScores[s.id] && (
                    <div className="flex flex-wrap items-center gap-3 text-xs text-ink-soft">
                      <span>
                        <strong className="font-semibold text-ink">
                          {engagementScores[s.id].total}
                        </strong>
                        /100 engagement
                      </span>
                      <span className="text-ink-faint">·</span>
                      <span>{engagementScores[s.id].attendance} attended</span>
                      <span className="text-ink-faint">·</span>
                      <span>{engagementScores[s.id].submissions} submitted</span>
                      <span className="text-ink-faint">·</span>
                      <span>{engagementScores[s.id].reflections} reflected</span>
                      <span className="text-ink-faint">·</span>
                      <span>{engagementScores[s.id].videos} watched</span>
                    </div>
                  )}

                  {/* Remove person */}
                  {isManager && (
                    <div className="border-t border-rule pt-3">
                      {confirmDeleteId === s.id ? (
                        <div className="flex items-center gap-2">
                          <span className="text-xs text-ink-soft">
                            Remove {s.first_name || s.email}?
                          </span>
                          <button
                            type="button"
                            onClick={() => {
                              onDeleteStudent(s.id);
                              setConfirmDeleteId(null);
                              setExpandedId(null);
                            }}
                            className="text-xs font-medium text-red-600 hover:text-red-700"
                          >
                            Confirm
                          </button>
                          <button
                            type="button"
                            onClick={() => setConfirmDeleteId(null)}
                            className="text-xs text-ink-faint hover:text-ink-soft"
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <button
                          type="button"
                          onClick={() => setConfirmDeleteId(s.id)}
                          className="inline-flex items-center gap-1.5 text-xs text-ink-faint hover:text-red-500 transition-colors"
                        >
                          <Trash2 size={12} />
                          Remove person
                        </button>
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
        {isManager && filteredPending.length > 0 && (
          <PendingPeopleSection
            inline
            pending={filteredPending}
            trackNames={Object.fromEntries(tracks.map((t) => [t.slug, t.shortName || t.name]))}
          />
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { updateCourseAction, applyWeeklyScheduleAction } from "../../actions";
import { uploadLandingImageAction } from "../../../landing/actions";
import type { UpdateCourseResult, ApplyScheduleResult } from "../../actions";
import { Field, buttonClass, fieldInput } from "@/components/ui";
import { compressImage } from "@/lib/compress-image";

const PHASE_OPTIONS = [
  { value: "foundation", label: "Foundation" },
  { value: "core",       label: "Core" },
  { value: "workshop",   label: "Workshop" },
  { value: "exit",       label: "Exit" },
  { value: "other",      label: "Other" },
];

export function EditCourseForm({
  programSlug,
  trackSlug,
  initialName,
  initialInstructor,
  initialTotalWeeks,
  initialSessionsPerWeek,
  initialPhase,
  initialCoverImageUrl = "",
  initialFirstDate = "",
  todayIso,
  initialTime = "",
  initialDuration = "",
}: {
  programSlug: string;
  trackSlug: string;
  initialName: string;
  initialInstructor: string;
  initialTotalWeeks: number;
  initialSessionsPerWeek: number;
  initialPhase: string;
  /** Course cover image shown on the learner dashboard card. */
  initialCoverImageUrl?: string;
  /** First dated unit, YYYY-MM-DD. Empty = no schedule set yet. */
  initialFirstDate?: string;
  /** Today in the cohort timezone, resolved on the server so the past-date
   *  check can't disagree between render and hydration. */
  todayIso: string;
  /** "HH:MM" ET wall clock from the first dated unit. */
  initialTime?: string;
  initialDuration?: string;
}) {
  const [name, setName] = useState(initialName);
  const [instructor, setInstructor] = useState(initialInstructor);
  const [totalWeeks, setTotalWeeks] = useState(String(initialTotalWeeks));
  const [sessionsPerWeek, setSessionsPerWeek] = useState(String(initialSessionsPerWeek));
  const [phase, setPhase] = useState(initialPhase);
  const [coverImageUrl, setCoverImageUrl] = useState(initialCoverImageUrl);
  const [uploadingCover, setUploadingCover] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState(false);

  // Schedule section — separate save so a schedule mistake can't block a
  // name edit and vice versa.
  const [firstDate, setFirstDate] = useState(initialFirstDate);
  // Compared as YYYY-MM-DD strings, which sort chronologically, so no Date
  // parsing and no timezone to get wrong.
  const firstDateIsPast = !!firstDate && firstDate < todayIso;
  const [time, setTime] = useState(initialTime);
  const [duration, setDuration] = useState(initialDuration);
  const [schedPending, setSchedPending] = useState(false);
  const [schedError, setSchedError] = useState<string | null>(null);
  const [schedSaved, setSchedSaved] = useState<string | null>(null);

  async function handleSchedule(e: React.FormEvent) {
    e.preventDefault();
    setSchedError(null);
    setSchedSaved(null);
    setSchedPending(true);
    try {
      const res: ApplyScheduleResult = await applyWeeklyScheduleAction(programSlug, trackSlug, {
        firstDate,
        time,
        durationMinutes: parseInt(duration, 10),
      });
      if (res.success) setSchedSaved(res.summary);
      else setSchedError(res.error);
    } catch {
      setSchedError("Something went wrong. Please try again.");
    } finally {
      setSchedPending(false);
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSaved(false);
    setPending(true);
    try {
      const res: UpdateCourseResult = await updateCourseAction(programSlug, trackSlug, {
        name,
        instructor,
        totalWeeks: parseInt(totalWeeks, 10),
        sessionsPerWeek: parseInt(sessionsPerWeek, 10),
        phase,
        coverImageUrl,
      });
      if (res.success) {
        setSaved(true);
      } else {
        setError(res.error);
      }
    } catch {
      setError("Something went wrong. Please try again.");
    } finally {
      setPending(false);
    }
  }

  return (
    <div className="space-y-8">
    <form onSubmit={handleSubmit} className="space-y-5">
      <Field label="Course name">
        <input
          id="name"
          type="text"
          required
          value={name}
          onChange={(e) => setName(e.target.value)}
          className={fieldInput}
        />
      </Field>

      <Field label="Instructor">
        <input
          id="instructor"
          type="text"
          required
          value={instructor}
          onChange={(e) => setInstructor(e.target.value)}
          className={fieldInput}
        />
      </Field>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <Field label="Length (weeks)">
          <input
            id="totalWeeks"
            type="number"
            required
            min={1}
            max={52}
            value={totalWeeks}
            onChange={(e) => setTotalWeeks(e.target.value)}
            className={fieldInput}
          />
        </Field>
        <Field label="Sessions / week">
          <input
            id="sessionsPerWeek"
            type="number"
            required
            min={1}
            max={7}
            value={sessionsPerWeek}
            onChange={(e) => setSessionsPerWeek(e.target.value)}
            className={fieldInput}
          />
        </Field>
      </div>

      <Field label="Group">
        <select
          id="phase"
          value={phase}
          onChange={(e) => setPhase(e.target.value)}
          className={fieldInput}
        >
          {PHASE_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      </Field>

      <Field label="Cover image" hint="shown on the learner dashboard card — leave empty for none">
        <div className="flex items-center gap-2">
          <input
            type="text"
            placeholder="https://…/cover.jpg"
            value={coverImageUrl}
            onChange={(e) => setCoverImageUrl(e.target.value)}
            className={fieldInput}
          />
          <label className={`${buttonClass("secondary", "sm")} shrink-0 cursor-pointer`}>
            {uploadingCover ? "Uploading…" : "Upload"}
            <input
              type="file"
              accept="image/jpeg,image/png,image/webp"
              className="sr-only"
              disabled={uploadingCover}
              onChange={async (e) => {
                const file = e.target.files?.[0];
                e.target.value = "";
                if (!file) return;
                setUploadingCover(true);
                setError(null);
                try {
                  const fd = new FormData();
                  fd.set("file", await compressImage(file));
                  const res = await uploadLandingImageAction(fd);
                  if (res.success) setCoverImageUrl(res.url);
                  else setError(res.error);
                } catch {
                  setError("Upload failed. Please try again.");
                } finally {
                  setUploadingCover(false);
                }
              }}
            />
          </label>
        </div>
        {coverImageUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={coverImageUrl}
            alt="Course cover preview"
            className="mt-2 h-24 w-full rounded-lg border border-rule object-cover"
          />
        )}
      </Field>

      {error && (
        <p className="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </p>
      )}

      {saved && (
        <p className="rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700">
          ✓ Changes saved
        </p>
      )}

      <div className="flex gap-3">
        <button
          type="submit"
          disabled={pending}
          className={`${buttonClass("primary", "md")} flex-1`}
        >
          {pending ? "Saving…" : "Save Changes"}
        </button>
        <a
          href="/dashboard/admin/programs"
          className={`${buttonClass("secondary", "md")} flex-1`}
        >
          Back to Courses
        </a>
      </div>
    </form>

    {/* Session schedule — the answer to "where do I set when this course
       meets". One weekly slot stamps a date + ET time + duration onto every
       unit, which is what drives the course calendar, the .ics feed, and the
       "Today / Live now · Join" panel. */}
    <form onSubmit={handleSchedule} className="space-y-4 border-t border-rule pt-6">
      <div>
        <h2 className="text-sm font-semibold text-ink">Session schedule</h2>
        <p className="mt-1 text-xs text-ink-faint">
          When this course meets. Sessions repeat weekly from the first date —
          every unit gets its date and time, shown on the course calendar and
          used for the live Join button. Times are Eastern (ET).
        </p>
      </div>
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <Field label="First session">
          <input
            id="firstDate"
            type="date"
            required
            value={firstDate}
            onChange={(e) => setFirstDate(e.target.value)}
            className={fieldInput}
          />
          {firstDateIsPast && (
            // Not a block: backfilling a cohort that already ran is legitimate.
            // But a course whose first session is in the past computes its
            // current week from that date, so a mistyped year reads as
            // "Week 7 of 7" on a program that hasn't started.
            <p className="mt-1.5 text-xs text-amber-700">
              That date is in the past. Check the year — a past start date makes
              the course look finished.
            </p>
          )}
        </Field>
        <Field label="Start time (ET)">
          <input
            id="time"
            type="time"
            required
            value={time}
            onChange={(e) => setTime(e.target.value)}
            className={fieldInput}
          />
        </Field>
        <Field label="Length (minutes)">
          <input
            id="duration"
            type="number"
            required
            min={5}
            max={600}
            step={5}
            value={duration}
            onChange={(e) => setDuration(e.target.value)}
            className={fieldInput}
          />
        </Field>
      </div>

      {schedError && (
        <p className="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {schedError}
        </p>
      )}
      {schedSaved && (
        <p className="rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-700">
          ✓ Schedule set — {schedSaved}
        </p>
      )}

      <button
        type="submit"
        disabled={schedPending}
        className={buttonClass("dark", "md")}
      >
        {schedPending ? "Applying…" : "Apply schedule"}
      </button>
    </form>
    </div>
  );
}

"use client";

import { useState } from "react";
import { createCourseAction } from "../actions";
import type { CreateCourseResult } from "../actions";
import { toSlug } from "@/lib/programs/slug";
import { Field, fieldInput, buttonClass } from "@/components/ui";

const PHASE_OPTIONS = [
  { value: "foundation", label: "Foundation" },
  { value: "core",       label: "Core" },
  { value: "workshop",   label: "Workshop" },
  { value: "exit",       label: "Exit" },
  { value: "other",      label: "Other" },
];

// Programs that surface on the bccacademy.io hub. Must match COURSE_PROGRAM_SLUGS
// in ../actions.ts.
const PROGRAM_OPTIONS = [
  { value: "catalyst",            label: "Catalyst" },
  { value: "beyond-code-centers", label: "Beyond Code Centers" },
  { value: "atg",                 label: "Beyond the Game" },
];

export function CreateCourseForm({
  extraProgram,
  currentProgram,
}: {
  /** Admin-created organization (is_dynamic), which has no TS config and so
   *  never appears in PROGRAM_OPTIONS. Passed through from ?program=. */
  extraProgram?: { slug: string; name: string };
  /** The program context the admin is standing in. Standalone programs (BGC,
   *  Forte, dynamic orgs) scope the picker to themselves; the hub programs
   *  keep the full hub list. */
  currentProgram?: { slug: string; name: string };
} = {}) {
  const hubSlugs = PROGRAM_OPTIONS.map((o) => o.value);
  const programOptions = extraProgram
    ? [{ value: extraProgram.slug, label: extraProgram.name }, ...PROGRAM_OPTIONS]
    : currentProgram && !hubSlugs.includes(currentProgram.slug)
      ? [{ value: currentProgram.slug, label: currentProgram.name }]
      : PROGRAM_OPTIONS;
  const [name, setName] = useState("");
  const [instructor, setInstructor] = useState("");
  const [totalWeeks, setTotalWeeks] = useState("");
  const [sessionsPerWeek, setSessionsPerWeek] = useState("");
  const [phase, setPhase] = useState("core");
  const [program, setProgram] = useState(
    extraProgram?.slug ?? currentProgram?.slug ?? "catalyst",
  );
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<Extract<CreateCourseResult, { success: true }> | null>(null);
  const [copied, setCopied] = useState(false);

  const slug = toSlug(name);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setPending(true);

    try {
      const res = await createCourseAction({
        name,
        instructor,
        totalWeeks: parseInt(totalWeeks, 10),
        sessionsPerWeek: parseInt(sessionsPerWeek, 10),
        phase,
        programSlug: program,
      });

      if (res.success) {
        setResult(res);
      } else {
        setError(res.error);
      }
    } catch {
      setError("Something went wrong. Please try again.");
    } finally {
      setPending(false);
    }
  }

  function handleCopy() {
    if (!result) return;
    navigator.clipboard.writeText(result.joinUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  if (result) {
    return (
      <div className="space-y-4">
        <div className="rounded-lg border border-green-200 bg-green-50 p-5 space-y-4">
          <p className="text-sm font-semibold text-green-800">✓ Course created</p>

          <div className="rounded-lg border border-green-200 bg-white p-4 space-y-3">
            <p className="font-mono text-sm text-green-700 break-all">{result.joinUrl}</p>
            <button
              type="button"
              onClick={handleCopy}
              className={`${buttonClass("primary", "md")} w-full`}
            >
              {copied ? "Copied!" : "Copy join link"}
            </button>
          </div>

          <p className="text-xs text-green-700">
            Share this link to start enrolling students.
          </p>

          {result.landingSlug && (
            <div className="rounded-lg border border-green-200 bg-white p-4">
              <p className="text-sm font-semibold text-neutral-900">
                {result.landingCreated
                  ? "A landing page was created with it"
                  : "This course already has a landing page"}
              </p>
              <p className="mt-1 text-xs text-neutral-600">
                {result.landingCreated
                  ? "It's a draft, so nothing is public yet. Add the copy and publish when it's ready."
                  : "It's already pointing at this course."}
              </p>
              <a
                href={`/dashboard/admin/landing/${result.landingSlug}`}
                className={`${buttonClass("secondary", "md")} mt-3 w-full`}
              >
                {result.landingCreated ? "Write the landing page →" : "Open the landing page →"}
              </a>
            </div>
          )}
        </div>

        <button
          type="button"
          onClick={() => {
            document.cookie = `program-override=${program}; path=/; max-age=86400`;
            window.location.href = `/dashboard/admin?tab=${result.slug}`;
          }}
          className={`${buttonClass("primary", "md")} w-full`}
        >
          Manage this course →
        </button>

        <a
          href="/dashboard/admin/programs"
          className={`${buttonClass("secondary", "md")} w-full`}
        >
          View all courses
        </a>

        <button
          type="button"
          onClick={() => {
            setResult(null);
            setError(null);
            setName("");
            setInstructor("");
            setTotalWeeks("");
            setSessionsPerWeek("");
            setCopied(false);
          }}
          className="w-full text-center text-sm text-ink-soft hover:text-ink-soft transition-colors py-1"
        >
          + Create another course
        </button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      <Field label="Course name">
        <input
          id="name"
          type="text"
          required
          placeholder="e.g. Salesforce Admin"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className={fieldInput}
        />
        {slug && (
          <p className="mt-1.5 font-mono text-xs text-ink-soft">
            bccacademy.io/join/{program}?track=<span className="text-primary">{slug}</span>
          </p>
        )}
      </Field>

      <Field label="Program" hint="which program this course belongs to">
        <select
          id="program"
          value={program}
          onChange={(e) => setProgram(e.target.value)}
          className={fieldInput}
        >
          {programOptions.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      </Field>

      <Field label="Instructor">
        <input
          id="instructor"
          type="text"
          required
          placeholder="e.g. Marcus Williams"
          value={instructor}
          onChange={(e) => setInstructor(e.target.value)}
          className={fieldInput}
        />
      </Field>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <Field label="Length (weeks)">
          <input
            id="totalWeeks"
            type="number"
            required
            min={1}
            max={52}
            placeholder="12"
            value={totalWeeks}
            onChange={(e) => setTotalWeeks(e.target.value)}
            className={fieldInput}
          />
        </Field>
        <Field label="Sessions / week">
          <input
            id="sessionsPerWeek"
            type="number"
            required
            min={1}
            max={7}
            placeholder="2"
            value={sessionsPerWeek}
            onChange={(e) => setSessionsPerWeek(e.target.value)}
            className={fieldInput}
          />
        </Field>
      </div>

      <Field label="Group">
        <select
          id="phase"
          value={phase}
          onChange={(e) => setPhase(e.target.value)}
          className={fieldInput}
        >
          {PHASE_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      </Field>

      {error && (
        <p className="rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </p>
      )}

      <button
        type="submit"
        disabled={pending}
        className={`${buttonClass("primary", "md")} w-full`}
      >
        {pending ? "Creating…" : "Create Course"}
      </button>
    </form>
  );
}

