                      {s.meetingLink && (
                        <a href={s.meetingLink} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1 text-xs text-ink-faint hover:text-ink">
                          Open link <ExternalLink size={12} />
                        </a>
                      )}
                    </div>
                  </div>
                ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  )}

      {/* Students tab — peer views you switch between (never stacked, so the
         people list isn't duplicated). Cohort courses get Attendance (live
         sessions); self-paced courses get Progress instead (watched +
         uploaded), since there's no class to attend. */}
      {trackView === "students" && (() => {
        // Attendance only for cohort courses; Progress only for self-paced.
        // Never leave the view stuck on an option that's hidden for this track.
        const showAttendance = !activeTrack.selfPaced;
        const showProgress = !!activeTrack.selfPaced;
        const subView =
          (studentSubView === "attendance" && !showAttendance) ||
          (studentSubView === "progress" && !showProgress) ||
          (studentSubView === "signups" && !signupsPanel)
            ? "students"
            : studentSubView;
        const viewSwitcher = (
          <div className="relative">
            <select
              value={subView}
              onChange={(e) => {
                // Signups load four registration sources on the server, so it
                // is a URL view; the rest are client state.
                if (e.target.value === "signups") {
                  router.push(`/dashboard/admin?tab=${encodeURIComponent(activeTrack.slug)}&view=students&sub=signups`);
                  return;
                }
                setStudentSubView(e.target.value as Exclude<StudentSubView, "signups">);
              }}
              className="appearance-none panel pl-3 pr-8 py-2 text-sm font-medium text-ink focus:border-ink-faint"
            >
              <option value="students">Roster</option>
              {isManager && <option value="signups">Signups</option>}
              {showAttendance && <option value="attendance">Attendance</option>}
              {showProgress && <option value="progress">Progress</option>}
              <option value="work">Submissions</option>
              <option value="certificates">Certificates</option>
            </select>
            <ChevronDown size={13} className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 text-ink-faint" />
          </div>
        );
        return (
          <div className="space-y-4">
            {subView === "students" && (
              <PeopleTab
                students={students}
                cohorts={cohorts}
                tracks={tracks}
                enrollments={enrollments}
                instrTracks={instrTracks}
                engagementScores={engagementScores}
                isManager={isManager}
                assignableRoles={assignableRoles}
                programSlug={programSlug}
                enrollmentSaving={enrollmentSaving}
                instrTrackSaving={instrTrackSaving}
                studentSaving={studentSaving}
                onUpdateStudent={updateStudent}
                onDeleteStudent={deleteStudent}
                onToggleStudentTrack={toggleTrackEnrollment}
                onToggleInstructorTrack={toggleInstructorTrack}
                onSetInstructorRole={setInstructorTrackRole}
                onStudentAdded={(s) => setStudents((prev) => [...prev, s])}
                initialTrackFilter={activeTrack.slug}
                staffCohort={activeTrack.staffCohort}
                attendanceRates={attendanceRates}
                embedded
                viewSwitcher={viewSwitcher}
              />
            )}

            {subView === "signups" && signupsPanel && (
              <>
                <div>{viewSwitcher}</div>
                {signupsPanel}
              </>
            )}

            {subView === "attendance" && (
              <AttendanceTab
                students={trackLearners}
                tracks={[activeTrack]}
                scopeLabel={activeTrack.shortName}
                embedded
                viewSwitcher={viewSwitcher}
              />
            )}

            {subView === "progress" && (
              <ProgressTab
                students={trackLearners}
                trackSlug={activeTrack.slug}
                totalWeeks={activeTrack.totalWeeks}
                viewSwitcher={viewSwitcher}
              />
            )}

            {subView === "work" && (
              <StudentWorkTab
                tracks={[activeTrack]}
                programSlug={programSlug}
                viewSwitcher={viewSwitcher}
              />
            )}

            {subView === "certificates" && (
              <CertificatesPanel
                students={trackLearners}
                trackSlug={activeTrack.slug}
                programSlug={programSlug}
                viewSwitcher={viewSwitcher}
              />
            )}
          </div>
        );
      })()}

      {/* Surveys sub-view — scoped to this track. ONE surface: the index
         of this course's forms and exams with response rates. Summaries
         and answer-level data live one level down, in each form's report —
         the embedded program-insights panel duplicated this list through
         its Form dropdown and only rendered on a full-page load, so the
         tab showed different content depending on how you arrived. */}
      {trackView === "surveys" && (
        <div className="space-y-8">
          <TrackInsightsSection
            trackSlug={activeTrack.slug}
            trackShortName={activeTrack.shortName}
            programSlug={programSlug}
            // Only surveys this track's students actually take. A track
            // opted out via skipForTracks (Security+ vs the AI
            // Fundamentals surveys) shouldn't list them; a companion
            // (MASS) follows the course it wraps around.
            // Evidence-based, not opt-out: list only surveys this course's
            // students have actually answered (plus the skip rule). The old
            // opt-out-only filter surfaced every program survey under every
            // course. Exception: a survey ASSIGNED to this course
            // (appliesToTracks) always lists — at "0 of N" until people
            // respond — otherwise a survey you're actively driving is
            // invisible right when you need to watch it fill in (the HFS
            // impact survey sat at zero with no row at all, 2026-08-17).
            surveyConfigs={surveyConfigs.filter((s) => {
              const home = activeTrack.companionOf ?? activeTrack.slug;
              if (s.skipForTracks?.includes(home)) return false;
              // A survey assigned to specific courses lists ONLY under
              // those courses. Assignment beats evidence: cross-enrolled
              // learners' answers otherwise surface another course's
              // survey here (HFS "How Did We Do?" under MASS, 2026-08-27).
              // A survey may name its courses, its programs, or both. Both
              // union (see surveyTargetsLearner): the AI Fundamentals
              // pre-survey belongs to Beyond Code Centers AND to Catalyst
              // Labs, so it must list under every course on either side.
              if (s.appliesToTracks?.length || s.appliesToPrograms?.length) {
                return (
                  (s.appliesToTracks ?? []).some(
                    (t) => t === activeTrack.slug || t === home,
                  ) || (s.appliesToPrograms ?? []).includes(programSlug)
                );
              }
              return (
                trackAnsweredSurveyIds === null ||
                trackAnsweredSurveyIds.includes(s.id)
              );
            })}
            trackPublicSurveys={trackPublicSurveys}
            enrolledCount={trackEnrolledCount}
            pulse={activeTrack.exitSurveyEnabled ? { latest: trackPulseLatest ?? null } : undefined}
            staffCohort={!!activeTrack.staffCohort}
            respondentsBySurvey={trackSurveyRespondents}
            exams={trackExams}
          />
        </div>
      )}
    </div>
    );

}

"use client";

import { useState, useCallback, useEffect, useMemo } from "react";
import { useRouter } from "next/navigation";
import { MODULE_1_ITEMS, MODULE_2_SCENARIOS, MODULE_3_ITEMS, TRANSITION_MESSAGES } from "@/lib/assessment/content";
import { saveAssessmentProgress, submitAssessment } from "./actions";
import { AssessmentA11yBar, SpeakButton, useReadAloud } from "@/components/assessment-a11y-bar";
import type { RawResponses } from "@/lib/assessment/types";

type WizardStage = "m1a" | "m1b" | "m2" | "m3" | "transitioning" | "submitting";

// Fisher-Yates shuffle — returns a new array, does not mutate the source.
function shuffle<T>(arr: readonly T[]): T[] {
  const out = [...arr];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

const TOTAL_QUESTIONS =
  MODULE_1_ITEMS.length + MODULE_2_SCENARIOS.length + MODULE_3_ITEMS.length;

const SECTION_META = {
  m1: {
    eyebrow: "Module 1 of 3",
    title: "How you tend to show up",
    description:
      "These questions help us understand your natural strengths — how you show up across different situations. Answer honestly; there are no right or wrong answers.",
  },
  m2: {
    eyebrow: "Module 2 of 3",
    title: "How you tend to work",
    description:
      "For each situation, pick the response that fits you best. Both options are valid — there's no right or wrong answer.",
  },
  m3: {
    eyebrow: "Module 3 of 3",
    title: "What drives you",
    description:
      "These questions are about what keeps you motivated and the kind of path that fits you right now.",
  },
} as const;

export function AssessmentWizard({
  initialModule,
  initialResponses,
  programSlug,
}: {
  initialModule: number;
  initialResponses: RawResponses;
  programSlug: string;
}) {
  const router = useRouter();
  const { enabled: readAloud, setEnabled: setReadAloud, speak, stop } = useReadAloud();
  const [responses, setResponses] = useState<RawResponses>(initialResponses);
  const [stage, setStage] = useState<WizardStage>(() => {
    if (initialModule === 0) return "m1a";  // no progress
    if (initialModule === 1) return "m1b";  // M1A done
    if (initialModule === 2) return "m2";   // M1B done
    if (initialModule === 3) return "m3";   // M2 done
    return "m1a";  // fallback
  });
  const [transitionMsg, setTransitionMsg] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const setResponse = useCallback((id: string, value: number | string) => {
    setResponses(prev => ({ ...prev, [id]: value }));
  }, []);

  // Shuffle each section's questions once, stable for the lifetime of the
  // wizard. Scoring keys off question IDs, so display order has no effect on
  // results — this just keeps learners from pattern-matching the source order.
  // On resume the page reshuffles from scratch, so already-answered items go
  // first: the saved first half stays in the first section and the second
  // half never repeats a question the learner already answered.
  const m1Items = useMemo(() => {
    const answered = MODULE_1_ITEMS.filter(i => initialResponses[i.id] != null);
    const unanswered = MODULE_1_ITEMS.filter(i => initialResponses[i.id] == null);
    return [...shuffle(answered), ...shuffle(unanswered)];
  }, [initialResponses]);
  const m2Items = useMemo(() => shuffle(MODULE_2_SCENARIOS), []);
  const m3Items = useMemo(() => shuffle(MODULE_3_ITEMS), []);

  const m1aItems = m1Items.slice(0, 14);
  const m1bItems = m1Items.slice(14);

  const isStageComplete = () => {
    if (stage === "m1a") return m1aItems.every(i => responses[i.id] != null);
    if (stage === "m1b") return m1bItems.every(i => responses[i.id] != null);
    if (stage === "m2") return m2Items.every(s => responses[s.id] != null);
    if (stage === "m3") return m3Items.every(i => responses[i.id] != null);
    return false;
  };

  // Overall progress — answered out of all scored items across the three modules.
  const answeredCount = useMemo(() => {
    let n = 0;
    for (const i of MODULE_1_ITEMS) if (responses[i.id] != null) n++;
    for (const s of MODULE_2_SCENARIOS) if (responses[s.id] != null) n++;
    for (const i of MODULE_3_ITEMS) if (responses[i.id] != null) n++;
    return n;
  }, [responses]);
  const progressPct = Math.round((answeredCount / TOTAL_QUESTIONS) * 100);

  const section =
    stage === "m1a" || stage === "m1b" ? SECTION_META.m1
    : stage === "m2" ? SECTION_META.m2
    : SECTION_META.m3;

  // Auto-read section intro when read-aloud is on and stage changes.
  useEffect(() => {
    if (!readAloud || stage === "transitioning" || stage === "submitting") return;
    speak(`${section.title}. ${section.description}`);
  }, [stage, readAloud]); // eslint-disable-line react-hooks/exhaustive-deps

  // Question-number offset so numbering is continuous across Module 1's two halves.
  const numberOffset = stage === "m1b" ? m1aItems.length : 0;

  const advance = async () => {
    if (stage === "m1a") {
      await saveAssessmentProgress(responses, 1);
      setTransitionMsg(TRANSITION_MESSAGES.afterM1A);
      setStage("transitioning");
      setTimeout(() => setStage("m1b"), 1800);
    } else if (stage === "m1b") {
      await saveAssessmentProgress(responses, 2);
      setTransitionMsg(TRANSITION_MESSAGES.afterM1B);
      setStage("transitioning");
      setTimeout(() => setStage("m2"), 1800);
    } else if (stage === "m2") {
      await saveAssessmentProgress(responses, 3);
      setTransitionMsg(TRANSITION_MESSAGES.afterM2);
      setStage("transitioning");
      setTimeout(() => setStage("m3"), 1800);
    } else if (stage === "m3") {
      setTransitionMsg(TRANSITION_MESSAGES.afterM3);
      setStage("transitioning");
      setIsSubmitting(true);
      try {
        await submitAssessment(responses, programSlug);
        router.push("/dashboard/assessment/results");
      } catch (e) {
        setError("Something went wrong saving your results. Please try again.");
        setIsSubmitting(false);
        setStage("m3");
      }
    }
  };

  if (stage === "transitioning") {
    return (
      <div className="flex min-h-screen items-center justify-center px-6">
        <div className="text-center space-y-4 max-w-md">
          <p className="text-ink/60 text-sm font-medium">{transitionMsg}</p>
          {isSubmitting && (
            <div className="flex justify-center">
              <div className="h-5 w-5 animate-spin rounded-full border-2 border-accent border-t-transparent" />
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-2xl px-5 py-10 space-y-8">
      <AssessmentA11yBar enabled={readAloud} onToggle={() => { setReadAloud(!readAloud); if (readAloud) stop(); }} />
      {/* Title + overall progress */}
      <div className="space-y-3">
        <div className="flex items-baseline justify-between">
          <p className="text-xs font-semibold uppercase tracking-widest text-accent">
            Pathway Profile
          </p>
          <p className="text-xs font-medium text-ink/40">
            {answeredCount} of {TOTAL_QUESTIONS} · {progressPct}%
          </p>
        </div>
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-ink/10">
          <div
            className="h-full rounded-full bg-accent transition-all duration-300"
            style={{ width: `${progressPct}%` }}
          />
        </div>
      </div>

      {/* Section header */}
      <div className="space-y-1.5">
        <p className="text-xs font-semibold uppercase tracking-widest text-ink/40">
          {section.eyebrow}
        </p>
        <h1 className="text-xl font-semibold text-ink">{section.title}</h1>
        <p className="text-sm text-ink/60 leading-relaxed">{section.description}</p>
      </div>

      {/* Questions */}
      <div className="space-y-8">
        {(stage === "m1a") && m1aItems.map((item, idx) => (
          <LikertRow
            key={item.id}
            number={idx + 1}
            text={item.text}
            value={responses[item.id] as number | undefined}
            onChange={(v) => setResponse(item.id, v)}
          />
        ))}

        {(stage === "m1b") && m1bItems.map((item, idx) => (
          <LikertRow
            key={item.id}
            number={numberOffset + idx + 1}
            text={item.text}
            value={responses[item.id] as number | undefined}
            onChange={(v) => setResponse(item.id, v)}
          />
        ))}

        {stage === "m2" && m2Items.map((scenario, idx) => (
          <ForcedChoiceRow
            key={scenario.id}
            number={idx + 1}
            scenario={scenario}
            value={responses[scenario.id] as string | undefined}
            onChange={(v) => setResponse(scenario.id, v)}
          />
        ))}

        {stage === "m3" && m3Items.map((item, idx) => (
          <LikertRow
            key={item.id}
            number={idx + 1}
            text={item.text}
            value={responses[item.id] as number | undefined}
            onChange={(v) => setResponse(item.id, v)}
          />
        ))}
      </div>

      {/* Error */}
      {error && <p className="text-sm text-red-600">{error}</p>}

      {/* Next button */}
      <button
        onClick={advance}
        disabled={!isStageComplete()}
        className="w-full rounded-lg bg-accent text-white font-semibold py-3.5 text-sm transition-opacity disabled:opacity-40"
      >
        {stage === "m3" ? "See my results" : "Continue"}
      </button>
    </div>
  );
}

// ─── Likert row ───────────────────────────────────────────────────────────────

const LIKERT_OPTIONS = [
  { value: 1, label: "Strongly disagree" },
  { value: 2, label: "Disagree" },
  { value: 3, label: "Not sure" },
  { value: 4, label: "Agree" },
  { value: 5, label: "Strongly agree" },
];

function LikertRow({
  number, text, value, onChange,
}: {
  number: number;
  text: string;
  value: number | undefined;
  onChange: (v: number) => void;
}) {
  return (
    <div className="space-y-3">
      <div className="flex items-start gap-2">
        <p className="text-sm text-ink leading-snug flex-1">
          <span className="font-semibold text-ink/40 mr-1.5">{number}.</span>
          {text}
        </p>
        <SpeakButton text={`Question ${number}. ${text}`} />
      </div>
      <div className="flex gap-2">
        {LIKERT_OPTIONS.map((opt) => (
          <button
            key={opt.value}
            type="button"
            title={opt.label}
            onClick={() => onChange(opt.value)}
            className={`
              flex-1 rounded-lg border-2 py-2.5 text-xs font-medium transition-all
              ${value === opt.value
                ? "border-accent bg-accent/10 text-accent"
                : "border-ink/10 text-ink/50 hover:border-ink/30"
              }
            `}
          >
            {opt.value}
          </button>
        ))}
      </div>
      <div className="flex justify-between text-[10px] text-ink/40 px-0.5">
        <span>Strongly disagree</span>
        <span>Strongly agree</span>
      </div>
    </div>
  );
}

// ─── Forced choice row ────────────────────────────────────────────────────────

function ForcedChoiceRow({
  number, scenario, value, onChange,
}: {
  number: number;
  scenario: typeof MODULE_2_SCENARIOS[number];
  value: string | undefined;
  onChange: (v: string) => void;
}) {
  return (
    <div className="space-y-3">
      <div className="flex items-start gap-2">
        <p className="text-sm font-medium text-ink leading-snug flex-1">
          <span className="font-semibold text-ink/40 mr-1.5">{number}.</span>
          {scenario.scenario}
        </p>
        <SpeakButton text={`Question ${number}. ${scenario.scenario}. Option A: ${scenario.optionA.label}. Option B: ${scenario.optionB.label}.`} />
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {(["A", "B"] as const).map((letter) => {
          const opt = letter === "A" ? scenario.optionA : scenario.optionB;
          return (
            <button
              key={letter}
              type="button"
              onClick={() => onChange(letter)}
              className={`
                text-left rounded-lg border-2 px-4 py-4 text-sm leading-snug transition-all
                ${value === letter
                  ? "border-accent bg-accent/10 text-ink font-medium"
                  : "border-ink/10 bg-white hover:border-ink/30 text-ink/70"
                }
              `}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { ScoredOutput } from "@/lib/assessment/types";
import {
  ARCHETYPE_CONTENT,
  WORK_STYLE_CONTENT,
  PATHWAY_CONTENT,
  SPECIAL_CASE_LANGUAGE,
  SUSTAINABILITY_NOTE,
  MODULE_2_FRAMING,
  MODULE_3_FRAMING,
} from "@/lib/assessment/content";

export function ResultsProfile({ result }: { result: ScoredOutput }) {
  const [openSection, setOpenSection] = useState<string | null>("strengths");

  const archetypeContent = ARCHETYPE_CONTENT[result.archetype_primary];
  const secondaryContent = result.archetype_secondary
    ? ARCHETYPE_CONTENT[result.archetype_secondary]
    : null;

  const showArchetypeNarrative =
    result.archetype_confidence !== "low" &&
    result.archetype_confidence !== "flat" &&
    result.archetype_confidence !== "emerging" &&
    result.archetype_confidence !== "broad_high";

  const archetypeSummaryText = (() => {
    if (result.archetype_confidence === "low") return SPECIAL_CASE_LANGUAGE.low_confidence;
    if (result.archetype_confidence === "broad_high") return SPECIAL_CASE_LANGUAGE.broad_high;
    if (result.archetype_confidence === "flat" || result.archetype_confidence === "emerging") return SPECIAL_CASE_LANGUAGE.flat;
    if (result.archetype_top_three) {
      const names = result.archetype_top_three.map((k) => ARCHETYPE_CONTENT[k].name);
      return `Your profile shows three strong patterns: ${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}.`;
    }
    if (result.archetype_is_blended && secondaryContent) {
      return `Your profile shows a blended pattern: ${archetypeContent.name} and ${secondaryContent.name}.`;
    }
    return archetypeContent.definition;
  })();

  return (
    <div className="mx-auto max-w-2xl px-5 py-12 space-y-10">
      {/* Header */}
      <div className="space-y-3">
        <p className="text-xs font-semibold uppercase tracking-widest text-accent">
          Your Pathway Profile
        </p>
        <h1 className="text-4xl font-black text-ink leading-tight">
          {showArchetypeNarrative ? (
            <>{archetypeContent.emoji} {archetypeContent.name}</>
          ) : "Your Profile"}
        </h1>
        <p className="text-ink/70 leading-relaxed">{archetypeSummaryText}</p>
      </div>

      {showArchetypeNarrative ? (
        <>
          {/* Your strengths */}
          <Section
            id="strengths"
            title="✨ Your strengths"
            isOpen={openSection === "strengths"}
            onToggle={() => setOpenSection(openSection === "strengths" ? null : "strengths")}
          >
            <div className="space-y-4">
              <p className="text-ink/80 leading-relaxed">{archetypeContent.strengths}</p>
              {result.archetype_is_blended && secondaryContent && (
                <>
                  <hr className="border-ink/10" />
                  <p className="text-xs font-semibold uppercase tracking-widest text-ink/40">
                    Also strong: {secondaryContent.name}
                  </p>
                  <p className="text-ink/80 leading-relaxed">{secondaryContent.strengths}</p>
                  <p className="text-sm text-ink/60 italic leading-relaxed">
                    {SPECIAL_CASE_LANGUAGE.blended}
                  </p>
                </>
              )}
            </div>
          </Section>

          {/* Where this can take you — Module 1 career pathways. A blended result
              gets the pathway copy for both archetypes. */}
          {[archetypeContent, ...(result.archetype_is_blended && secondaryContent ? [secondaryContent] : [])]
            .filter((c) => c.pathways)
            .map((content, idx) => (
              <Section
                key={content.name}
                id={idx === 0 ? "pathways" : "pathways-secondary"}
                title={idx === 0 ? "🚀 Where this can take you" : `🚀 Where ${content.name} can take you`}
                isOpen={openSection === (idx === 0 ? "pathways" : "pathways-secondary")}
                onToggle={() => {
                  const id = idx === 0 ? "pathways" : "pathways-secondary";
                  setOpenSection(openSection === id ? null : id);
                }}
              >
                <div className="space-y-5">
                  {content.pathwaysIntro && (
                    <p className="text-sm text-ink/75 leading-relaxed">{content.pathwaysIntro}</p>
                  )}
                  {[
                    { label: "Entry points", text: content.pathways!.entry },
                    { label: "Mid-career", text: content.pathways!.mid },
                    { label: "Established roles", text: content.pathways!.established },
                  ].map(({ label, text }) => (
                    <div key={label} className="space-y-1">
                      <p className="text-xs font-semibold uppercase tracking-widest text-accent">{label}</p>
                      <p className="text-sm text-ink/75 leading-relaxed">{text}</p>
                    </div>
                  ))}
                  {content.verticals && (
                    <div className="space-y-1">
                      <p className="text-xs font-semibold uppercase tracking-widest text-accent">
                        Catalyst verticals to explore first
                      </p>
                      <p className="text-sm text-ink/75 leading-relaxed">{content.verticals.join(", ")}</p>
                    </div>
                  )}
                  {content.future && (
                    <div className="rounded-lg bg-ink/5 px-4 py-4">
                      <p className="text-xs font-semibold uppercase tracking-widest text-ink/40 mb-1">Looking ahead</p>
                      <p className="text-sm text-ink/70 leading-relaxed">{content.future}</p>
                    </div>
                  )}
                  <p className="text-[11px] text-ink/40 italic leading-relaxed">
                    Stages describe how the work grows, not your age — you can enter at any point.
                  </p>
                </div>
              </Section>
            ))}

          {archetypeContent.honest && (
            <Section
              id="honest"
              title="💬 The honest part"
              isOpen={openSection === "honest"}
              onToggle={() => setOpenSection(openSection === "honest" ? null : "honest")}
            >
              <p className="text-ink/80 leading-relaxed">{archetypeContent.honest}</p>
            </Section>
          )}
        </>
      ) : (
        /* No single clear lean — show the opportunity-framed block only. */
        <Section
          id="strengths"
          title="✨ Your strengths"
          isOpen={openSection === "strengths"}
          onToggle={() => setOpenSection(openSection === "strengths" ? null : "strengths")}
        >
          <p className="text-ink/70 leading-relaxed">{archetypeSummaryText}</p>
        </Section>
      )}

      {/* Section 2 — How you tend to work */}
      <Section
        id="workstyle"
        title="🔧 How you tend to work"
        isOpen={openSection === "workstyle"}
        onToggle={() => setOpenSection(openSection === "workstyle" ? null : "workstyle")}
      >
        <div className="space-y-6">
          <p className="text-xs text-ink/50 italic">{MODULE_2_FRAMING}</p>
          {[
            { label: "Energy", pole: result.social_energy, signal: result.social_energy_signal },
            { label: "Structure", pole: result.structure_preference, signal: result.structure_preference_signal },
            { label: "Contribution", pole: result.contribution_mode, signal: result.contribution_mode_signal },
            { label: "Pace", pole: result.pace, signal: result.pace_signal },
          ].map(({ label, pole, signal }) => {
            const content = WORK_STYLE_CONTENT[pole];
            const poleName = pole.replace(/_/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase());
            return (
              <div key={label} className="space-y-1">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-semibold uppercase tracking-widest text-ink/40">{label}</span>
                  <span className="text-xs text-accent font-medium">{poleName}</span>
                  {signal === "lighter" && (
                    <span className="text-[10px] text-ink/30 italic">lighter lean</span>
                  )}
                </div>
                <p className="text-sm text-ink/75 leading-relaxed">{content.learner}</p>
              </div>
            );
          })}
        </div>
      </Section>

      {/* Section 3 — What drives you */}
      <Section
        id="pathway"
        title="🎯 What drives you"
        isOpen={openSection === "pathway"}
        onToggle={() => setOpenSection(openSection === "pathway" ? null : "pathway")}
      >
        <div className="space-y-4">
          <p className="text-xs text-ink/50 italic">{MODULE_3_FRAMING}</p>
          <p className="text-ink/80 leading-relaxed">
            {PATHWAY_CONTENT[result.pathway_orientation].learner}
          </p>
          {result.sustainability_note && (
            <div className="rounded-lg bg-ink/5 px-4 py-4">
              <p className="text-sm text-ink/70 leading-relaxed">{SUSTAINABILITY_NOTE}</p>
            </div>
          )}
        </div>
      </Section>

      {/* Closing */}
      <p className="text-xs text-ink/40 italic text-center pt-4">
        {SPECIAL_CASE_LANGUAGE.closing}
      </p>
    </div>
  );
}

function Section({
  id, title, isOpen, onToggle, children,
}: {
  id: string;
  title: string;
  isOpen: boolean;
  onToggle: () => void;
  children: React.ReactNode;
}) {
  return (
    <div className="rounded-lg border border-ink/10 overflow-hidden">
      <button
        type="button"
        onClick={onToggle}
        className="w-full flex items-center justify-between px-5 py-4 text-left hover:bg-ink/[0.02] transition-colors"
      >
        <span className="font-semibold text-ink">{title}</span>
        <span className="text-ink/30 text-sm">{isOpen ? "↑" : "↓"}</span>
      </button>
      {isOpen && (
        <div className="px-5 pb-6 pt-2 border-t border-ink/10">
          {children}
        </div>
      )}
    </div>
  );
}

