"use client";

import { useRef, useEffect, useState } from "react";

interface VideoBackgroundProps {
  src: string;
  poster?: string;
  className?: string;
  overlay?: string;
  /** Pause video when not in viewport for performance */
  lazy?: boolean;
}

export default function VideoBackground({
  src,
  poster,
  className = "",
  overlay,
  lazy = true,
}: VideoBackgroundProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(!lazy);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  // Check reduced motion preference
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setPrefersReducedMotion(mq.matches);
    const handler = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  // Lazy loading via IntersectionObserver
  useEffect(() => {
    if (!lazy || !containerRef.current) return;

    const observer = new IntersectionObserver(
      ([entry]) => setIsVisible(entry.isIntersecting),
      { rootMargin: "200px" }
    );
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [lazy]);

  // Play/pause based on visibility
  useEffect(() => {
    if (!videoRef.current || prefersReducedMotion) return;
    if (isVisible) {
      videoRef.current.play().catch(() => {});
    } else {
      videoRef.current.pause();
    }
  }, [isVisible, prefersReducedMotion]);

  return (
    <div ref={containerRef} className={`absolute inset-0 overflow-hidden ${className}`}>
      {!prefersReducedMotion && isVisible && (
        <video
          ref={videoRef}
          autoPlay
          muted
          loop
          playsInline
          poster={poster}
          className="absolute inset-0 w-full h-full object-cover"
        >
          <source src={src} type="video/mp4" />
        </video>
      )}
      {/* Fallback for reduced motion — show poster as bg */}
      {prefersReducedMotion && poster && (
        <div
          className="absolute inset-0 bg-cover bg-center"
          style={{ backgroundImage: `url(${poster})` }}
        />
      )}
      {overlay && <div className={`absolute inset-0 ${overlay}`} />}
    </div>
  );
}

"use client";

import { useState, useEffect, Suspense } from "react";
import dynamic from "next/dynamic";
import Link from "next/link";
import { LinkPending } from "@/components/link-pending";
import { usePathname, useSearchParams } from "next/navigation";
import {
  House,
  ChatsCircle,
  ChartBar,
  Question,
  List,
  X,
  Check,
  Confetti,
  BookOpen,
  SpeakerHigh,
  SpeakerSlash,
} from "@phosphor-icons/react";
import { computeCurrentWeek, trackHasStarted } from "@/lib/utils";
import { unitDisplayMap } from "@/lib/programs/unit-display";
import { primaryTrack } from "@/lib/enrollment";
import { TextScaleToggle } from "@/components/text-scale-toggle";
import { PushToggle } from "@/components/push-toggle";
import { useReadAloud } from "@/components/assessment-a11y-bar";
import { SidebarToggle } from "@/components/sidebar-toggle";
import { setPreviewTrackSlug } from "@/app/dashboard/preview-actions";

const UserMenu = dynamic(
  () => import("@/components/user-menu").then((m) => m.UserMenu),
  {
    loading: () => (
      <div className="h-8 w-8 shrink-0 animate-pulse rounded-full bg-paper-tint" />
    ),
  },
);

const AdminProgramSwitcher = dynamic(
  () =>
    import("@/components/admin-program-switcher").then(
      (m) => m.AdminProgramSwitcher,
    ),
  {
    loading: () => (
      <div className="mx-3 h-12 animate-pulse rounded bg-paper-tint" />
    ),
  },
);

// Leaving preview is a server action (it clears an httpOnly cookie), so the
// one nav item that has to do it is a form button rather than a Link.
type NavItem = {
  href: string;
  label: string;
  icon: React.ComponentType<{ size?: number; weight?: "bold"; "aria-hidden"?: boolean }>;
};

type ProgramOption = {
  slug: string;
  name: string;
  domain: string;
  dnsReady?: boolean;
};

type CurriculumTrack = {
  slug: string;
  shortName: string;
  startDate: string;
  startDateTbd?: boolean;
  selfPaced?: boolean;
  totalWeeks: number;
  lastSessionDayOffset: number;
  unitLabel?: string;
  /** Set when this track wraps around another (MASS → Security+). */
  companionOf?: string;
  weekSummaries: { week: number; topic: string; icon: string; label?: string; title?: string }[];
  /** Sessions that actually ran — from check-ins or an existing recording, not
   *  from calendar arithmetic. */
  heldWeeks?: number[];
  /** Sessions THIS learner has finished. What a tick means. */
  completedWeeks?: number[];
};

type NavVariant = "admin-sidebar" | "student-sidebar" | "lunch-learn-sidebar" | "topbar";

type LunchLearnRecording = {
  id: string;
  title: string;
  recorded_at: string;
};

export function Nav({
  isAdmin,
  canAccessStaff = false,
  logo,
  programName,
  showTutor = true,
  showResources = false,
  minimal = false,
  firstName,
  lastName,
  email,
  avatarUrl,
  canSwitch,
  programs,
  currentProgramSlug,
  variant = "admin-sidebar",
  curriculumTracks = [],
  adminTracks = [],
  lunchLearnRecordings = [],
  showLunchLearnLink = false,
  previewingSlug = null,
}: {
  isAdmin: boolean;
  canAccessStaff?: boolean;
  logo: string;
  programName: string;
  showTutor?: boolean;
  showResources?: boolean;
  minimal?: boolean;
  firstName: string;
  lastName: string;
  email: string | null;
  avatarUrl: string | null;
  canSwitch: boolean;
  programs: ProgramOption[];
  currentProgramSlug: string;
  variant?: NavVariant;
  curriculumTracks?: CurriculumTrack[];
  adminTracks?: { slug: string; shortName: string }[];
  lunchLearnRecordings?: LunchLearnRecording[];
  showLunchLearnLink?: boolean;
  /** Track being previewed-as-student — Home follows it. Null = not previewing. */
  previewingSlug?: string | null;
}) {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const activeTab = searchParams.get("tab") ?? "program";
  const [mobileOpen, setMobileOpen] = useState(false);
  // Light shell (Meridian-style) across the whole platform — learner, admin,
  // and lunch-learn now share the white/SF/skin look.
  const lightShell = true;

  useEffect(() => {
    if (!mobileOpen) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMobileOpen(false);
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [mobileOpen]);

  // For admins, Home IS the admin dashboard (the learner home is preview-only).
  // The bare /dashboard would render the learner shell and only THEN redirect
  // admins to /dashboard/admin — flashing the learner skeleton first. Point
  // every brand/home link straight at the right destination to avoid that.
  //
  // Same reasoning for students: their course IS their home. /dashboard was a
  // greeting, a picker duplicating this very sidebar, and two tiles duplicating
  // these very nav items — 118 of 122 learners have exactly one real course, and
  // the four with two reach the second from the list below. Point Home at the
  // course; the second course is one click away, and nobody lands on a chooser.
  // (Security+ enrolls you in its MASS wraparound too, so "how many courses"
  // isn't a count — `primaryTrack` prefers a standalone course over a companion.)
  // While previewing-as-student, curriculumTracks is the WHOLE catalog (so the
  // sidebar works on any course page) — primaryTrack over that list would send
  // Home to whichever course starts earliest, not the one being previewed.
  // That teleported an admin to Network+ out of a MASS preview (2026-07-10).
  //
  // Multi-course students are the exception: their hub is the card home at
  // /dashboard (which now leads with the cross-course "Happening next"
  // panel). Pointing Home at the primary course stranded them — Home from
  // the Security+ page just reloaded the Security+ page. Companions collapse
  // only when their parent course is also enrolled (same rule as the
  // /dashboard redirect): Security+ + MASS is still ONE course, and those
  // students keep Home on the course.
  const enrolledSlugSet = new Set(curriculumTracks.map((t) => t.slug));
  const collapsedCourseCount = new Set(
    curriculumTracks.map((t) =>
      t.companionOf && enrolledSlugSet.has(t.companionOf) ? t.companionOf : t.slug,
    ),
  ).size;
  const primarySlug =
    variant === "student-sidebar"
      ? (previewingSlug ??
        (collapsedCourseCount > 1 ? null : (primaryTrack(curriculumTracks)?.slug ?? null)))
      : null;
  const homeHref = isAdmin
    ? "/dashboard/admin"
    : primarySlug
      ? `/dashboard/track/${primarySlug}`
      : "/dashboard";

  // While previewing, Home follows the previewed course — useful from a week
  // or session page, and a dead link on the course page itself, which is
  // exactly where a previewing admin spends their time. Clicking Home there
  // did nothing at all, which reads as a broken button (reported 2026-09-08).
  // /dashboard/admin isn't a destination either: the admin subtree redirects
  // preview mode straight back out. So on that one page Home leaves preview,
  // which is what "take me home" means for staff.
  const homeExitsPreview = !!previewingSlug && homeHref === pathname;

  const items: NavItem[] = [
    // For admins, Home IS the admin dashboard (the learner home is preview-only),
    // so there's no separate "Admin" item — one clear landing.
    { href: homeHref, label: "Home", icon: House },
    // No separate "Courses" item: for admins, Home IS the course hub — it lists
    // every track with Manage + Open-student-view actions per course, so a
    // second admin-only catalog page was redundant (collapsed into Home).
    // Workshops are BGC-internal staff content — only shown to staff while in
    // the BGC program (the page itself 404s outside BGC to close the URL hole).
    // Students never see this; it's not enrolled-learner content.
    ...(canAccessStaff && currentProgramSlug === "bgc"
      ? [{ href: "/dashboard/workshops", label: "Workshops", icon: Confetti }]
      : []),
    ...(showTutor
      ? [{ href: "/dashboard/tutor", label: "AI Tutor", icon: ChatsCircle }]
      : []),
    // Resources is independent of the AI Tutor — shown whenever the current
    // program has any resources (admins manage them at /dashboard/admin/resources).
    ...(showResources
      ? [{ href: "/dashboard/resources", label: "Resources", icon: BookOpen }]
      : []),
    ...(canSwitch
      ? [{ href: "/dashboard/insights", label: "Overview", icon: ChartBar }]
      : []),
  ];

  // Survey-specific responses live at /dashboard/admin?tab=insights and are
  // reachable from the Insights page header, so they're no longer a sidebar
  // item of their own. Admin still needs to NOT highlight when ?tab=insights
  // is the active tab (it would feel wrong for both to highlight).
  const isItemActive = (href: string) => {
    if (href === "/dashboard") return pathname === "/dashboard";
    if (href === "/dashboard/admin") {
      return pathname.startsWith("/dashboard/admin") && activeTab !== "insights";
    }
    return pathname.startsWith(href);
  };

  const navItemClass = (active: boolean) =>
    `nav-item flex min-h-[44px] w-full items-center gap-3 py-2 text-sm font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-inset rounded-lg border-l-2 pl-[10px] pr-3 ${
      lightShell
        ? active
          ? "border-primary bg-primary/[0.08] text-primary"
          : "border-transparent text-ink-soft hover:bg-paper-tint hover:text-ink"
        : active
          ? "border-primary bg-white/[0.08] text-white"
          : "border-transparent text-ink-soft hover:bg-white/[0.06] hover:text-white"
    }`;

  const renderItem = ({ href, label, icon: Icon }: NavItem) => {
    const active = isItemActive(href);
    if (href === homeHref && homeExitsPreview) {
      return (
        <form key={href} action={setPreviewTrackSlug.bind(null, null)}>
          <button
            type="submit"
            aria-label={`${label} — leave preview`}
            onClick={() => setMobileOpen(false)}
            className={navItemClass(false)}
          >
            <Icon size={20} weight="bold" aria-hidden />
            <span className="nav-collapsible flex-1 text-left">{label}</span>
          </button>
        </form>
      );
    }
    return (
      <Link
        key={href}
        href={href}
        aria-label={label}
        aria-current={active ? "page" : undefined}
