"use client";

import { useEffect, useState } from "react";
import {
  TEXT_SCALE_COOKIE,
  TEXT_SCALES,
  DEFAULT_TEXT_SCALE,
  parseTextScale,
  rootFontSizeFor,
  type TextScale,
} from "@/lib/accessibility/scale";

// Three-button A A A toggle. Each button's own label is rendered at its
// scale so the control demonstrates what the scale does at a glance.
//
// Used both in the dashboard nav (compact=true) and at the top of public
// pages (compact=false).

export function TextScaleToggle({
  compact = false,
  tone = "light",
}: {
  compact?: boolean;
  tone?: "light" | "dark";
}) {
  const [scale, setScale] = useState<TextScale>(DEFAULT_TEXT_SCALE);

  useEffect(() => {
    const match = document.cookie.match(
      new RegExp(`(?:^|; )${TEXT_SCALE_COOKIE}=(\\d+)`),
    );
    setScale(parseTextScale(match?.[1]));
  }, []);

  function apply(next: TextScale) {
    setScale(next);
    document.cookie =
      `${TEXT_SCALE_COOKIE}=${next}; path=/; max-age=${60 * 60 * 24 * 365}; samesite=lax`;
    document.documentElement.style.fontSize = rootFontSizeFor(next);
  }

  const baseBtn =
    tone === "dark"
      ? "text-ink-faint hover:bg-white/10 hover:text-white"
      : "text-ink-soft hover:bg-paper-tint hover:text-ink";
  const activeBtn =
    tone === "dark"
      ? "bg-white/15 text-white"
      : "bg-ink text-white";

  return (
    <div
      role="group"
      aria-label="Text size"
      className={`inline-flex items-center ${
        compact ? "gap-0.5" : "gap-1"
      } ${
        tone === "dark" ? "bg-transparent" : "bg-neutral-50"
      } p-0.5`}
    >
      {!compact && (
        <span
          className={`px-1.5 text-xs font-medium ${
            tone === "dark" ? "text-ink-faint" : "text-ink-soft"
          }`}
        >
          Text size
        </span>
      )}
      {TEXT_SCALES.map((s, i) => {
        const isActive = scale === s;
        const labelSize = i === 0 ? "0.75rem" : i === 1 ? "0.95rem" : "1.15rem";
        return (
          <button
            key={s}
            type="button"
            onClick={() => apply(s)}
            aria-label={`Text size ${s} percent`}
            aria-pressed={isActive}
            className={`min-h-[32px] min-w-[32px] rounded-md px-2 font-semibold leading-none transition-colors ${
              isActive ? activeBtn : baseBtn
            }`}
            style={{ fontSize: labelSize }}
          >
            A
          </button>
        );
      })}
    </div>
  );
}

import { describe, it, expect } from "vitest";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { Field } from "@/components/ui";

const html = (el: React.ReactElement) => renderToStaticMarkup(el);
const field = (label: string, child: React.ReactElement) => createElement(Field, { label, children: child });
const attr = (markup: string, tag: string, name: string) =>
  new RegExp(`<${tag}[^>]*\\s${name}="([^"]*)"`).exec(markup)?.[1];

describe("Field", () => {
  it("ties the label to its input", () => {
    const m = html(field("First name", createElement("input", { type: "text" })));
    const id = attr(m, "input", "id");
    expect(id).toBeTruthy();
    expect(attr(m, "label", "for")).toBe(id);
  });

  it("works for selects and textareas too", () => {
    for (const tag of ["select", "textarea"]) {
      const m = html(field("X", createElement(tag)));
      expect(attr(m, "label", "for")).toBe(attr(m, tag, "id"));
    }
  });

  it("keeps an id the control already has", () => {
    const m = html(field("Email", createElement("input", { id: "email-field" })));
    expect(attr(m, "input", "id")).toBe("email-field");
    expect(attr(m, "label", "for")).toBe("email-field");
  });

  it("gives two fields different ids", () => {
    const m = html(
      createElement("div", null,
        field("A", createElement("input")),
        field("B", createElement("input"))),
    );
    const ids = [...m.matchAll(/<input[^>]*\sid="([^"]*)"/g)].map((x) => x[1]);
    expect(new Set(ids).size).toBe(2);
  });
});

"use client";

import { useEffect, useRef, useState } from "react";
import { CaretUpDown, SignOut, Check, GearSix } from "@phosphor-icons/react";
import { createClient } from "@/lib/supabase/client";

type ProgramOption = {
  slug: string;
  name: string;
  domain: string;
  /** If false, switching uses the cookie-based override instead of redirecting to `domain`. */
  dnsReady?: boolean;
};

type Variant = "sidebar" | "topbar";

export function UserMenu({
  firstName,
  lastName,
  email,
  avatarUrl,
  canSwitch,
  programs,
  currentProgramSlug,
  variant = "sidebar",
  align = "right",
}: {
  firstName: string;
  lastName: string;
  email: string | null;
  avatarUrl: string | null;
  canSwitch: boolean;
  programs: ProgramOption[];
  currentProgramSlug: string;
  variant?: Variant;
  /** Topbar popover edge. "left" when the trigger sits near the screen's left
   *  edge (the minimal checklist shell), or the menu opens off-screen. */
  align?: "left" | "right";
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const initials =
    `${firstName?.[0] ?? ""}${lastName?.[0] ?? ""}`.toUpperCase() || "·";

  /* eslint-disable react-hooks/immutability -- intentional browser-global writes for navigation */
  const handleSwitchProgram = (slug: string) => {
    if (slug === currentProgramSlug) return;
    if (slug === "__bcc_surveys__") {
      window.location.href = "/dashboard/admin/surveys";
      return;
    }
    document.cookie = `program-override=${slug}; path=/; max-age=86400`;
    // Full navigation (not router.push) — the program context is resolved
    // server-side from the program-override cookie, and a client-side push
    // serves the cached route without re-reading it, so the switched-to program
    // (and the menu's checkmark) wouldn't update. A real navigation reloads with
    // the new cookie. Straight to /dashboard/admin (super-admins land there).
    window.location.href = "/dashboard/admin";
  };
  /* eslint-enable react-hooks/immutability */

  const handleSignOut = async () => {
    document.cookie = "atg-demo-user=; path=/; max-age=0";
    document.cookie = "program-override=; path=/; max-age=0";
    try {
      if (process.env.NEXT_PUBLIC_SUPABASE_URL) {
        await createClient().auth.signOut();
      }
    } finally {
      // Leave even if the sign-out call fails, so the button never looks dead.
      window.location.href = "/";
    }
  };

  const avatarNode = (size: "sm" | "md" | "lg") => {
    const cls =
      size === "sm"
        ? "h-8 w-8 text-[11px]"
        : size === "md"
          ? "h-9 w-9 text-xs"
          : "h-10 w-10 text-sm";
    return (
      <span
        aria-hidden
        className={`flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-paper-tint font-semibold tracking-tight text-ink-soft ${cls}`}
      >
        {avatarUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={avatarUrl}
            alt=""
            className="h-full w-full object-cover"
          />
        ) : (
          <span>{initials}</span>
        )}
      </span>
    );
  };

  const popoverPosition =
    variant === "sidebar"
      ? "bottom-full mb-2 left-0 origin-bottom-left"
      : align === "left"
        ? "top-full mt-2 left-0 origin-top-left"
        : "top-full mt-2 right-0 origin-top-right";

  const trigger =
    variant === "sidebar" ? (
      <button
        ref={triggerRef}
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={open ? "Close account menu" : "Open account menu"}
        className="flex w-full min-h-[44px] items-center gap-2.5 px-2 py-1.5 text-left transition-colors hover:bg-paper-tint focus:outline-none focus-visible:ring-2 focus-visible:ring-ink/15"
      >
        {avatarNode("md")}
        <span className="min-w-0 flex-1">
          <span className="block truncate text-sm font-medium text-ink">
            {[firstName, lastName].filter(Boolean).join(" ") || "Your account"}
          </span>
          {email && (
            <span className="block truncate text-xs text-ink-faint">
              {email}
            </span>
          )}
        </span>
        <CaretUpDown
          size={14}
          weight="bold"
          aria-hidden
          className="shrink-0 text-ink-faint"
        />
      </button>
    ) : (
      <button
        ref={triggerRef}
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={open ? "Close account menu" : "Open account menu"}
        className="flex min-h-[44px] min-w-[44px] items-center justify-center rounded-full p-1 transition-colors hover:bg-paper-tint focus:outline-none focus-visible:ring-2 focus-visible:ring-ink/15"
      >
        {avatarNode("sm")}
      </button>
    );

  return (
    <div ref={rootRef} className="relative">
      {trigger}

      {open && (
        <div
          role="menu"
          aria-label="Account menu"
          className={`absolute z-40 w-72 border border-rule-soft bg-surface-elevated p-1 shadow-sm ${popoverPosition}`}
        >
          {/* Identity header — topbar only. The sidebar trigger already
             shows avatar + name + email right below the popover, so
             repeating them here read as a duplicate. */}
          {variant === "topbar" && (
          <div className="flex items-center gap-3 px-3 py-3">
            <span
              aria-hidden
              className="flex h-10 w-10 shrink-0 items-center justify-center overflow-hidden rounded-full bg-paper-tint text-sm font-semibold tracking-tight text-ink-soft"
            >
              {avatarUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={avatarUrl}
                  alt=""
                  className="h-full w-full object-cover"
                />
              ) : (
                <span>{initials}</span>
              )}
            </span>
            <div className="min-w-0">
              <p className="truncate text-sm font-semibold text-ink">
                {[firstName, lastName].filter(Boolean).join(" ") || "Your account"}
              </p>
              {email && (
                <p className="truncate text-xs text-ink-faint">{email}</p>
              )}
            </div>
          </div>
          )}

          {/* Program switcher (super-admins) */}
          {canSwitch && programs.length > 1 && (
            <>
              {variant === "topbar" && (
                <div className="my-1 h-px bg-rule-soft" role="separator" />
              )}
              <div className="px-3 pt-2 pb-1">
                <p className="text-[10px] font-medium uppercase tracking-[0.14em] text-ink-faint">
                  Switch program
                </p>
              </div>
              <div className="px-1 pb-1">
                {programs.map((p) => {
                  const isCurrent = p.slug === currentProgramSlug;
                  return (
                    <button
                      key={p.slug}
                      type="button"
                      role="menuitem"
                      onClick={() => handleSwitchProgram(p.slug)}
                      className={`flex w-full items-center gap-2 px-2.5 py-2 text-sm transition-colors ${
                        isCurrent
                          ? "text-ink font-medium"
                          : "text-ink-soft hover:bg-paper-tint-soft hover:text-ink"
                      }`}
                    >
                      <Check
                        size={14}
                        weight="bold"
                        aria-hidden
                        className={`shrink-0 ${isCurrent ? "text-ink" : "text-transparent"}`}
                      />
                      <span className="truncate">{p.name}</span>
                    </button>
                  );
                })}
              </div>
            </>
          )}

          {/* Settings + Sign out */}
          {(variant === "topbar" || (canSwitch && programs.length > 1)) && (
            <div className="my-1 h-px bg-rule-soft" role="separator" />
          )}
          <div className="px-1 pb-1 pt-1">
            <a
              href="/dashboard/settings"
              role="menuitem"
              onClick={() => setOpen(false)}
              className="flex w-full items-center gap-2 px-2.5 py-2 text-sm font-medium text-ink-soft transition-colors hover:bg-paper-tint-soft hover:text-ink"
            >
              <GearSix size={15} weight="bold" aria-hidden />
              <span>Settings</span>
            </a>
            <button
              type="button"
              role="menuitem"
              onClick={handleSignOut}
              className="flex w-full items-center gap-2 px-2.5 py-2 text-sm font-medium text-ink-soft transition-colors hover:bg-paper-tint-soft hover:text-ink"
            >
              <SignOut size={15} weight="bold" aria-hidden />
              <span>Sign out</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

