"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Link from "next/link";
import { ArrowLeft } from "lucide-react";

// Renders the week prev/next links into the breadcrumb row (the #breadcrumb-actions
// slot) so the nav sits on one line with the breadcrumb instead of a separate
// block below. Lives in the page (not the layout) so prev/next stay fresh as the
// learner moves between weeks; the breadcrumb bar only provides the slot.
export function WeekNavPortal({
  trackSlug,
  weekNum,
  totalWeeks,
  unitLabel = "Week",
  prevLabel,
  nextLabel,
}: {
  trackSlug: string;
  weekNum: number;
  totalWeeks: number;
  unitLabel?: string;
  /** Display names for the adjacent units — an extra reads "Kickoff", not a number. */
  prevLabel?: string;
  nextLabel?: string;
}) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  const prevWeek = weekNum > 1 ? weekNum - 1 : null;
  const nextWeek = weekNum < totalWeeks ? weekNum + 1 : null;
  if (!prevWeek && !nextWeek) return null;
  if (!mounted) return null;

  const target = document.getElementById("breadcrumb-actions");
  if (!target) return null;

  const cls =
    "inline-flex items-center gap-1 border border-rule px-3 py-1.5 text-xs font-medium text-ink-soft hover:bg-paper-tint-soft hover:text-ink transition-colors";

  return createPortal(
    <>
      {prevWeek && (
        <Link href={`/dashboard/track/${trackSlug}/${prevWeek}`} className={cls}>
          <ArrowLeft size={12} />
          {prevLabel ?? `${unitLabel} ${prevWeek}`}
        </Link>
      )}
      {nextWeek && (
        <Link href={`/dashboard/track/${trackSlug}/${nextWeek}`} className={cls}>
          {nextLabel ?? `${unitLabel} ${nextWeek}`}
          <ArrowLeft size={12} className="rotate-180" />
        </Link>
      )}
    </>,
    target,
  );
}

import { createServiceClient } from "@/lib/supabase/server";
import { trackHasStarted } from "@/lib/utils";

// Staff who TAKE a course (the Field Ready staff cohort is all staff, many of
// them admins) get the student view of it, pre-survey checklist included:
// until it ends they land on it at login and its pages treat them as learners. Teaching it (an
// instructor_tracks row) keeps the admin view. The admin panel stays one
// click away in the account menu.

type TrackDates = {
  track_slug: string;
  start_date: string | null;
  total_weeks: number | null;
  sequential_gating?: boolean | null;
  self_paced?: boolean | null;
};

/** True until the course is past its last week (upcoming counts). */
export function courseNotOver(t: TrackDates, now: Date = new Date()): boolean {
  if (!t.start_date) return false;
  if (!t.total_weeks) return true;
  const end = new Date(`${t.start_date}T00:00:00Z`);
  end.setUTCDate(end.getUTCDate() + t.total_weeks * 7);
  return now < end;
}

async function learnerCourses(userId: string, only?: string): Promise<TrackDates[]> {
  const svc = createServiceClient();
  let enrQ = svc.from("student_tracks").select("track_slug").eq("student_id", userId);
  let teachQ = svc.from("instructor_tracks").select("track_slug").eq("student_id", userId);
  if (only) {
    enrQ = enrQ.eq("track_slug", only);
    teachQ = teachQ.eq("track_slug", only);
  }
  const [{ data: enr }, { data: teach }] = await Promise.all([enrQ, teachQ]);
  const teaching = new Set(((teach ?? []) as { track_slug: string }[]).map((r) => r.track_slug));
  const slugs = ((enr ?? []) as { track_slug: string }[])
    .map((r) => r.track_slug)
    .filter((s) => !teaching.has(s));
  if (slugs.length === 0) return [];
  if (only) return [{ track_slug: only, start_date: null, total_weeks: null }];
  const { data } = await svc
    .from("track_overrides")
    .select("track_slug, start_date, total_weeks, sequential_gating, self_paced")
    .in("track_slug", slugs);
  return (data ?? []) as TrackDates[];
}

/** Whether this person takes `trackSlug` as a learner (enrolled, not teaching). */
export async function takesCourseAsLearner(userId: string, trackSlug: string): Promise<boolean> {
  return (await learnerCourses(userId, trackSlug)).length > 0;
}

/**
 * An upcoming or running course this person is taking as a learner, or null.
 * A weeks-open-one-at-a-time cohort (Field Ready) wins, flagged `weekGated`.
 */
export async function runningLearnerCourse(
  userId: string,
): Promise<{ slug: string; weekGated: boolean } | null> {
  const rows = (await learnerCourses(userId)).filter((t) => courseNotOver(t));
  const gated = rows.find((t) => t.sequential_gating && !t.self_paced);
  const pick = gated ?? rows[0];
  return pick ? { slug: pick.track_slug, weekGated: !!gated } : null;
}

// Practice-exam engine. The one rule that shapes everything here: the answer
// key never leaves the server. Client components receive questions through
// clientView() (answers stripped); grading happens in a server action against
// the key in the data module, which is import "server-only" guarded.

import "server-only";
import { NETWORK_PLUS_POST, type ExamQuestion } from "./network-plus-post";
import { NETWORK_PLUS_POST_V2 } from "./network-plus-post-v2";
import { SECURITY_PLUS_PRACTICE } from "./security-plus-practice";

export type Exam = typeof NETWORK_PLUS_POST;

const EXAMS: Record<string, Exam> = {
  [NETWORK_PLUS_POST.id]: NETWORK_PLUS_POST,
  [NETWORK_PLUS_POST_V2.id]: NETWORK_PLUS_POST_V2,
  [SECURITY_PLUS_PRACTICE.id]: SECURITY_PLUS_PRACTICE,
};

export function getExam(id: string): Exam | null {
  return EXAMS[id] ?? null;
}

/** Practice exams belonging to a course (via appliesToTracks). */
export function examsForTrack(trackSlug: string): Exam[] {
  return Object.values(EXAMS).filter((e) => e.appliesToTracks.includes(trackSlug));
}

export type ClientQuestion = Omit<ExamQuestion, "correct">;

/** The exam as the browser is allowed to see it. */
export function clientView(exam: Exam): {
  id: string;
  title: string;
  description: string;
  minutes: number;
  questions: ClientQuestion[];
} {
  return {
    id: exam.id,
    title: exam.title,
    description: exam.description,
    minutes: exam.minutes,
    questions: exam.questions.map(({ correct: _correct, ...q }) => q),
  };
}

export type DomainScore = { domain: string; correct: number; total: number };

/** A missed question as the learner may see it: what was asked and what they
 *  answered — NEVER the correct option. With unlimited retakes, revealing the
 *  key would turn the exam into memorization and void the readiness signal. */
export type MissedQuestion = {
  n: number;
  domain: string;
  prompt: string;
  /** The option text the learner chose; null if left blank. */
  answered: string | null;
};

/** One question as an INSTRUCTOR may see it: the prompt, what the learner
 *  picked, and the right answer. Staff-only — the learner-facing
 *  MissedQuestion deliberately withholds `correct`, and this must never be
 *  handed to a learner surface. */
export type ReviewedQuestion = {
  n: number;
  domain: string;
  prompt: string;
  answered: string | null;
  correct: string;
  isCorrect: boolean;
};

/** Full item-level review of a submitted attempt, for the instructor's
 *  per-student view. Ordered by question number. */
export function reviewAttempt(
  exam: Exam,
  answers: Record<string, number>,
): ReviewedQuestion[] {
  return exam.questions.map((q) => {
    const picked = answers[String(q.n)];
    return {
      n: q.n,
      domain: q.domain,
      prompt: q.prompt,
      answered: picked !== undefined ? q.options[picked] ?? null : null,
      correct: q.options[q.correct],
      isCorrect: picked === q.correct,
    };
  });
}

export function grade(
  exam: Exam,
  answers: Record<string, number>,
): { score: number; total: number; domainScores: DomainScore[]; missed: MissedQuestion[] } {
  let score = 0;
  const byDomain = new Map<string, DomainScore>();
  const missed: MissedQuestion[] = [];
  for (const q of exam.questions) {
    let d = byDomain.get(q.domain);
    if (!d) {
      d = { domain: q.domain, correct: 0, total: 0 };
      byDomain.set(q.domain, d);
    }
    d.total++;
    const picked = answers[String(q.n)];
    if (picked === q.correct) {
      score++;
      d.correct++;
    } else {
      missed.push({
        n: q.n,
        domain: q.domain,
        prompt: q.prompt,
        answered: picked !== undefined ? q.options[picked] ?? null : null,
      });
    }
  }
  return { score, total: exam.questions.length, domainScores: [...byDomain.values()], missed };
}

import type { Variants, Transition } from "framer-motion";

// Exponential easing — smooth deceleration like real objects
const expoOut = [0.16, 1, 0.3, 1] as const;
const quartOut = [0.25, 1, 0.5, 1] as const;
const quintOut = [0.22, 1, 0.36, 1] as const;

// ── Fade + Translate ──────────────────────────────────

export const fadeInUp: Variants = {
  hidden: { opacity: 0, y: 50 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.8, ease: expoOut } as Transition,
  },
};

export const slideInLeft: Variants = {
  hidden: { opacity: 0, x: -80 },
  visible: {
    opacity: 1,
    x: 0,
    transition: { duration: 0.9, ease: quintOut } as Transition,
  },
};

export const slideInRight: Variants = {
  hidden: { opacity: 0, x: 80 },
  visible: {
    opacity: 1,
    x: 0,
    transition: { duration: 0.9, ease: quintOut } as Transition,
  },
};

// Rise from below with scale for headlines
export const heroReveal: Variants = {
  hidden: { opacity: 0, y: 100, scale: 0.95 },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { duration: 1.2, ease: expoOut } as Transition,
  },
};

// Counter/stat punch — scales in with emphasis
export const statPunch: Variants = {
  hidden: { opacity: 0, scale: 0.5, y: 30 },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: { duration: 1, ease: expoOut } as Transition,
  },
};

// ── Containers ────────────────────────────────────────

export const staggerContainer: Variants = {
  hidden: {},
  visible: {
    transition: {
      staggerChildren: 0.12,
      delayChildren: 0.15,
    },
  },
};

export const staggerContainerSlow: Variants = {
  hidden: {},
  visible: {
    transition: {
      staggerChildren: 0.2,
      delayChildren: 0.2,
    },
  },
};

import { catalystConfig } from "./catalyst";
import { atgConfig } from "./atg";
import { forteConfig } from "./forte";
import { beyondCodeCentersConfig } from "./beyond-code-centers";
import { bgcConfig } from "./bgc";
import { marketingConfig, MARKETING_SLUG } from "./marketing";
import { fieldReadyConfig, FIELD_READY_SLUG } from "./field-ready";
import type { ProgramConfig, TrackConfig } from "./types";

const PROGRAMS: Record<string, ProgramConfig> = {
  catalyst: catalystConfig,
};

// Marketing, Forte, and BGC are intentionally NOT in PROGRAMS (so they're
// excluded from getAllPrograms and the program switcher). They're resolved
// separately: marketing → apex domain; forte → /join/forte; bgc → /join/bgc
// and the BGC camp landing pages. BGC (Black Girls Code) is its own org, not a
// Catalyst track.
//
// Beyond the Game (slug `atg`) and Beyond Code Centers are standalone programs
// — their tracks no longer aggregate into Catalyst. Registered here so they're
// switchable and own their tracks via getHomeProgramForTrack.
const SPECIAL_CONFIGS: Record<string, ProgramConfig> = {
  [MARKETING_SLUG]: marketingConfig,
  atg: atgConfig,
  forte: forteConfig,
  "beyond-code-centers": beyondCodeCentersConfig,
  bgc: bgcConfig,
  // Field Ready is standalone for the same reason Beyond the Game is: its
  // learners are not Catalyst's learners. It has no domain of its own —
  // resolveTrackProgram sends its tracks here by slug.
  [FIELD_READY_SLUG]: fieldReadyConfig,
};

/**
 * Map hostnames to program slugs.
 *
 * All programs run on bccacademy.io. The apex serves marketing for
 * unauthenticated visitors; program context is carried by the
 * program-slug cookie (set by middleware) or the program-override
 * cookie (super-admin switcher).
 */
const DOMAIN_MAP: Record<string, string> = {
  "bccacademy.io": MARKETING_SLUG,
  "www.bccacademy.io": MARKETING_SLUG,
};

/**
 * Always returns false — there are no program subdomains.
 * Kept so callers (auth callback) don't need to change.
 */
export function isKnownProgramHost(_host: string): boolean {
  return false;
}

/**
 * Resolve a hostname to a program config.
 * Falls back to Catalyst if the domain isn't recognized.
 */
export function getProgramByDomain(host: string): ProgramConfig {
  const bare = host.replace(/:\d+$/, "");
  const slug = DOMAIN_MAP[bare] ?? DOMAIN_MAP[host] ?? process.env.DEFAULT_PROGRAM ?? "catalyst";
  return SPECIAL_CONFIGS[slug] ?? PROGRAMS[slug] ?? PROGRAMS.catalyst;
}

/**
 * Get a program config by its slug.
 */
export function getProgramBySlug(slug: string): ProgramConfig {
  return SPECIAL_CONFIGS[slug] ?? PROGRAMS[slug] ?? PROGRAMS.catalyst;
}

/**
 * Get all registered program configs.
 */
export function getAllPrograms(): ProgramConfig[] {
  return Object.values(PROGRAMS);
}

/**
 * EVERY real program's config — Catalyst plus the standalone ones (Beyond the
 * Game, Forte, Beyond Code Centers, BGC). Excludes only `marketing`, the apex
 * pseudo-program with no DB row.
 *
 * getAllPrograms() returns just PROGRAMS, which today is Catalyst alone. That
 * reads as "all" at every call site and silently isn't: the outcomes engine
 * built its candidate survey list from it, so Beyond the Game's mid-program
 * survey — the one instrument on the platform that measures before and after
 * in a single response — was invisible. Its Learnings page said "no paired
 * before/after responses yet" while sitting on a +0.84 shift across every
 * statement from all four learners.
 *
 * Anything that asks "what exists across the platform" wants this one.
 */
export function getEveryProgramConfig(): ProgramConfig[] {
  return [
    ...Object.values(PROGRAMS),
    ...Object.entries(SPECIAL_CONFIGS)
      .filter(([slug]) => slug !== MARKETING_SLUG)
      .map(([, cfg]) => cfg),
  ];
}

/**
 * Full program configs for every program a new student could self-join
 * (Catalyst + Forte). Used by the "No account found" CTA list on /login
 * so a Forte invitee who lost their join link can still self-route to
 * the right program instead of accidentally signing up for Catalyst.
 */
export function getJoinablePrograms(): ProgramConfig[] {
  const joinable: ProgramConfig[] = [...Object.values(PROGRAMS)];
  for (const [slug, cfg] of Object.entries(SPECIAL_CONFIGS)) {
    if (slug !== MARKETING_SLUG) joinable.push(cfg);
  }
  return joinable;
}

/**
 * Find a track config within a program by its slug.
 */
export function getTrackBySlug(program: ProgramConfig, trackSlug: string): TrackConfig | undefined {
  return program.tracks.find((t) => t.slug === trackSlug);
}

/**
 * Find the "home" program for a track — the original config the track was
 * authored in. Catalyst spreads tracks from other programs (ATG, Forge,
 * Forte), so a track resolved via Catalyst doesn't tell you where it
 * actually lives.
 *
 * Walks the special configs first (forte) and then registered programs,
 * skipping Catalyst itself — those are the underlying owners. Falls back
 * to Catalyst when nothing else claims the track (e.g. additionalTracks
 * that only live in Catalyst's config).
 */
export function getHomeProgramForTrack(trackSlug: string): ProgramConfig | undefined {
  for (const cfg of Object.values(SPECIAL_CONFIGS)) {
    if (cfg.slug === MARKETING_SLUG) continue;
    if (cfg.tracks.some((t) => t.slug === trackSlug)) return cfg;
  }
  for (const cfg of Object.values(PROGRAMS)) {
    if (cfg.slug === "catalyst") continue;
    if (cfg.tracks.some((t) => t.slug === trackSlug)) return cfg;
  }
  return PROGRAMS.catalyst?.tracks.some((t) => t.slug === trackSlug)
    ? PROGRAMS.catalyst
    : undefined;
}

/**
 * Returns true when the slug is a known TS-config program (PROGRAMS or
 * SPECIAL_CONFIGS). Used by resolveBaseProgram() to decide whether to
 * fall through to the DB lookup for is_dynamic programs.
 */
export function hasTsConfigSlug(slug: string): boolean {
  return slug in PROGRAMS || slug in SPECIAL_CONFIGS;
}

export type { ProgramConfig, TrackConfig, WeekConfig, SessionInfo } from "./types";

// Pre-launch kill-switch for the AI Tutor. Flip back to `false` once we're
// ready to re-enable per-program tutor configs. While true: the
// /dashboard/tutor route 404s, /api/tutor refuses requests, the dashboard
// nav hides the link, and the welcome email omits the tutor blurb.
export const TUTOR_DISABLED_PRELAUNCH = false;

export function isTutorAvailable(program: ProgramConfig): boolean {
  if (TUTOR_DISABLED_PRELAUNCH) return false;
  // Opt-in: a program only gets the tutor if it explicitly enables it with a
  // tutorConfig. This keeps the unguarded generic prompt from reaching programs
  // that haven't been given (and tested with) their own system prompt — only
  // Forte/Upskill Bahamas is enabled today.
  return program.tutorConfig?.enabled === true;
}
